/* ──────────────────────────────────────────────────────────────────────────
   learnroman-emma.js — „Η Έμμα στη Θεσσαλονίκη" · Zielsprache GRIECHISCH
   Muttersprachen de + es + en (na/tr/teaser als {de, es, en}). Fester Inhalt.
   Bauplan wie learnroman-lukas.js (Leo, 15.10.2026): Teil I = A1-Szenen des
   Geführten Gesprächs (lernpfad-daten-el.js a1.*), Teil II = A2 (Ostern),
   Epilog = griechische Prosa ohne Brücke.
   NEU für Griechisch: Feld `lt` = lateinische Umschrift der Zeile (Teil I immer,
   Teil II bei neuen Wörtern) — der Raum zeigt sie klein unter dem Griechischen.
   Motor: die Steuernummer (ΑΦΜ) bis 31. Oktober.
   ────────────────────────────────────────────────────────────────────────── */
/* ──────────────────────────────────────────────────────────────────────────
   lr-el/emma-1.js — „Η Έμμα στη Θεσσαλονίκη" · Teil I · fundament
   Zielsprache Griechisch · Muttersprachen de (Hochdeutsch), es (castellano
   de España), en (British). Stationen 1–10 = die zehn A1-Szenen.
   N(de, es, en) = Erzählung in der Muttersprache · kein Audio
   Z(el, de, es, en, lt) = Griechisch + Brücken + Umschrift (lt, Teil I immer)
   Motor: das ΑΦΜ (Steuernummer) bis Ende Oktober — dafür der Mietvertrag
   mit Unterschrift und ΑΦΜ der Vermieterin, κυρία Βούλα, die in Βέροια lebt.
   ────────────────────────────────────────────────────────────────────────── */
(function (w) {
  var K = w.__LR_PARTS_EMMA = w.__LR_PARTS_EMMA || {};
  function N(de, es, en) { return { na: { de: de, es: es, en: en } }; }
  function Z(z, de, es, en, lt) { var o = { z: z }; if (de) o.tr = { de: de, es: es, en: en }; if (lt) o.lt = lt; return o; }
  function P(p) { return { p: p }; }
  function S(level, n, thema, title, tde, tes, ten, body) { return { level: level, n: n, thema: thema, title: title, teaser: { de: tde, es: tes, en: ten }, body: body }; }

  K.teil1 = [

  // ── Station 1 · TAXI ────────────────────────────────────────────────
  S('fundament', 1, 'taxi', "Είστε ελεύθερος;",
    "Emma landet in Thessaloniki, ein Taxifahrer erklärt ihr das Leben anhand von PAOK — und eine E-Mail verlangt drei Buchstaben.",
    "Emma aterriza en Tesalónica, un taxista le explica la vida a través del PAOK — y un correo le exige tres letras.",
    "Emma lands in Thessaloniki, a taxi driver explains life to her by way of PAOK — and an email demands three letters.",
  [
    N("Flughafen Thessaloniki »Makedonia«, Dienstag, der achte Oktober, vier Uhr nachmittags. Die Glastüren gehen auf, und die Luft draußen riecht nach Meer, Kerosin und warmem Asphalt.",
      "Aeropuerto de Tesalónica «Makedonia», martes 8 de octubre, las cuatro de la tarde. Las puertas de cristal se abren y el aire de fuera huele a mar, a queroseno y a asfalto caliente.",
      "Thessaloniki Airport “Makedonia”, Tuesday the eighth of October, four in the afternoon. The glass doors slide open, and the air outside smells of sea, kerosene and warm tarmac."),
    N("Emma Novak, siebenundzwanzig, Archäologin aus Wien. Ein Jahr Forschung an der Aristoteles-Universität, ein Rollkoffer, ein Rucksack. Altgriechisch liest sie seit dem Studium. Leider hat Platon nie ein Taxi gerufen.",
      "Emma Novak, veintisiete años, arqueóloga de Viena. Un año de investigación en la Universidad Aristóteles, una maleta con ruedas, una mochila. Lee griego antiguo desde la carrera. Por desgracia, Platón nunca pidió un taxi.",
      "Emma Novak, twenty-seven, an archaeologist from Vienna. A year of research at the Aristotle University, a wheelie case, a rucksack. She has read Ancient Greek since university. Sadly, Plato never hailed a taxi."),
    Z("ΤΑΞΙ", "Taxi", "Taxi", "Taxi", "TAXÍ"),
    Z("Τα ταξί είναι μπλε και άσπρα. Είναι πολλά.", "Die Taxis sind blau und weiß. Es sind viele.", "Los taxis son azules y blancos. Hay muchos.", "The taxis are blue and white. There are lots of them.", "Ta taxí íne ble ke áspra. Íne pollá."),
    N("Am ersten lehnt ein Mann um die fünfzig, Bauch, Schnurrbart, einen schwarz-weißen Schal um den Hals — bei vierundzwanzig Grad. Am Rückspiegel baumelt ein Doppeladler. Emma atmet ein. Den ersten Satz hat sie im Flugzeug geübt, zwölfmal, lautlos.",
      "En el primero está apoyado un hombre de unos cincuenta, barriga, bigote y una bufanda blanca y negra al cuello — con veinticuatro grados. Del retrovisor cuelga un águila bicéfala. Emma respira hondo. La primera frase la ha practicado en el avión, doce veces, sin voz.",
      "Leaning against the first one is a man of about fifty, belly, moustache, a black-and-white scarf round his neck — in twenty-four degrees. A double-headed eagle dangles from the mirror. Emma takes a breath. She practised the first sentence on the plane, twelve times, silently."),
    Z("—Καλησπέρα. Είστε ελεύθερος;", "Guten Tag. Sind Sie frei?", "Buenas tardes. ¿Está libre?", "Good afternoon. Are you free?", "—Kalispéra. Íste eléftheros?"),
    Z("—Ναι.", "Ja.", "Sí.", "Yes.", "—Ne."),
    N("Emma bleibt stehen. Ne? Ihr Wiener Ohr hört »nee«. Nein. Aber der Mann öffnet schon den Kofferraum und winkt.",
      "Emma se queda quieta. ¿Ne? Su oído vienés oye «nee», que en alemán es «no». Pero el hombre ya abre el maletero y le hace señas.",
      "Emma stops. Ne? Her Viennese ear hears “nee” — German for no. But the man is already opening the boot and waving her over."),
    Z("—Ναι, ναι! Ελάτε. Έχετε βαλίτσα;", "Ja, ja! Kommen Sie. Haben Sie einen Koffer?", "¡Sí, sí! Venga. ¿Lleva maleta?", "Yes, yes! Come on. Have you got a suitcase?", "—Ne, ne! Eláte. Échete valítsa?"),
    Z("—Ναι, μία. Και ένα σακίδιο.", "Ja, einen. Und einen Rucksack.", "Sí, una. Y una mochila.", "Yes, one. And a rucksack.", "—Ne, mía. Ke éna sakídio."),
    N("Ne. Jetzt hat sie es selbst gesagt, und es heißt ja. Ihr Kopf zuckt trotzdem. Ein Jahr, schätzt sie, bis er damit aufhört.",
      "Ne. Ahora lo ha dicho ella misma, y significa sí. Aun así, la cabeza le da un respingo. Un año, calcula, hasta que deje de hacerlo.",
      "Ne. Now she has said it herself, and it means yes. Her head still twitches. A year, she reckons, before it stops."),
    Z("—Πού πάμε;", "Wohin fahren wir?", "¿Adónde vamos?", "Where are we going?", "—Poú páme?"),
    Z("—Στην Άνω Πόλη, παρακαλώ. Οδός Ολυμπιάδος, δεκατέσσερα.", "In die Oberstadt, bitte. Olympiados-Straße vierzehn.", "A la Ciudad Alta, por favor. Calle Olympiados, número catorce.", "To the Upper Town, please. Olympiados Street, number fourteen.", "—Stin Áno Póli, parakaló. Odós Olimbiádos, dekatéssera."),
    N("Und los. Die Küstenstraße, rechts das Meer, flach und silbern. Der Fahrer lenkt mit einer Hand. Mit der anderen erklärt er etwas — dem Meer, der Stadt, Emma.",
      "Y en marcha. La carretera de la costa, a la derecha el mar, plano y plateado. El taxista conduce con una mano. Con la otra le explica algo al mar, a la ciudad, a Emma.",
      "And off they go. The coast road, the sea on the right, flat and silver. The driver steers with one hand. With the other he explains something — to the sea, to the city, to Emma."),
    Z("—Από πού είστε; Γερμανίδα;", "Woher sind Sie? Deutsche?", "¿De dónde es usted? ¿Alemana?", "Where are you from? German?", "—Apó poú íste? Yermanída?"),
    Z("—Όχι. Είμαι από την Αυστρία. Από τη Βιέννη.", "Nein. Ich bin aus Österreich. Aus Wien.", "No. Soy de Austria. De Viena.", "No. I'm from Austria. From Vienna.", "—Óchi. Íme apó tin Afstría. Apó ti Viénni."),
    Z("—Ωραία πόλη! Εγώ είμαι ο Στέλιος.", "Schöne Stadt! Ich bin Stelios.", "¡Bonita ciudad! Yo soy Stelios.", "Lovely city! I'm Stelios.", "—Oréa póli! Egó íme o Stélios."),
    Z("—Με λένε Έμμα.", "Ich heiße Emma.", "Me llamo Emma.", "My name is Emma.", "—Me léne Émma."),
    N("Stelios tippt auf den Doppeladler am Spiegel. Dann auf sein Herz. Dann wieder auf den Adler.",
      "Stelios da un toquecito al águila del retrovisor. Luego a su corazón. Luego otra vez al águila.",
      "Stelios taps the eagle on the mirror. Then his heart. Then the eagle again."),
    Z("—ΠΑΟΚ. Ο ΠΑΟΚ είναι σαν τη ζωή. Πονάει. Αλλά τον αγαπάς.", "PAOK. PAOK ist wie das Leben. Es tut weh. Aber du liebst ihn.", "El PAOK. El PAOK es como la vida. Duele. Pero lo quieres.", "PAOK. PAOK is like life. It hurts. But you love it.", "—PAOK. O PAOK íne san ti zoí. Ponái. Allá ton agapás."),
    N("Ζωή, Leben, kennt Emma aus Aristoteles. Dass das Wort in Thessaloniki neben Fußball im Taxi sitzt, ist neu. Dann vibriert das Handy: eine E-Mail der Personalabteilung. »Damit wir Ihr Gehalt Ende Oktober überweisen können, benötigen wir Ihre griechische Steuernummer, das ΑΦΜ. Sie erhalten es beim Finanzamt — mit Reisepass und Mietvertrag.«",
      "Ζωή, vida, Emma la conoce de Aristóteles. Que en Tesalónica esa palabra vaya en taxi junto al fútbol es nuevo. Entonces vibra el móvil: un correo de Recursos Humanos. «Para pagarle el sueldo a finales de octubre necesitamos su número fiscal griego, el ΑΦΜ. Lo obtendrá en Hacienda, con pasaporte y contrato de alquiler.»",
      "Ζωή, life, Emma knows from Aristotle. That in Thessaloniki the word rides in a taxi next to football is new. Then her phone buzzes: an email from Human Resources. “So that we can pay your salary at the end of October, we need your Greek tax number, the ΑΦΜ. You can get it at the tax office — with your passport and your rental contract.”"),
    Z("—Στέλιο, τι είναι το ΑΦΜ;", "Stelios, was ist das AFM?", "Stelios, ¿qué es el AFM?", "Stelios, what's the AFM?", "—Stélio, ti íne to afimí?"),
    Z("—Το ΑΦΜ; Ένας αριθμός. Χωρίς ΑΦΜ δεν είσαι κανένας.", "Das AFM? Eine Nummer. Ohne AFM bist du niemand.", "¿El AFM? Un número. Sin AFM no eres nadie.", "The AFM? A number. Without an AFM you're nobody.", "—To afimí? Énas arithmós. Chorís afimí den íse kanénas."),
    N("Er sagt nicht A-F-M. Er sagt »afimí«, in einem Atemzug. Niemand. Emma muss an Odysseus denken, der dem Zyklopen erzählt, er heiße Niemand. Bei Odysseus hat das funktioniert. Bei einer Personalabteilung wird es das nicht.",
      "No dice A-F-M. Dice «afimí», de un tirón. Nadie. Emma piensa en Ulises, que le dice al cíclope que se llama Nadie. A Ulises le funcionó. Con un departamento de personal no va a funcionar.",
      "He doesn't say A-F-M. He says “afimí”, in one breath. Nobody. Emma thinks of Odysseus telling the Cyclops his name is Nobody. It worked for Odysseus. It won't work with an HR department."),
    N("Die Straßen werden steil, dann eng, dann sehr eng. Weiße Häuser mit Holzerkern, Katzen auf jeder Mauer, unten die ganze Stadt und das Meer.",
      "Las calles se vuelven empinadas, luego estrechas, luego muy estrechas. Casas blancas con miradores de madera, gatos en cada muro, abajo toda la ciudad y el mar.",
      "The streets get steep, then narrow, then very narrow. White houses with wooden bay windows, cats on every wall, and below, the whole city and the sea."),
    Z("—Εδώ είναι. Πόσο κάνει;", "Hier ist es. Wie viel macht das?", "Es aquí. ¿Cuánto es?", "This is it. How much is it?", "—Edó íne. Póso káni?"),
    Z("—Είκοσι πέντε ευρώ.", "Fünfundzwanzig Euro.", "Veinticinco euros.", "Twenty-five euros.", "—Íkosi pénde evró."),
    Z("—Ορίστε. Κρατήστε τα ρέστα.", "Bitte schön. Behalten Sie den Rest.", "Tenga. Quédese con la vuelta.", "Here you are. Keep the change.", "—Oríste. Kratíste ta résta."),
    Z("—Να 'σαι καλά, Βιεννέζα! Και… ΠΑΟΚ!", "Mach's gut, Wienerin! Und … PAOK!", "¡Cuídate, vienesa! Y… ¡PAOK!", "Take care, Viennese! And… PAOK!", "—Na 'se kalá, Vienéza! Ke… PAOK!"),
    N("Im Erdgeschoss geht eine Tür auf. Eine kleine Frau um die siebzig, Schürze, Kochlöffel, mustert Emma von oben bis unten und bleibt an ihren Handgelenken hängen. Zu dünn, sagen ihre Augen.",
      "En la planta baja se abre una puerta. Una mujer bajita de unos setenta, delantal, cuchara de palo, mira a Emma de arriba abajo y se detiene en sus muñecas. Demasiado delgada, dicen sus ojos.",
      "On the ground floor a door opens. A small woman of about seventy, apron, wooden spoon, looks Emma up and down and stops at her wrists. Too thin, say her eyes."),
    Z("—Εσύ είσαι η Έμμα; Είμαι η κυρία Ρούλα. Πεινάς;", "Bist du Emma? Ich bin Frau Roula. Hast du Hunger?", "¿Tú eres Emma? Soy la señora Rula. ¿Tienes hambre?", "Are you Emma? I'm Mrs Roula. Are you hungry?", "—Esí íse i Émma? Íme i kiría Roúla. Pinás?"),
    Z("—Όχι, ευχαριστώ.", "Nein, danke.", "No, gracias.", "No, thank you.", "—Óchi, efcharistó."),
    N("Zehn Minuten später sitzt Emma an Frau Roulas Küchentisch vor einem Teller gefüllter Paprika. In diesem Haus heißt nein offenbar ja. Und ja sowieso.",
      "Diez minutos después, Emma está sentada a la mesa de la cocina de la señora Rula, delante de un plato de pimientos rellenos. En esta casa, por lo visto, «no» significa «sí». Y «sí», también.",
      "Ten minutes later Emma is sitting at Mrs Roula's kitchen table in front of a plate of stuffed peppers. In this house, apparently, no means yes. And yes means yes anyway."),
    Z("ΑΦΜ.", "AFM. Die Steuernummer.", "AFM. El número fiscal.", "AFM. The tax number.", "Afimí.")
  ]),

  // ── Station 2 · CAFÉ ────────────────────────────────────────────────
  S('fundament', 2, 'cafe', "Μέτριο με γάλα",
    "Ein Frappé im Kafeneio an der Ecke, Herr Thanasis lehrt Geduld — und Marina findet die leere Zeile im Mietvertrag.",
    "Un frapé en el kafeneio de la esquina, el señor Thanasis enseña paciencia — y Marina encuentra la línea vacía del contrato.",
    "A frappé at the kafeneio on the corner, Mr Thanasis teaches patience — and Marina finds the empty line in the contract.",
  [
    N("Mittwochmorgen. In Emmas Küche gibt es keine Kaffeemaschine. Nur ein Briki, ein Messingkännchen mit langem Stiel, und keine Ahnung, wie man es benutzt. An der Ecke: vier Tische auf dem Gehsteig, blaue Stühle, ein Fernseher ohne Ton.",
      "Miércoles por la mañana. En la cocina de Emma no hay cafetera. Solo un briki, un cacito de latón con mango largo, y ni idea de cómo se usa. En la esquina: cuatro mesas en la acera, sillas azules, una tele sin sonido.",
      "Wednesday morning. There's no coffee machine in Emma's kitchen. Just a briki, a little brass pot with a long handle, and no idea how to use it. On the corner: four tables on the pavement, blue chairs, a television with no sound."),
    Z("ΚΑΦΕΝΕΙΟ «Ο ΘΑΝΑΣΗΣ»", "Kafeneio »Thanasis«", "Kafeneio «Thanasis»", "Kafeneio “Thanasis”", "KAFENÍO «O THANÁSIS»"),
    N("Hinter der Theke sitzt ein alter Mann mit weißem Haar. Durch seine Finger klicken Bernsteinperlen: ein Kombolói.",
      "Detrás de la barra hay un anciano de pelo blanco. Entre sus dedos chasquean unas cuentas de ámbar: un kombolói.",
      "Behind the counter sits an old man with white hair. Amber beads click through his fingers: a komboloi."),
    Z("—Καλημέρα!", "Guten Morgen!", "¡Buenos días!", "Good morning!", "—Kaliméra!"),
    Z("—Καλημέρα, κοπέλα μου. Τι θα πάρεις;", "Guten Morgen, meine Liebe. Was nimmst du?", "Buenos días, hija. ¿Qué vas a tomar?", "Morning, love. What'll you have?", "—Kaliméra, kopéla mou. Ti tha páris?"),
    Z("—Έναν καφέ, παρακαλώ.", "Einen Kaffee, bitte.", "Un café, por favor.", "A coffee, please.", "—Énan kafé, parakaló."),
    Z("—Τι καφέ; Ελληνικό; Φραπέ; Φρέντο;", "Was für einen Kaffee? Griechischen? Frappé? Freddo?", "¿Qué café? ¿Griego? ¿Frapé? ¿Freddo?", "What kind of coffee? Greek? Frappé? Freddo?", "—Ti kafé? Ellinikó? Frapé? Fréndo?"),
    N("Drei Kaffees, und jeder klingt wie eine kleine Gottheit. Emma zeigt auf das Glas am Nebentisch: hoch, braun, oben Schaum wie eine Wolke.",
      "Tres cafés, y cada uno suena a deidad menor. Emma señala el vaso de la mesa de al lado: alto, marrón, con espuma como una nube.",
      "Three coffees, and each one sounds like a minor deity. Emma points at the glass on the next table: tall, brown, with foam on top like a cloud."),
    Z("—Αυτό. Έναν φραπέ.", "Den da. Einen Frappé.", "Ese. Un frapé.", "That one. A frappé.", "—Aftó. Énan frapé."),
    Z("—Σκέτο, μέτριο ή γλυκό;", "Ohne Zucker, mittel oder süß?", "¿Sin azúcar, con poco o dulce?", "No sugar, medium or sweet?", "—Skéto, métrio i glikó?"),
    Z("—Μέτριο. Με γάλα.", "Mittel. Mit Milch.", "Con poco azúcar. Con leche.", "Medium. With milk.", "—Métrio. Me gála."),
    Z("—Για εδώ ή πακέτο;", "Für hier oder zum Mitnehmen?", "¿Para tomar aquí o para llevar?", "For here or to take away?", "—Gia edó i pakéto?"),
    Z("—Για εδώ.", "Für hier.", "Para tomar aquí.", "For here.", "—Gia edó."),
    N("Herr Thanasis steht auf. Langsam. Er wählt ein Glas. Er betrachtet das Glas. Um elf ist Emma hier mit Marina verabredet, einer Kollegin vom Institut. Es ist zehn vor elf.",
      "El señor Thanasis se levanta. Despacio. Elige un vaso. Contempla el vaso. A las once Emma ha quedado aquí con Marina, una compañera del instituto. Son las once menos diez.",
      "Mr Thanasis gets up. Slowly. He chooses a glass. He contemplates the glass. Emma is meeting Marina here at eleven, a colleague from the institute. It's ten to eleven."),
    Z("—Συγγνώμη… βιάζομαι λίγο.", "Entschuldigung … ich habe es ein bisschen eilig.", "Perdone… tengo un poco de prisa.", "Sorry… I'm in a bit of a hurry.", "—Signómi… viázome lígo."),
    Z("—Σιγά-σιγά, κοπέλα μου. Σιγά-σιγά.", "Langsam, langsam, meine Liebe.", "Despacito, hija. Despacito.", "Slowly, slowly, love. Slowly.", "—Sigá-sigá, kopéla mou. Sigá-sigá."),
    N("Das Kombolói klickt. Als der Frappé auf dem Tisch steht, ist es elf. Marina kommt um zwanzig nach, Sonnenbrille im Haar, zwei Mappen unterm Arm, als wäre sie pünktlich.",
      "El kombolói chasquea. Cuando el frapé llega a la mesa, son las once. Marina aparece a y veinte, gafas de sol en el pelo, dos carpetas bajo el brazo, como si llegara puntual.",
      "The komboloi clicks. By the time the frappé is on the table, it's eleven. Marina turns up at twenty past, sunglasses in her hair, two folders under her arm, as if she were on time."),
    Z("—Γεια σου, Έμμα! Τι κάνεις;", "Hallo, Emma! Wie geht's?", "¡Hola, Emma! ¿Qué tal?", "Hi, Emma! How are you?", "—Giá sou, Émma! Ti kánis?"),
    Z("—Καλά, ευχαριστώ. Κι εσύ;", "Gut, danke. Und dir?", "Bien, gracias. ¿Y tú?", "Fine, thanks. And you?", "—Kalá, efcharistó. Ki esí?"),
    Z("—Κυρ-Θανάση, ένα φρέντο εσπρέσο, σκέτο!", "Herr Thanasis, einen Freddo Espresso, ohne Zucker!", "¡Señor Thanasis, un freddo espresso, sin azúcar!", "Mr Thanasis, a freddo espresso, no sugar!", "—Kir-Thanási, éna fréndo espréso, skéto!"),
    N("Neunzig Sekunden. Sigá-sigá, lernt Emma, gilt nicht für Stammgäste. Sie zeigt Marina die E-Mail und den Mietvertrag.",
      "Noventa segundos. Despacito, aprende Emma, no vale para los clientes de toda la vida. Le enseña a Marina el correo y el contrato.",
      "Ninety seconds. Slowly-slowly, Emma learns, doesn't apply to regulars. She shows Marina the email and the rental contract."),
    Z("—Για το ΑΦΜ χρειάζεσαι δύο πράγματα. Το διαβατήριο και το μισθωτήριο.", "Für das AFM brauchst du zwei Dinge. Den Pass und den Mietvertrag.", "Para el AFM necesitas dos cosas. El pasaporte y el contrato de alquiler.", "For the AFM you need two things. Your passport and the rental contract.", "—Gia to afimí chriázese dío prágmata. To diavatírio ke to misthotírio."),
    Z("—Το μισθωτήριο το έχω. Εδώ.", "Den Mietvertrag habe ich. Hier.", "El contrato lo tengo. Aquí.", "I've got the contract. Here.", "—To misthotírio to écho. Edó."),
    N("Marina blättert. Seite drei. Sie tippt mit dem Fingernagel auf eine leere Linie.",
      "Marina hojea. Página tres. Da golpecitos con la uña en una línea vacía.",
      "Marina leafs through it. Page three. She taps an empty line with her fingernail."),
    Z("—Πού είναι η υπογραφή της κυρίας Βούλας; Και το ΑΦΜ της;", "Wo ist die Unterschrift von Frau Voula? Und ihr AFM?", "¿Dónde está la firma de la señora Vula? ¿Y su AFM?", "Where's Mrs Voula's signature? And her AFM?", "—Poú íne i ipografí tis kirías Voúlas? Ke to afimí tis?"),
    N("Frau Voula Karagianni, achtundsiebzig, Eigentümerin der Wohnung. Emma hat sie nie gesehen. Die Schlüssel kamen von Frau Roula. Frau Voula lebt in Veria bei ihrer Schwester. »Voula macht kein E-Mail«, hat Frau Roula gesagt. Wie man sagt: Voula raucht nicht.",
      "La señora Vula Karagianni, setenta y ocho años, dueña del piso. Emma nunca la ha visto. Las llaves se las dio la señora Rula. La señora Vula vive en Veria con su hermana. «Vula no hace e-mail», dijo la señora Rula. Como quien dice: Vula no fuma.",
      "Mrs Voula Karagianni, seventy-eight, owner of the flat. Emma has never seen her. The keys came from Mrs Roula. Mrs Voula lives in Veria with her sister. “Voula doesn't do email,” Mrs Roula said. The way you'd say: Voula doesn't smoke."),
    Z("—Έχεις το τηλέφωνό της;", "Hast du ihre Telefonnummer?", "¿Tienes su teléfono?", "Have you got her phone number?", "—Échis to tiléfonó tis?"),
    Z("—Όχι.", "Nein.", "No.", "No.", "—Óchi."),
    N("Emma sagt es mit dem Mund. Marina zeigt ihr, wie man es richtig sagt: Kinn hoch, Augenbrauen hoch, ein kleines Klicken mit der Zunge. Tsk. Kein Wort, ein ganzes Nein. Emma probiert es. Marina lacht so laut, dass Herr Thanasis aufschaut.",
      "Emma lo dice con la boca. Marina le enseña a decirlo bien: barbilla arriba, cejas arriba, un chasquido de lengua. Tsk. Ni una palabra, un «no» entero. Emma lo intenta. Marina se ríe tan fuerte que el señor Thanasis levanta la vista.",
      "Emma says it with her mouth. Marina shows her how to say it properly: chin up, eyebrows up, a little click of the tongue. Tsk. Not a word — a whole no. Emma tries it. Marina laughs so loudly that Mr Thanasis looks up."),
    Z("—Έτοιμο. Έχεις ραντεβού στην εφορία. Πέμπτη, είκοσι τέσσερις Οκτωβρίου, στις εννιά.", "Fertig. Du hast einen Termin beim Finanzamt. Donnerstag, vierundzwanzigster Oktober, um neun.", "Listo. Tienes cita en Hacienda. Jueves, 24 de octubre, a las nueve.", "Done. You've got an appointment at the tax office. Thursday the twenty-fourth of October, at nine.", "—Étimo. Échis randevoú stin eforía. Pémbti, íkosi tésseris Oktovríou, stis enniá."),
    Z("—Και η κυρία Βούλα;", "Und Frau Voula?", "¿Y la señora Vula?", "And Mrs Voula?", "—Ke i kiría Voúla?"),
    Z("—Η κυρία Βούλα είναι το πρόβλημά σου. Καλή τύχη!", "Frau Voula ist dein Problem. Viel Glück!", "La señora Vula es problema tuyo. ¡Suerte!", "Mrs Voula is your problem. Good luck!", "—I kiría Voúla íne to próvlimá sou. Kalí tíchi!"),
    N("Herr Thanasis stellt ungefragt ein Tellerchen mit Sesamkringeln auf den Tisch.",
      "El señor Thanasis, sin que nadie se lo pida, deja en la mesa un platito de rosquillas de sésamo.",
      "Without being asked, Mr Thanasis puts a little plate of sesame biscuits on the table."),
    Z("—Φάε. Είσαι πολύ αδύνατη.", "Iss. Du bist sehr dünn.", "Come. Estás muy delgada.", "Eat. You're very thin.", "—Fáe. Íse polí adínati.")
  ]),

  // ── Station 3 · EINKAUFEN ───────────────────────────────────────────
  S('fundament', 3, 'einkaufen', "Ένα κιλό μήλα",
    "Samstag ist Laïkí: Äpfel, Feta, Kastanien als Geschenk — und eine Obstverkäuferin, die Frau Voula aus der Kirche kennt.",
    "El sábado hay laikí: manzanas, feta, castañas de regalo — y una frutera que conoce a la señora Vula de la iglesia.",
    "Saturday means the laiki: apples, feta, chestnuts as a present — and a fruit seller who knows Mrs Voula from church.",
  [
    N("Samstag, acht Uhr. Frau Roula klopft. Sie hat einen karierten Einkaufstrolley dabei und einen Gesichtsausdruck, der keinen Widerspruch duldet.",
      "Sábado, las ocho. La señora Rula llama a la puerta. Trae un carrito de la compra de cuadros y una cara que no admite réplica.",
      "Saturday, eight o'clock. Mrs Roula knocks. She has a tartan shopping trolley with her and an expression that brooks no argument."),
    Z("—Σήμερα είναι Σάββατο. Το Σάββατο έχει λαϊκή. Πάμε!", "Heute ist Samstag. Samstags ist Markt. Gehen wir!", "Hoy es sábado. Los sábados hay mercadillo. ¡Vamos!", "It's Saturday today. On Saturdays there's the street market. Let's go!", "—Símera íne Sávvato. To Sávvato échi laikí. Páme!"),
    N("Die Laïkí, der Volksmarkt: eine ganze Straße, für Autos gesperrt, Stände unter gestreiften Planen. Und alle rufen. Nicht wütend — sie singen ihre Preise.",
      "La laikí, el mercado del pueblo: una calle entera cortada al tráfico, puestos bajo toldos de rayas. Y todos gritan. No de enfado: cantan sus precios.",
      "The laiki, the people's market: a whole street closed to cars, stalls under striped awnings. And everyone is shouting. Not angrily — they're singing their prices."),
    Z("—Ντομάτες! Φρέσκιες ντομάτες! Ένα ευρώ το κιλό!", "Tomaten! Frische Tomaten! Ein Euro das Kilo!", "¡Tomates! ¡Tomates frescos! ¡A euro el kilo!", "Tomatoes! Fresh tomatoes! One euro a kilo!", "—Domátes! Fréskies domátes! Éna evró to kiló!"),
    N("Frau Roula verschwindet im Gedränge Richtung Fisch. Emma bekommt einen Zettel, in großen Buchstaben, wie für ein Kind.",
      "La señora Rula desaparece entre la gente rumbo al pescado. A Emma le da una nota, con letras grandes, como para una niña.",
      "Mrs Roula disappears into the crowd in the direction of the fish. Emma is handed a note, in big letters, as if for a child."),
    Z("1 κιλό μήλα. ½ κιλό φέτα.", "1 Kilo Äpfel. ½ Kilo Feta.", "1 kilo de manzanas. ½ kilo de feta.", "1 kilo of apples. ½ kilo of feta.", "1 kiló míla. ½ kiló féta."),
    N("Am Obststand: eine Frau mit roten Wangen und Wollmütze, trotz Sonne, mit einer Stimme bis zum Hafen.",
      "En el puesto de fruta: una mujer de mejillas rojas y gorro de lana, a pesar del sol, con una voz que llega hasta el puerto.",
      "At the fruit stall: a woman with red cheeks and a woolly hat, despite the sun, with a voice that carries to the harbour."),
    Z("—Έλα, κούκλα μου! Τι θέλεις;", "Komm, Püppchen! Was möchtest du?", "¡Ven, guapa! ¿Qué quieres?", "Come on, sweetheart! What would you like?", "—Éla, koúkla mou! Ti thélis?"),
    N("Koúkla: Puppe. Auf der Laïkí ist jede Frau eine Puppe und jeder Mann ein Chef.",
      "Koúkla: muñeca. En la laikí, toda mujer es una muñeca y todo hombre es jefe.",
      "Koukla: doll. At the laiki every woman is a doll and every man is the boss."),
    Z("—Ένα κιλό μήλα, παρακαλώ.", "Ein Kilo Äpfel, bitte.", "Un kilo de manzanas, por favor.", "A kilo of apples, please.", "—Éna kiló míla, parakaló."),
    Z("—Κόκκινα ή πράσινα;", "Rote oder grüne?", "¿Rojas o verdes?", "Red or green?", "—Kókkina i prásina?"),
    Z("—Κόκκινα. Πόσο κάνει;", "Rote. Wie viel macht das?", "Rojas. ¿Cuánto es?", "Red. How much is that?", "—Kókkina. Póso káni?"),
    Z("—Ένα ευρώ και πενήντα. Τίποτα άλλο;", "Ein Euro fünfzig. Sonst noch etwas?", "Un euro cincuenta. ¿Algo más?", "One euro fifty. Anything else?", "—Éna evró ke penínda. Típota állo?"),
    Z("—Και μισό κιλό φέτα.", "Und ein halbes Kilo Feta.", "Y medio kilo de feta.", "And half a kilo of feta.", "—Ke misó kiló féta."),
    Z("—Φέτα; Η φέτα είναι εκεί, στον Μανώλη. Πες ότι σε στέλνει η Δέσποινα.", "Feta? Den Feta gibt es da drüben, bei Manolis. Sag, dass Despina dich schickt.", "¿Feta? El feta está ahí, donde Manolis. Dile que te manda Despina.", "Feta? The feta's over there, at Manolis's. Tell him Despina sent you.", "—Féta? I féta íne ekí, ston Manóli. Pes óti se stélni i Déspina."),
    N("Dann legt Frau Despina zwei Mandarinen in die Tüte. Und eine Handvoll Kastanien. Emma will protestieren.",
      "Luego la señora Despina mete dos mandarinas en la bolsa. Y un puñado de castañas. Emma quiere protestar.",
      "Then Mrs Despina pops two mandarins into the bag. And a handful of chestnuts. Emma tries to protest."),
    Z("—Δώρο. Είσαι πολύ αδύνατη. Πού μένεις, κούκλα μου;", "Geschenk. Du bist sehr dünn. Wo wohnst du, Püppchen?", "Regalo. Estás muy delgada. ¿Dónde vives, guapa?", "A present. You're very thin. Where do you live, sweetheart?", "—Dóro. Íse polí adínati. Poú ménis, koúkla mou?"),
    Z("—Στην Άνω Πόλη. Στο σπίτι της κυρίας Βούλας Καραγιάννη.", "In der Oberstadt. Im Haus von Frau Voula Karagianni.", "En la Ciudad Alta. En la casa de la señora Vula Karagianni.", "In the Upper Town. In Mrs Voula Karagianni's house.", "—Stin Áno Póli. Sto spíti tis kirías Voúlas Karagiánni."),
    Z("—Της Βούλας; Της Βούλας από την εκκλησία; Την ξέρω!", "Von Voula? Von Voula aus der Kirche? Die kenne ich!", "¿De Vula? ¿De Vula la de la iglesia? ¡La conozco!", "Voula's? Voula from church? I know her!", "—Tis Voúlas? Tis Voúlas apó tin ekklisía? Tin xéro!"),
    N("Emma erklärt. Das Finanzamt, die Unterschrift, der Donnerstag. Ihr Griechisch reicht für zwölf Wörter, ihre Hände erklären den Rest. Frau Despina versteht alles. Marktfrauen verstehen immer alles.",
      "Emma se lo explica. Hacienda, la firma, el jueves. Su griego da para doce palabras; las manos explican el resto. La señora Despina lo entiende todo. Las del mercado siempre lo entienden todo.",
      "Emma explains. The tax office, the signature, the Thursday. Her Greek stretches to twelve words; her hands explain the rest. Mrs Despina understands everything. Market women always understand everything."),
    Z("—Η Βούλα δεν σηκώνει ποτέ το τηλέφωνο. Αλλά για μένα το σηκώνει.", "Voula geht nie ans Telefon. Aber für mich geht sie ran.", "Vula nunca coge el teléfono. Pero a mí sí me lo coge.", "Voula never picks up the phone. But she picks up for me.", "—I Voúla den sikóni poté to tiléfono. Allá gia ména to sikóni."),
    Z("—Έλα, Βούλα! Η Δέσποινα είμαι. Έχω εδώ την Έμμα σου!", "Hallo, Voula! Ich bin's, Despina. Ich habe deine Emma hier!", "¡Hola, Vula! Soy Despina. ¡Tengo aquí a tu Emma!", "Hello, Voula! It's Despina. I've got your Emma here!", "—Éla, Voúla! I Déspina íme. Écho edó tin Émma sou!"),
    N("Ein Gespräch, schneller als jeder Tomatenhändler. Emma versteht: Veria, Samstag, Zug, und dreimal das Wort für essen. Dann hält Frau Despina ihr das Handy ans Ohr.",
      "Una conversación más rápida que cualquier tomatero. Emma entiende: Veria, sábado, tren, y tres veces la palabra «comer». Luego la señora Despina le pone el móvil en la oreja.",
      "A conversation faster than any tomato seller. Emma catches: Veria, Saturday, train, and three times the word for eat. Then Mrs Despina holds the phone to her ear."),
    Z("—Έμμα; Έλα το Σάββατο στη Βέροια. Με το τρένο. Και φέρε το χαρτί!", "Emma? Komm am Samstag nach Veria. Mit dem Zug. Und bring das Papier mit!", "¿Emma? Ven el sábado a Veria. En tren. ¡Y trae el papel!", "Emma? Come to Veria on Saturday. By train. And bring the paper!", "—Émma? Éla to Sávvato sti Véria. Me to tréno. Ke fére to chartí!"),
    Z("—Ναι, κυρία Βούλα. Ευχαριστώ!", "Ja, Frau Voula. Danke!", "Sí, señora Vula. ¡Gracias!", "Yes, Mrs Voula. Thank you!", "—Ne, kiría Voúla. Efcharistó!"),
    N("Ne. Diesmal zuckt Emmas Kopf nicht. Fast nicht. Frau Despina schreibt die Nummer auf eine Papiertüte. Emma gibt ihr einen Zehner für die Äpfel. Das Wechselgeld kommt mit drei Feigen zurück.",
      "Ne. Esta vez a Emma no le da el respingo. Casi no. La señora Despina apunta el número en una bolsa de papel. Emma le da diez euros por las manzanas. La vuelta viene con tres higos.",
      "Ne. This time Emma's head doesn't twitch. Almost not. Mrs Despina writes the number on a paper bag. Emma gives her a ten for the apples. The change comes back with three figs."),
    Z("—Ορίστε, δέκα ευρώ.", "Bitte schön, zehn Euro.", "Tenga, diez euros.", "Here you are, ten euros.", "—Oríste, déka evró."),
    N("Am Käsestand: ein Mann mit Schürze und einem Messer so lang wie ein Unterarm.",
      "En el puesto de quesos: un hombre con delantal y un cuchillo tan largo como un antebrazo.",
      "At the cheese stall: a man in an apron with a knife as long as a forearm."),
    Z("—Καλημέρα. Με στέλνει η κυρία Δέσποινα. Μισό κιλό φέτα, παρακαλώ.", "Guten Morgen. Frau Despina schickt mich. Ein halbes Kilo Feta, bitte.", "Buenos días. Me manda la señora Despina. Medio kilo de feta, por favor.", "Good morning. Mrs Despina sent me. Half a kilo of feta, please.", "—Kaliméra. Me stélni i kiría Déspina. Misó kiló féta, parakaló."),
    Z("—Της Δέσποινας; Τότε η καλή φέτα. Δοκίμασε. Έξι ευρώ.", "Von Despina? Dann der gute Feta. Probier mal. Sechs Euro.", "¿De Despina? Entonces el feta bueno. Prueba. Seis euros.", "From Despina? Then the good feta. Have a taste. Six euros.", "—Tis Déspinas? Tóte i kalí féta. Dokímase. Éxi evró."),
    N("Salzig, weich, ein bisschen säuerlich. Emma beschließt, nie wieder abgepackten Feta zu kaufen. Hinter ihr taucht Frau Roula auf, mit Fisch und einer Frage.",
      "Salado, tierno, un poco ácido. Emma decide no volver a comprar feta envasado nunca más. Detrás de ella aparece la señora Rula, con pescado y una pregunta.",
      "Salty, soft, a little sour. Emma decides never to buy packaged feta again. Behind her Mrs Roula reappears, with fish and a question."),
    Z("—Πεινάς;", "Hast du Hunger?", "¿Tienes hambre?", "Are you hungry?", "—Pinás?")
  ]),

  // ── Station 4 · WEGBESCHREIBUNG ─────────────────────────────────────
  S('fundament', 4, 'wegbeschreibung', "Ευθεία, μετά δεξιά",
    "Emma sucht das Finanzamt zehn Tage zu früh — und bekommt vier Wegbeschreibungen, ein Koulouri und einen Begleiter.",
    "Emma busca Hacienda con diez días de antelación — y recibe cuatro indicaciones, un koulouri y un acompañante.",
    "Emma looks for the tax office ten days early — and gets four sets of directions, a koulouri and an escort.",
  [
    N("Montag. Emma ist Österreicherin. Österreicher gehen einen Weg, bevor sie ihn gehen müssen. Den Termin hat sie am Donnerstag in zehn Tagen. Heute will sie wissen, wo.",
      "Lunes. Emma es austriaca. Los austriacos recorren un camino antes de tener que recorrerlo. La cita es el jueves de la semana que viene. Hoy quiere saber dónde.",
      "Monday. Emma is Austrian. Austrians walk a route before they have to walk it. Her appointment is on Thursday week. Today she wants to know where."),
    Z("Η Έμμα είναι στην πλατεία Αριστοτέλους. Το κινητό δεν έχει μπαταρία.", "Emma ist am Aristotelous-Platz. Das Handy hat keinen Akku mehr.", "Emma está en la plaza Aristotelous. El móvil no tiene batería.", "Emma is in Aristotelous Square. Her phone's battery is dead.", "I Émma íne stin platía Aristotélous. To kinitó den échi bataría."),
    N("Vor ihr: das Meer. Hinter ihr: die halbe Stadt. Irgendwo dazwischen: das Finanzamt. Am Kiosk, dem Períptero, sitzt ein junger Mann zwischen Zeitungen, Kaugummi und Feuerzeugen.",
      "Delante: el mar. Detrás: media ciudad. En algún punto entre los dos: Hacienda. En el quiosco, el períptero, hay un chico entre periódicos, chicles y mecheros.",
      "In front of her: the sea. Behind her: half the city. Somewhere in between: the tax office. At the kiosk, the periptero, a young man sits among newspapers, chewing gum and lighters."),
    Z("—Συγγνώμη. Πού είναι η εφορία;", "Entschuldigung. Wo ist das Finanzamt?", "Perdone. ¿Dónde está Hacienda?", "Excuse me. Where's the tax office?", "—Signómi. Poú íne i eforía?"),
    Z("—Η εφορία; Εκεί.", "Das Finanzamt? Da.", "¿Hacienda? Allí.", "The tax office? There.", "—I eforía? Ekí."),
    N("Er zeigt mit dem Kinn. Nach links? Nach oben? In die Vergangenheit? Emma wartet auf mehr. Mehr kommt nicht.",
      "Señala con la barbilla. ¿A la izquierda? ¿Hacia arriba? ¿Hacia el pasado? Emma espera algo más. No llega nada más.",
      "He points with his chin. Left? Up? Into the past? Emma waits for more. No more comes."),
    Z("—Εκεί… πού; Είναι μακριά;", "Da … wo? Ist es weit?", "Allí… ¿dónde? ¿Está lejos?", "There… where? Is it far?", "—Ekí… poú? Íne makriá?"),
    Z("—Όχι, κοντά. Ευθεία. Μετά δεξιά. Στο φανάρι αριστερά. Είναι στη γωνία.", "Nein, nah. Geradeaus. Dann rechts. An der Ampel links. Es ist an der Ecke.", "No, cerca. Todo recto. Luego a la derecha. En el semáforo, a la izquierda. Está en la esquina.", "No, close. Straight on. Then right. At the lights, left. It's on the corner.", "—Óchi, kondá. Efthía. Metá dexiá. Sto fanári aristerá. Íne sti gonía."),
    N("Emma wiederholt es leise, wie eine Beschwörung. Geradeaus, rechts, Ampel, links, Ecke.",
      "Emma lo repite en voz baja, como un conjuro. Recto, derecha, semáforo, izquierda, esquina.",
      "Emma repeats it under her breath, like an incantation. Straight, right, lights, left, corner."),
    Z("Στη γωνία είναι ένας φούρνος. Μυρίζει κουλούρι. Εφορία δεν υπάρχει.", "An der Ecke ist eine Bäckerei. Es riecht nach Koulouri. Ein Finanzamt gibt es nicht.", "En la esquina hay una panadería. Huele a koulouri. Hacienda, ni rastro.", "On the corner there's a bakery. It smells of koulouri. There's no tax office.", "Sti gonía íne énas foúrnos. Mirízi kouloúri. Eforía den ipárchi."),
    N("Koulouri, der Sesamring von Thessaloniki, das Frühstück der ganzen Stadt im Gehen. Vor der Bäckerei: eine Frau mit Kinderwagen.",
      "El koulouri, la rosca de sésamo de Tesalónica, el desayuno de toda la ciudad sobre la marcha. Delante de la panadería: una mujer con un carrito de bebé.",
      "Koulouri, Thessaloniki's sesame ring, the whole city's breakfast on the move. Outside the bakery: a woman with a pram."),
    Z("—Με συγχωρείτε. Ξέρετε πού είναι η εφορία;", "Verzeihung. Wissen Sie, wo das Finanzamt ist?", "Disculpe. ¿Sabe dónde está Hacienda?", "Excuse me. Do you know where the tax office is?", "—Me sinchoríte. Xérete poú íne i eforía?"),
    Z("—Η εφορία; Είναι μακριά. Πάρτε λεωφορείο.", "Das Finanzamt? Das ist weit. Nehmen Sie den Bus.", "¿Hacienda? Está lejos. Coja el autobús.", "The tax office? It's a long way. Take the bus.", "—I eforía? Íne makriá. Párte leoforío."),
    N("Ein Mann im Anzug, im Vorbeigehen, ohne stehen zu bleiben:",
      "Un hombre de traje, al pasar, sin pararse:",
      "A man in a suit, in passing, without stopping:"),
    Z("—Όχι, όχι! Είναι πολύ κοντά. Δύο λεπτά. Αριστερά!", "Nein, nein! Es ist ganz nah. Zwei Minuten. Links!", "¡No, no! Está muy cerca. Dos minutos. ¡A la izquierda!", "No, no! It's very close. Two minutes. Left!", "—Óchi, óchi! Íne polí kondá. Dío leptá. Aristerá!"),
    N("Drei Menschen, drei Richtungen. Auf einer Bank sitzt ein alter Mann mit Schiebermütze. Er hat alles gehört. Er steht auf, ächzend, und nimmt Emmas Arm.",
      "Tres personas, tres direcciones. En un banco hay un anciano con gorra. Lo ha oído todo. Se levanta, con un quejido, y coge a Emma del brazo.",
      "Three people, three directions. On a bench sits an old man in a flat cap. He has heard everything. He gets up with a groan and takes Emma's arm."),
    Z("—Έλα μαζί μου, κοπέλα μου.", "Komm mit mir, Mädchen.", "Ven conmigo, hija.", "Come with me, love.", "—Éla mazí mou, kopéla mou."),
    Z("—Από πού είσαι;", "Woher kommst du?", "¿De dónde eres?", "Where are you from?", "—Apó poú íse?"),
    Z("—Από τη Βιέννη.", "Aus Wien.", "De Viena.", "From Vienna.", "—Apó ti Viénni."),
    Z("—Ο εγγονός μου είναι στη Στουτγάρδη. Μηχανικός. Δεν τρώει καλά.", "Mein Enkel ist in Stuttgart. Ingenieur. Er isst nicht richtig.", "Mi nieto está en Stuttgart. Ingeniero. No come bien.", "My grandson's in Stuttgart. An engineer. He doesn't eat properly.", "—O engonós mou íne sti Stoutgárdi. Michanikós. Den trói kalá."),
    Z("—Κι εσύ; Τρως καλά;", "Und du? Isst du ordentlich?", "¿Y tú? ¿Comes bien?", "And you? Are you eating properly?", "—Ki esí? Tros kalá?"),
    Z("—Ναι, πολύ καλά. Εδώ όλοι μου δίνουν φαγητό.", "Ja, sehr gut. Hier geben mir alle etwas zu essen.", "Sí, muy bien. Aquí todo el mundo me da de comer.", "Yes, very well. Everyone here feeds me.", "—Ne, polí kalá. Edó óli mou dínoun fayitó."),
    Z("—Μπράβο. Τι δουλειά κάνεις;", "Bravo. Was arbeitest du?", "Muy bien. ¿A qué te dedicas?", "Good. What do you do?", "—Brávo. Ti douliá kánis?"),
    Z("—Είμαι αρχαιολόγος.", "Ich bin Archäologin.", "Soy arqueóloga.", "I'm an archaeologist.", "—Íme archeológos."),
    Z("—Αρχαιολόγος! Ξέρεις τον δρόμο για την αρχαία Ελλάδα, αλλά όχι για την εφορία.", "Archäologin! Du kennst den Weg ins antike Griechenland, aber nicht zum Finanzamt.", "¡Arqueóloga! Sabes el camino a la Grecia antigua, pero no a Hacienda.", "An archaeologist! You know the way to ancient Greece, but not to the tax office.", "—Archeológos! Xéris ton drómo gia tin archéa Elláda, allá óchi gia tin eforía."),
    N("Er lacht über seinen eigenen Witz, lange und zufrieden.",
      "Se ríe de su propio chiste, largo rato y muy satisfecho.",
      "He laughs at his own joke, long and contentedly."),
    N("Er kauft ihr im Vorbeigehen ein Koulouri. Natürlich. Dann: ein großes graues Gebäude, eine Glastür, ein Schild.",
      "Al pasar le compra un koulouri. Cómo no. Luego: un edificio grande y gris, una puerta de cristal, un cartel.",
      "On the way he buys her a koulouri. Of course. Then: a big grey building, a glass door, a sign."),
    Z("—Να η εφορία.", "Da ist das Finanzamt.", "Ahí está Hacienda.", "There's the tax office.", "—Na i eforía."),
    Z("Η πόρτα είναι κλειστή. Ένα χαρτί λέει: «Ώρες 8:00–14:30». Είναι 14:35.", "Die Tür ist zu. Ein Zettel sagt: »Öffnungszeiten 8:00–14:30«. Es ist 14:35.", "La puerta está cerrada. Un papel dice: «Horario 8:00–14:30». Son las 14:35.", "The door is shut. A notice says: “Opening hours 8:00–14:30”. It's 14:35.", "I pórta íne klistí. Éna chartí léi: «Óres 8:00–14:30». Íne 14:35."),
    Z("—Δεν πειράζει. Τώρα ξέρεις τον δρόμο. Την Πέμπτη έρχεσαι νωρίς.", "Macht nichts. Jetzt kennst du den Weg. Am Donnerstag kommst du früh.", "No pasa nada. Ahora ya sabes el camino. El jueves vienes temprano.", "Never mind. Now you know the way. On Thursday you come early.", "—Den pirázi. Tóra xéris ton drómo. Tin Pémbti érchese norís."),
    Z("—Ευχαριστώ πολύ!", "Vielen Dank!", "¡Muchas gracias!", "Thank you very much!", "—Efcharistó polí!"),
    N("Der alte Mann heißt Kyr-Pavlos, sagt er, und er hat vierzig Jahre bei der Post gearbeitet, im Gebäude gegenüber. Den Weg zum Finanzamt kennt er also seit 1971. Er tippt sich an die Mütze und geht langsam zurück zu seiner Bank.",
      "El anciano se llama kyr-Pavlos, dice, y trabajó cuarenta años en Correos, en el edificio de enfrente. O sea, que conoce el camino a Hacienda desde 1971. Se toca la gorra y vuelve despacio a su banco.",
      "The old man is called Kyr-Pavlos, he says, and he worked at the post office for forty years, in the building opposite. So he has known the way to the tax office since 1971. He touches his cap and walks slowly back to his bench."),
    N("Am Abend zeichnet Emma den Weg ins Notizbuch, wie einen Grabungsplan. Ganz unten, zweimal unterstrichen:",
      "Por la noche, Emma dibuja el camino en su libreta, como un plano de excavación. Abajo del todo, subrayado dos veces:",
      "In the evening Emma draws the route in her notebook, like an excavation plan. At the very bottom, underlined twice:"),
    Z("Ευθεία, δεξιά, φανάρι, αριστερά, γωνία. Νωρίς!", "Geradeaus, rechts, Ampel, links, Ecke. Früh!", "Recto, derecha, semáforo, izquierda, esquina. ¡Temprano!", "Straight on, right, lights, left, corner. Early!", "Efthía, dexiá, fanári, aristerá, gonía. Norís!")
  ]),

  // ── Station 5 · BAHNHOF ─────────────────────────────────────────────
  S('fundament', 5, 'bahnhof', "Μετ' επιστροφής",
    "Eine Rückfahrkarte nach Veria, ein Zug, der »kommt« — und eine Großmutter mit Käsepasteten und erstaunlichen Verwandten.",
    "Un billete de ida y vuelta a Veria, un tren que «ya viene» — y una abuela con empanadas de queso y parientes asombrosos.",
    "A return ticket to Veria, a train that is “coming” — and a grandmother with cheese pies and astonishing relatives.",
  [
    N("Samstag, sieben Uhr früh. Der Bahnhof von Thessaloniki ist groß, grau und fast leer. Ein paar Soldaten, eine Familie mit Kühlbox, Tauben.",
      "Sábado, las siete de la mañana. La estación de Tesalónica es grande, gris y está casi vacía. Unos soldados, una familia con una nevera portátil, palomas.",
      "Saturday, seven in the morning. Thessaloniki station is big, grey and nearly empty. A few soldiers, a family with a cool box, pigeons."),
    Z("ΣΙΔΗΡΟΔΡΟΜΙΚΟΣ ΣΤΑΘΜΟΣ ΘΕΣΣΑΛΟΝΙΚΗΣ", "Bahnhof Thessaloniki", "Estación de tren de Tesalónica", "Thessaloniki railway station", "SIDIRODROMIKÓS STATHMÓS THESSALONÍKIS"),
    Z("Στην τσάντα της Έμμας: το διαβατήριο, το μισθωτήριο, ένα στιλό.", "In Emmas Tasche: der Pass, der Mietvertrag, ein Kugelschreiber.", "En el bolso de Emma: el pasaporte, el contrato, un bolígrafo.", "In Emma's bag: her passport, the contract, a pen.", "Stin tsánda tis Émmas: to diavatírio, to misthotírio, éna stiló."),
    Z("—Καλημέρα. Ένα εισιτήριο για τη Βέροια, παρακαλώ.", "Guten Morgen. Eine Fahrkarte nach Veria, bitte.", "Buenos días. Un billete para Veria, por favor.", "Good morning. A ticket to Veria, please.", "—Kaliméra. Éna isitírio gia ti Véria, parakaló."),
    Z("—Απλό ή μετ' επιστροφής;", "Einfach oder hin und zurück?", "¿De ida o de ida y vuelta?", "Single or return?", "—Apló i met' epistrofís?"),
    Z("—Μετ' επιστροφής. Τι ώρα φεύγει το τρένο;", "Hin und zurück. Wann fährt der Zug ab?", "De ida y vuelta. ¿A qué hora sale el tren?", "Return. What time does the train leave?", "—Met' epistrofís. Ti óra févyi to tréno?"),
    Z("—Στις επτά και σαράντα. Από την αποβάθρα τέσσερα. Δώδεκα ευρώ.", "Um sieben Uhr vierzig. Von Gleis vier. Zwölf Euro.", "A las siete y cuarenta. Del andén cuatro. Doce euros.", "At seven forty. From platform four. Twelve euros.", "—Stis eptá ke saránda. Apó tin apováthra téssera. Dódeka evró."),
    N("Zwölf Euro, hin und zurück, siebzig Kilometer pro Strecke. In Wien bekäme man dafür zwei Kilometer Taxi. Emma steckt die Fahrkarte in die Klarsichthülle zum Vertrag. Ordnung muss sein, auch in Griechenland. Gerade in Griechenland.",
      "Doce euros, ida y vuelta, setenta kilómetros por trayecto. En Viena, eso da para dos kilómetros de taxi. Emma mete el billete en la funda de plástico, junto al contrato. Hay que ser ordenada, también en Grecia. Sobre todo en Grecia.",
      "Twelve euros, return, seventy kilometres each way. In Vienna that would buy you two kilometres of taxi. Emma slips the ticket into the plastic sleeve with the contract. Order matters, in Greece too. Especially in Greece."),
    Z("—Πού είναι η αποβάθρα τέσσερα;", "Wo ist Gleis vier?", "¿Dónde está el andén cuatro?", "Where's platform four?", "—Poú íne i apováthra téssera?"),
    Z("—Ευθεία και αριστερά.", "Geradeaus und links.", "Todo recto y a la izquierda.", "Straight on and left.", "—Efthía ke aristerá."),
    N("Gleis vier. Sieben Uhr vierzig: kein Zug. Sieben Uhr fünfzig: kein Zug. Auf der Anzeige erscheint ein langes Wort.",
      "Andén cuatro. Las siete y cuarenta: ni rastro del tren. Las siete y cincuenta: tampoco. En el panel aparece una palabra larga.",
      "Platform four. Seven forty: no train. Seven fifty: no train. A long word appears on the board."),
    Z("ΚΑΘΥΣΤΕΡΗΣΗ", "Verspätung", "Retraso", "Delay", "KATHISTÉRISI"),
    N("Neben Emma auf der Bank: eine Großmutter in Schwarz mit einer riesigen Tasche, aus der es nach Butter riecht.",
      "Junto a Emma, en el banco: una abuela vestida de negro con un bolso enorme que huele a mantequilla.",
      "Next to Emma on the bench: a grandmother in black with an enormous bag that smells of butter."),
    Z("—Το τρένο αργεί. Πάντα αργεί.", "Der Zug hat Verspätung. Er hat immer Verspätung.", "El tren se retrasa. Siempre se retrasa.", "The train's late. It's always late.", "—To tréno aryí. Pánda aryí."),
    Z("—Πόσο αργεί;", "Wie viel Verspätung hat er?", "¿Cuánto se retrasa?", "How late is it?", "—Póso aryí?"),
    Z("—Λίγο.", "Ein bisschen.", "Un poco.", "A bit.", "—Lígo."),
    N("Um zwanzig nach acht ruft der Bahnhofsvorsteher über den Bahnsteig:",
      "A las ocho y veinte, el jefe de estación grita por el andén:",
      "At twenty past eight the stationmaster calls across the platform:"),
    Z("—Έρχεται, έρχεται!", "Er kommt, er kommt!", "¡Ya viene, ya viene!", "It's coming, it's coming!", "—Érchete, érchete!"),
    N("Um zehn vor neun ruft er es wieder, genauso überzeugt. »Er kommt« heißt in Griechenland, lernt Emma: vielleicht in einer Stunde. Und »ein bisschen« ist keine Maßeinheit, sondern eine Weltanschauung.",
      "A las nueve menos diez lo vuelve a gritar, igual de convencido. «Ya viene», aprende Emma, en Grecia significa: quizá dentro de una hora. Y «un poco» no es una unidad de medida, sino una forma de ver el mundo.",
      "At ten to nine he calls it again, just as convinced. In Greece, Emma learns, “it's coming” means: maybe in an hour. And “a bit” is not a unit of measurement but a philosophy of life."),
    Z("—Πεινάς; Πάρε μια τυρόπιτα.", "Hast du Hunger? Nimm eine Käsepastete.", "¿Tienes hambre? Toma una empanada de queso.", "Are you hungry? Have a cheese pie.", "—Pinás? Páre mia tirópita."),
    N("Emma macht Marinas Nein: Kinn hoch, Augenbrauen hoch, tsk. Die Großmutter schaut sie an, lacht — und gibt ihr zwei. Das griechische Nein funktioniert. Nur nicht bei Großmüttern.",
      "Emma hace el «no» de Marina: barbilla arriba, cejas arriba, tsk. La abuela la mira, se ríe… y le da dos. El «no» griego funciona. Menos con las abuelas.",
      "Emma does Marina's no: chin up, eyebrows up, tsk. The grandmother looks at her, laughs — and gives her two. The Greek no works. Just not on grandmothers."),
    Z("Στις εννιά και πέντε έρχεται το τρένο. Είναι παλιό και πολύ ζεστό.", "Um neun Uhr fünf kommt der Zug. Er ist alt und sehr warm.", "A las nueve y cinco llega el tren. Es viejo y hace mucho calor dentro.", "At five past nine the train arrives. It's old and very hot.", "Stis enniá ke pénde érchete to tréno. Íne palió ke polí zestó."),
    Z("—Εισιτήρια, παρακαλώ.", "Fahrkarten, bitte.", "Billetes, por favor.", "Tickets, please.", "—Isitíria, parakaló."),
    Z("—Ορίστε.", "Bitte schön.", "Tenga.", "Here you are.", "—Oríste."),
    N("Draußen ziehen Baumwollfelder vorbei, weiß wie Schnee im Oktober. Die Großmutter sitzt Emma gegenüber und will alles wissen.",
      "Fuera pasan campos de algodón, blancos como nieve en octubre. La abuela se sienta enfrente de Emma y quiere saberlo todo.",
      "Outside, cotton fields roll past, white as snow in October. The grandmother sits opposite Emma and wants to know everything."),
    Z("—Από πού είσαι, κορίτσι μου;", "Woher kommst du, mein Mädchen?", "¿De dónde eres, hija?", "Where are you from, dear?", "—Apó poú íse, korítsi mou?"),
    Z("—Από τη Βιέννη. Δουλεύω στη Θεσσαλονίκη, στο πανεπιστήμιο.", "Aus Wien. Ich arbeite in Thessaloniki, an der Universität.", "De Viena. Trabajo en Tesalónica, en la universidad.", "From Vienna. I work in Thessaloniki, at the university.", "—Apó ti Viénni. Doulévo sti Thessaloníki, sto panepistímio."),
    Z("—Και τι κάνεις στη Βέροια;", "Und was machst du in Veria?", "¿Y qué haces en Veria?", "And what are you doing in Veria?", "—Ke ti kánis sti Véria?"),
    Z("—Χρειάζομαι μια υπογραφή.", "Ich brauche eine Unterschrift.", "Necesito una firma.", "I need a signature.", "—Chriázome mia ipografí."),
    Z("—Μια υπογραφή! Για μια υπογραφή πας στη Βέροια; Ποιον ξέρεις εκεί;", "Eine Unterschrift! Für eine Unterschrift fährst du nach Veria? Wen kennst du da?", "¡Una firma! ¿Por una firma vas a Veria? ¿A quién conoces allí?", "A signature! You're going to Veria for a signature? Who do you know there?", "—Mia ipografí! Gia mia ipografí pas sti Véria? Pion xéris ekí?"),
    Z("—Την κυρία Βούλα Καραγιάννη.", "Frau Voula Karagianni.", "A la señora Vula Karagianni.", "Mrs Voula Karagianni.", "—Tin kiría Voúla Karagiánni."),
    Z("—Τη Βούλα; Είναι ξαδέρφη μου!", "Voula? Sie ist meine Cousine!", "¿Vula? ¡Es mi prima!", "Voula? She's my cousin!", "—Ti Voúla? Íne xadérfi mou!"),
    N("Natürlich ist sie das. Die Großmutter ruft an. Frau Voula geht sofort ran.",
      "Pues claro. La abuela llama. La señora Vula lo coge al instante.",
      "Of course she is. The grandmother rings. Mrs Voula answers straight away."),
    Z("—Βούλα; Η κοπέλα σου είναι εδώ. Ναι, στο τρένο. Ναι, τρώει.", "Voula? Dein Mädchen ist hier. Ja, im Zug. Ja, sie isst.", "¿Vula? Tu chica está aquí. Sí, en el tren. Sí, está comiendo.", "Voula? Your girl is here. Yes, on the train. Yes, she's eating.", "—Voúla? I kopéla sou íne edó. Ne, sto tréno. Ne, trói."),
    Z("Στις δέκα και είκοσι το τρένο φτάνει στη Βέροια.", "Um zehn Uhr zwanzig kommt der Zug in Veria an.", "A las diez y veinte el tren llega a Veria.", "At twenty past ten the train reaches Veria.", "Stis déka ke íkosi to tréno ftáni sti Véria."),
    Z("Στον σταθμό περιμένει ένας νέος με ένα χαρτί: «ΕΜΜΑ».", "Am Bahnhof wartet ein junger Mann mit einem Schild: »EMMA«.", "En la estación espera un chico con un cartel: «EMMA».", "At the station a young man is waiting with a sign: “EMMA”.", "Ston stathmó periméni énas néos me éna chartí: «ÉMMA»."),
    N("Giannakis, Frau Voulas Patensohn. Frau Voula geht nicht ans Telefon. Aber sie schickt immer jemanden.",
      "Giannakis, el ahijado de la señora Vula. La señora Vula no coge el teléfono. Pero siempre manda a alguien.",
      "Giannakis, Mrs Voula's godson. Mrs Voula doesn't answer the phone. But she always sends someone.")
  ]),

  // ── Station 6 · RESTAURANT ──────────────────────────────────────────
  S('fundament', 6, 'restaurant', "Τι μας προτείνετε;",
    "Eine Taverne am Fluss, zwei Schwestern, ein Kilo Wein — eine Unterschrift. Und die Rechnung gibt es gar nicht.",
    "Una taberna junto al río, dos hermanas, un kilo de vino — una firma. Y la cuenta ni siquiera existe.",
    "A taverna by the river, two sisters, a kilo of wine — a signature. And the bill doesn't even exist.",
  [
    N("Veria, ein Uhr mittags. Eine Taverne am Fluss Tripotamos, Platanen, Papiertischdecken, festgeklemmt gegen den Wind. Am Ecktisch warten zwei alte Damen, beide in Dunkelblau, beide mit der Handtasche auf dem Schoß, als könnte jemand sie stehlen.",
      "Veria, la una del mediodía. Una taberna junto al río Tripotamos, plátanos, manteles de papel sujetos con pinzas contra el viento. En la mesa del rincón esperan dos señoras mayores, las dos de azul marino, las dos con el bolso en el regazo, como si alguien se lo fuera a robar.",
      "Veria, one in the afternoon. A taverna by the Tripotamos river, plane trees, paper tablecloths clipped down against the wind. At the corner table two old ladies are waiting, both in navy blue, both with their handbags on their laps, as if someone might steal them."),
    Z("Η κυρία Βούλα είναι μικρή και γρήγορη. Η αδερφή της, η κυρία Λίτσα, είναι ψηλή και αργή.", "Frau Voula ist klein und schnell. Ihre Schwester, Frau Litsa, ist groß und langsam.", "La señora Vula es bajita y rápida. Su hermana, la señora Litsa, es alta y lenta.", "Mrs Voula is small and quick. Her sister, Mrs Litsa, is tall and slow.", "I kiría Voúla íne mikrí ke grígori. I aderfí tis, i kiría Lítsa, íne psilí ke argí."),
    Z("—Έμμα! Επιτέλους! Κάτσε, κάτσε.", "Emma! Endlich! Setz dich, setz dich.", "¡Emma! ¡Por fin! Siéntate, siéntate.", "Emma! At last! Sit down, sit down.", "—Émma! Epitélous! Kátse, kátse."),
    N("Frau Voula küsst sie auf beide Wangen, als kenne sie Emma seit ihrer Taufe. Ein junger Kellner kommt.",
      "La señora Vula le da dos besos como si la conociera desde el bautizo. Llega un camarero joven.",
      "Mrs Voula kisses her on both cheeks as if she had known Emma since her christening. A young waiter comes over."),
    Z("—Καλώς ήρθατε! Πόσοι είστε;", "Willkommen! Wie viele sind Sie?", "¡Bienvenidas! ¿Cuántas son?", "Welcome! How many of you are there?", "—Kalós írthate! Pósi íste?"),
    Z("—Είμαστε τρεις. Τι μας προτείνετε;", "Wir sind zu dritt. Was empfehlen Sie uns?", "Somos tres. ¿Qué nos recomienda?", "There are three of us. What do you recommend?", "—Ímaste tris. Ti mas protínete?"),
    N("Emma hat gefragt. Auf Griechisch. Frau Voula sieht ihre Schwester an, als hätte die Katze gesprochen.",
      "Lo ha preguntado Emma. En griego. La señora Vula mira a su hermana como si hubiera hablado el gato.",
      "Emma asked. In Greek. Mrs Voula looks at her sister as if the cat had spoken."),
    Z("—Σήμερα έχουμε μουσακά, γεμιστά και μπιφτέκια. Και φρέσκια σαλάτα.", "Heute haben wir Moussaka, gefülltes Gemüse und Biftekia. Und frischen Salat.", "Hoy tenemos musaca, verduras rellenas y biftekia. Y ensalada fresca.", "Today we've got moussaka, stuffed vegetables and biftekia. And fresh salad.", "—Símera échoume mousaká, yemistá ke biftékia. Ke fréskia saláta."),
    Z("—Για μένα έναν μουσακά, παρακαλώ.", "Für mich eine Moussaka, bitte.", "Para mí una musaca, por favor.", "A moussaka for me, please.", "—Gia ména énan mousaká, parakaló."),
    Z("—Φέρε απ' όλα, Γιαννάκη. Η κοπέλα είναι πολύ αδύνατη.", "Bring von allem, Giannakis. Das Mädchen ist sehr dünn.", "Trae de todo, Yanakis. La chica está muy delgada.", "Bring a bit of everything, Giannakis. The girl is very thin.", "—Fére ap' óla, Giannáki. I kopéla íne polí adínati."),
    Z("—Και τι θα πιείτε;", "Und was trinken Sie?", "¿Y para beber?", "And to drink?", "—Ke ti tha piíte?"),
    Z("—Ένα κιλό κρασί. Κόκκινο.", "Ein Kilo Wein. Roten.", "Un kilo de vino. Tinto.", "A kilo of wine. Red.", "—Éna kiló krasí. Kókkino."),
    N("Ein Kilo Wein. Er kommt in einer Blechkaraffe, und niemand wiegt ihn. Danach: Teller über Teller, bis der Tisch verschwindet.",
      "Un kilo de vino. Llega en una jarra de latón y nadie lo pesa. Después: plato tras plato, hasta que la mesa desaparece.",
      "A kilo of wine. It arrives in a tin jug, and nobody weighs it. After that: plate after plate, until the table disappears."),
    Z("—Ορίστε. Μουσακάς, γεμιστά, μπιφτέκια, σαλάτα. Και τζατζίκι, δώρο.", "Bitte schön. Moussaka, gefülltes Gemüse, Biftekia, Salat. Und Tsatsiki, als Geschenk.", "Aquí tienen. Musaca, verduras rellenas, biftekia, ensalada. Y tzatziki, de regalo.", "Here you are. Moussaka, stuffed vegetables, biftekia, salad. And tzatziki, on the house.", "—Oríste. Mousakás, yemistá, biftékia, saláta. Ke tzatzíki, dóro."),
    N("Wenn sie das alles isst, denkt Emma, braucht sie kein AFM mehr, sondern einen neuen Pass. Mit neuem Foto.",
      "Si se come todo esto, piensa Emma, no necesitará un AFM, sino un pasaporte nuevo. Con foto nueva.",
      "If she eats all this, Emma thinks, she won't need an AFM but a new passport. With a new photo."),
    Z("—Πώς είναι το σπίτι; Σου αρέσει;", "Wie ist die Wohnung? Gefällt sie dir?", "¿Qué tal el piso? ¿Te gusta?", "How's the flat? Do you like it?", "—Pós íne to spíti? Sou arési?"),
    Z("—Μου αρέσει πολύ. Έχει θέα στη θάλασσα.", "Sie gefällt mir sehr. Man sieht das Meer.", "Me gusta mucho. Tiene vistas al mar.", "I like it very much. It has a sea view.", "—Mou arési polí. Échi théa sti thálassa."),
    Z("—Και η Ρούλα; Σε ταΐζει;", "Und Roula? Füttert sie dich?", "¿Y Rula? ¿Te da de comer?", "And Roula? Is she feeding you?", "—Ke i Roúla? Se taízi?"),
    Z("—Κάθε μέρα!", "Jeden Tag!", "¡Todos los días!", "Every day!", "—Káthe méra!"),
    Z("—Μπράβο της.", "Gut so.", "Bien hecho.", "Good for her.", "—Brávo tis."),
    Z("—Γεια μας!", "Prost! (Auf uns!)", "¡Salud! (¡Por nosotras!)", "Cheers! (To us!)", "—Giá mas!"),
    N("Frau Voula stößt mit Wasser an, Frau Litsa mit Wein. Wer von beiden die Ältere ist, wird Emma nie erfahren.",
      "La señora Vula brinda con agua; la señora Litsa, con vino. Cuál de las dos es la mayor, Emma no lo sabrá nunca.",
      "Mrs Voula toasts with water, Mrs Litsa with wine. Which of them is the elder, Emma will never find out."),
    Z("—Καλή όρεξη!", "Guten Appetit!", "¡Que aproveche!", "Enjoy your meal!", "—Kalí órexi!"),
    N("Beim Kaffee legt Emma den Mietvertrag auf den Tisch. Zwischen Brotkrümel und Weinflecken.",
      "Con el café, Emma pone el contrato sobre la mesa. Entre migas de pan y manchas de vino.",
      "Over coffee Emma puts the contract on the table. Between breadcrumbs and wine stains."),
    Z("—Κυρία Βούλα, το μισθωτήριο. Εδώ, παρακαλώ. Η υπογραφή σας.", "Frau Voula, der Mietvertrag. Hier, bitte. Ihre Unterschrift.", "Señora Vula, el contrato. Aquí, por favor. Su firma.", "Mrs Voula, the contract. Here, please. Your signature.", "—Kiría Voúla, to misthotírio. Edó, parakaló. I ipografí sas."),
    Z("Η κυρία Βούλα υπογράφει. Αργά. Με μεγάλα γράμματα.", "Frau Voula unterschreibt. Langsam. Mit großen Buchstaben.", "La señora Vula firma. Despacio. Con letras grandes.", "Mrs Voula signs. Slowly. In big letters.", "I kiría Voúla ipográfi. Argá. Me megála grámmata."),
    Z("—Και το ΑΦΜ σας;", "Und Ihr AFM?", "¿Y su AFM?", "And your AFM?", "—Ke to afimí sas?"),
    Z("—Το ΑΦΜ μου; Λίτσα, πού είναι το ΑΦΜ μου;", "Mein AFM? Litsa, wo ist mein AFM?", "¿Mi AFM? Litsa, ¿dónde está mi AFM?", "My AFM? Litsa, where's my AFM?", "—To afimí mou? Lítsa, poú íne to afimí mou?"),
    Z("Η κυρία Λίτσα ανοίγει την τσάντα. Βγάζει ένα μικρό τετράδιο.", "Frau Litsa öffnet die Handtasche. Sie holt ein kleines Heft heraus.", "La señora Litsa abre el bolso. Saca una libretita.", "Mrs Litsa opens her handbag. She takes out a little notebook.", "I kiría Lítsa aníyi tin tsánda. Vgázi éna mikró tetrádio."),
    Z("—Η Βούλα δεν θυμάται τίποτα. Εγώ θυμάμαι τα πάντα.", "Voula erinnert sich an nichts. Ich erinnere mich an alles.", "Vula no se acuerda de nada. Yo me acuerdo de todo.", "Voula doesn't remember anything. I remember everything.", "—I Voúla den thimáte típota. Egó thimáme ta pánda."),
    N("Der erste Satz, den Frau Litsa heute sagt. Er fasst sechzig Jahre Schwesternschaft zusammen.",
      "Es la primera frase que dice hoy la señora Litsa. Resume sesenta años de hermanas.",
      "The first sentence Mrs Litsa has said all day. It sums up sixty years of being sisters."),
    N("Neun Ziffern, Buchstabe für Buchstabe abgeschrieben. Emma schiebt den Vertrag in eine Klarsichthülle. Für alle Fälle.",
      "Nueve cifras, copiadas una a una. Emma mete el contrato en una funda de plástico. Por si acaso.",
      "Nine digits, copied out one by one. Emma slides the contract into a plastic sleeve. Just in case."),
    Z("—Τον λογαριασμό, παρακαλώ.", "Die Rechnung, bitte.", "La cuenta, por favor.", "The bill, please.", "—Ton logariasmó, parakaló."),
    Z("—Δεν υπάρχει λογαριασμός. Είναι κερασμένο.", "Es gibt keine Rechnung. Das geht aufs Haus.", "No hay cuenta. Invita la casa.", "There is no bill. It's on the house.", "—Den ipárchi logariasmós. Íne kerasméno."),
    N("Der Kellner ist Giannakis, Frau Voulas Patensohn, derselbe, der Emma vom Bahnhof abgeholt hat. In Veria, vermutet Emma, ist jeder irgendjemandes Patensohn.",
      "El camarero es Giannakis, el ahijado de la señora Vula, el mismo que fue a buscar a Emma a la estación. En Veria, sospecha Emma, todo el mundo es ahijado de alguien.",
      "The waiter is Giannakis, Mrs Voula's godson, the same one who picked Emma up from the station. In Veria, Emma suspects, everyone is somebody's godson."),
    Z("—Ευχαριστώ πολύ, κυρία Βούλα. Για όλα.", "Vielen Dank, Frau Voula. Für alles.", "Muchas gracias, señora Vula. Por todo.", "Thank you so much, Mrs Voula. For everything.", "—Efcharistó polí, kiría Voúla. Gia óla."),
    Z("—Να 'σαι καλά, κορίτσι μου. Και να τρως!", "Mach's gut, mein Mädchen. Und iss ordentlich!", "Cuídate, hija mía. ¡Y come!", "Look after yourself, my girl. And eat!", "—Na 'se kalá, korítsi mou. Ke na tros!")
  ]),

  // ── Station 7 · WETTER ──────────────────────────────────────────────
  S('fundament', 7, 'wetter', "Ο Όλυμπος φοράει καπέλο",
    "Ein goldener Oktobersonntag, ein Berg mit Hut — und die Frage, wer das Wetter besser kennt: die App oder Frau Roula.",
    "Un domingo dorado de octubre, una montaña con sombrero — y la pregunta de quién sabe más del tiempo: la aplicación o la señora Rula.",
    "A golden October Sunday, a mountain wearing a hat — and the question of who knows the weather better: the app or Mrs Roula.",
  [
    N("Sonntag. Ein Oktobertag, wie ihn Wien nicht einmal im Juni hinbekommt.",
      "Domingo. Un día de octubre como Viena no consigue ni en junio.",
      "Sunday. An October day of the kind Vienna can't manage even in June."),
    Z("Σήμερα ο καιρός είναι υπέροχος. Έχει ήλιο. Κάνει ζέστη. Είκοσι πέντε βαθμοί.", "Heute ist das Wetter herrlich. Die Sonne scheint. Es ist warm. Fünfundzwanzig Grad.", "Hoy hace un tiempo estupendo. Hace sol. Hace calor. Veinticinco grados.", "The weather's wonderful today. It's sunny. It's warm. Twenty-five degrees.", "Símera o kerós íne ipérochos. Échi ílio. Káni zésti. Íkosi pénde vathmí."),
    N("Frau Roula hat Emma auf ihren Balkon im Erdgeschoss geholt, mit Kaffee und Kuchen, natürlich. Das Haus steht am Hang: unten die Stadt, dahinter der Golf, und ganz hinten, über dem Wasser, ein Berg.",
      "La señora Rula ha invitado a Emma a su balcón de la planta baja, con café y bizcocho, cómo no. La casa está en la ladera: abajo la ciudad, detrás el golfo, y al fondo, sobre el agua, una montaña.",
      "Mrs Roula has brought Emma out onto her ground-floor balcony, with coffee and cake, naturally. The house stands on the hillside: below, the city; beyond it, the gulf; and right at the back, across the water, a mountain."),
    Z("Η Έμμα τρώει το τρίτο κομμάτι κέικ.", "Emma isst das dritte Stück Kuchen.", "Emma se come el tercer trozo de bizcocho.", "Emma eats her third slice of cake.", "I Émma trói to tríto kommáti kéik."),
    Z("—Κοίτα, Έμμα. Εκεί είναι ο Όλυμπος.", "Schau, Emma. Da ist der Olymp.", "Mira, Emma. Ahí está el Olimpo.", "Look, Emma. That's Mount Olympus.", "—Kíta, Émma. Ekí íne o Ólimbos."),
    Z("—Ο Όλυμπος; Το σπίτι των θεών;", "Der Olymp? Das Haus der Götter?", "¿El Olimpo? ¿La casa de los dioses?", "Olympus? The home of the gods?", "—O Ólimbos? To spíti ton theón?"),
    Z("—Των θεών και του καιρού.", "Der Götter und des Wetters.", "De los dioses y del tiempo.", "Of the gods and of the weather.", "—Ton theón ke tou keroú."),
    Z("—Σου αρέσει η Θεσσαλονίκη;", "Gefällt dir Thessaloniki?", "¿Te gusta Tesalónica?", "Do you like Thessaloniki?", "—Sou arési i Thessaloníki?"),
    Z("—Πολύ. Στη Βιέννη τώρα κάνει κρύο. Δώδεκα βαθμοί.", "Sehr. In Wien ist es jetzt kalt. Zwölf Grad.", "Mucho. En Viena ahora hace frío. Doce grados.", "Very much. It's cold in Vienna now. Twelve degrees.", "—Polí. Sti Viénni tóra káni krío. Dódeka vathmí."),
    Z("—Δώδεκα! Πώς ζείτε εκεί;", "Zwölf! Wie lebt ihr da?", "¡Doce! ¿Cómo vivís allí?", "Twelve! How do you live there?", "—Dódeka! Pós zíte ekí?"),
    Z("—Με μπουφάν. Και με καφέ.", "Mit Daunenjacke. Und mit Kaffee.", "Con plumífero. Y con café.", "With a puffer jacket. And with coffee.", "—Me boufán. Ke me kafé."),
    N("Emma hat über den Olymp eine Seminararbeit geschrieben, vierzig Seiten. Gesehen hat sie ihn nie. Er ist kleiner, als sie dachte. Und schöner.",
      "Emma escribió un trabajo de cuarenta páginas sobre el Olimpo. Nunca lo había visto. Es más pequeño de lo que pensaba. Y más bonito.",
      "Emma wrote a forty-page seminar paper about Olympus. She had never seen it. It's smaller than she thought. And more beautiful."),
    Z("—Και η θάλασσα σήμερα είναι λάδι.", "Und das Meer ist heute Öl.", "Y el mar hoy es aceite.", "And the sea is oil today.", "—Ke i thálassa símera íne ládi."),
    N("Öl: keine Welle, kein Hauch. Spiegelglatt, sagt man auf Deutsch. Auf Griechisch ist es Olivenöl. Natürlich.",
      "Aceite: ni una ola, ni un soplo. Una balsa, dirían en España. En griego es aceite de oliva. Cómo no.",
      "Oil: not a wave, not a breath. Like glass, you'd say in English. In Greek it's olive oil. Of course."),
    Z("—Τι καιρό θα κάνει αύριο;", "Wie wird das Wetter morgen?", "¿Qué tiempo hará mañana?", "What will the weather be like tomorrow?", "—Ti keró tha káni ávrio?"),
    Z("—Βλέπεις το σύννεφο στον Όλυμπο; Ο Όλυμπος φοράει καπέλο. Αύριο μάλλον θα βρέξει.", "Siehst du die Wolke auf dem Olymp? Der Olymp trägt einen Hut. Morgen regnet es wohl.", "¿Ves la nube en el Olimpo? El Olimpo lleva sombrero. Mañana seguramente llueve.", "Do you see the cloud on Olympus? Olympus is wearing a hat. It'll probably rain tomorrow.", "—Vlépis to sínnefo ston Ólimbo? O Ólimbos forái kapélo. Ávrio málon tha vréxi."),
    Z("Η Έμμα κοιτάζει το κινητό. Η εφαρμογή λέει: αύριο ήλιος, είκοσι τρεις βαθμοί.", "Emma schaut aufs Handy. Die App sagt: morgen Sonne, dreiundzwanzig Grad.", "Emma mira el móvil. La aplicación dice: mañana sol, veintitrés grados.", "Emma checks her phone. The app says: sun tomorrow, twenty-three degrees.", "I Émma kitázi to kinitó. I efarmoyí léi: ávrio ílios, íkosi tris vathmí."),
    Z("—Η εφαρμογή λέει ήλιο, κυρία Ρούλα.", "Die App sagt Sonne, Frau Roula.", "La aplicación dice sol, señora Rula.", "The app says sun, Mrs Roula.", "—I efarmoyí léi ílio, kiría Roúla."),
    Z("—Η εφαρμογή δεν ξέρει τον Όλυμπο.", "Die App kennt den Olymp nicht.", "La aplicación no conoce el Olimpo.", "The app doesn't know Olympus.", "—I efarmoyí den xéri ton Ólimbo."),
    N("Frau Roula sagt es ohne Triumph, wie eine Tatsache. Sie hat siebzig Jahre Wettervorhersagen überlebt und keiner einzigen geglaubt.",
      "La señora Rula lo dice sin triunfalismo, como un hecho. Ha sobrevivido a setenta años de previsiones meteorológicas y no se ha creído ni una.",
      "Mrs Roula says it without triumph, as a plain fact. She has survived seventy years of weather forecasts and believed not a single one."),
    Z("Το πρωί ο ουρανός είναι μπλε. Δεν έχει σύννεφα. Δεν φυσάει.", "Am Morgen ist der Himmel blau. Keine Wolken. Kein Wind.", "Por la mañana el cielo está azul. No hay nubes. No hace viento.", "In the morning the sky is blue. No clouds. No wind.", "To proí o ouranós íne ble. Den échi sínnefa. Den fisái."),
    N("Montag. Emma geht los, im T-Shirt. Aus dem Fenster im Erdgeschoss:",
      "Lunes. Emma sale en camiseta. Desde la ventana de la planta baja:",
      "Monday. Emma sets off in a T-shirt. From the ground-floor window:"),
    Z("—Έμμα! Πάρε ομπρέλα!", "Emma! Nimm einen Schirm mit!", "¡Emma! ¡Coge un paraguas!", "Emma! Take an umbrella!", "—Émma! Páre ombréla!"),
    Z("—Δεν έχω ομπρέλα. Και έχει ήλιο!", "Ich habe keinen Schirm. Und die Sonne scheint!", "¡No tengo paraguas! ¡Y hace sol!", "I haven't got an umbrella. And it's sunny!", "—Den écho ombréla. Ke échi ílio!"),
    N("Um eins, in der Universität, wird der Himmel schwarz. Nicht grau. Schwarz. Dann öffnet er sich. Die Straßen zum Meer hinunter werden zu Flüssen.",
      "A la una, en la universidad, el cielo se pone negro. No gris. Negro. Luego se abre. Las calles que bajan al mar se convierten en ríos.",
      "At one o'clock, at the university, the sky turns black. Not grey. Black. Then it opens. The streets running down to the sea become rivers."),
    Z("Βρέχει πολύ. Φυσάει. Η Έμμα δεν έχει ομπρέλα. Είναι μούσκεμα.", "Es regnet stark. Es ist windig. Emma hat keinen Schirm. Sie ist klatschnass.", "Llueve mucho. Hace viento. Emma no tiene paraguas. Está empapada.", "It's pouring. It's windy. Emma has no umbrella. She's soaked.", "Vréchi polí. Fisái. I Émma den échi ombréla. Íne moúskema."),
    Z("Οι δρόμοι είναι ποτάμια.", "Die Straßen sind Flüsse.", "Las calles son ríos.", "The streets are rivers.", "I drómi íne potámia."),
    N("Emma steht im Eingang der Fakultät und sieht zu, wie ein Plastikstuhl die Straße hinunterschwimmt, Richtung Meer.",
      "Emma, en la entrada de la facultad, ve cómo una silla de plástico baja calle abajo nadando, rumbo al mar.",
      "Emma stands in the faculty doorway and watches a plastic chair float down the street towards the sea."),
    Z("—Δεν έχεις ομπρέλα; Είσαι Αυστριακή ή ψάρι;", "Du hast keinen Schirm? Bist du Österreicherin oder ein Fisch?", "¿No tienes paraguas? ¿Eres austriaca o un pez?", "No umbrella? Are you Austrian or a fish?", "—Den échis ombréla? Íse Afstriakí i psári?"),
    Z("—Έλα, πάμε για καφέ. Εγώ κερνάω.", "Komm, wir gehen einen Kaffee trinken. Ich lade dich ein.", "Venga, vamos a tomar un café. Invito yo.", "Come on, let's get a coffee. My treat.", "—Éla, páme gia kafé. Egó kernáo."),
    N("Das ist Marina, trocken, unter einem Schirm mit Sonnenblumen. Am Abend steht Frau Roula vor Emmas Tür. Mit einem Topf.",
      "Es Marina, seca, bajo un paraguas de girasoles. Por la noche, la señora Rula está en la puerta de Emma. Con una olla.",
      "That's Marina, dry, under an umbrella covered in sunflowers. In the evening Mrs Roula is at Emma's door. With a pot."),
    Z("—Τι σου είπα; Έλα, φάε σούπα. Ζεστή.", "Was habe ich dir gesagt? Komm, iss Suppe. Heiß.", "¿Qué te dije? Venga, tómate la sopa. Calentita.", "What did I tell you? Come on, have some soup. Hot.", "—Ti sou ípa? Éla, fáe soúpa. Zestí."),
    Z("—Καλή ιδέα. Ευχαριστώ, κυρία Ρούλα. Τα λέμε αύριο.", "Gute Idee. Danke, Frau Roula. Bis morgen.", "Buena idea. Gracias, señora Rula. Hasta mañana.", "Good idea. Thank you, Mrs Roula. See you tomorrow.", "—Kalí idéa. Efcharistó, kiría Roúla. Ta léme ávrio."),
    N("Emma niest. Einmal. Zweimal. Dreimal. Von unten, durch den Fußboden:",
      "Emma estornuda. Una vez. Dos. Tres. Desde abajo, a través del suelo:",
      "Emma sneezes. Once. Twice. Three times. From downstairs, through the floor:"),
    Z("—Γείτσες! Πάρε και μέλι!", "Gesundheit! Nimm auch Honig!", "¡Jesús! ¡Y toma miel!", "Bless you! Have some honey too!", "—Yítses! Páre ke méli!"),
    Z("Ο Όλυμπος έχει πάντα δίκιο.", "Der Olymp hat immer recht.", "El Olimpo siempre tiene razón.", "Olympus is always right.", "O Ólimbos échi pánda díkio.")
  ]),

  // ── Station 8 · ARZT ────────────────────────────────────────────────
  S('fundament', 8, 'arzt', "Περαστικά",
    "Fieber, zwei Tage vor dem Termin. Im Gesundheitszentrum wartet eine neue Abkürzung — und ein Rezept für doppelte Eile.",
    "Fiebre, dos días antes de la cita. En el centro de salud la espera una sigla nueva — y una receta para ir el doble de rápido.",
    "A fever, two days before the appointment. At the health centre a new abbreviation is waiting — and a prescription for double speed.",
  [
    N("Dienstag. Emma wacht auf, und ihr Kopf ist aus Beton.",
      "Martes. Emma se despierta y tiene la cabeza de hormigón.",
      "Tuesday. Emma wakes up, and her head is made of concrete."),
    Z("Η Έμμα έχει πυρετό. Τριάντα οκτώ και πέντε.", "Emma hat Fieber. Achtunddreißig Komma fünf.", "Emma tiene fiebre. Treinta y ocho y medio.", "Emma has a temperature. Thirty-eight point five.", "I Émma échi piretó. Triánda októ ke pénde."),
    Z("Η κυρία Ρούλα παίρνει την Έμμα στο κέντρο υγείας. Με ταξί.", "Frau Roula bringt Emma ins Gesundheitszentrum. Mit dem Taxi.", "La señora Rula lleva a Emma al centro de salud. En taxi.", "Mrs Roula takes Emma to the health centre. By taxi.", "I kiría Roúla pérni tin Émma sto kéndro iyías. Me taxí."),
    N("Am Rückspiegel des Taxis: ein Doppeladler. Emma ist zu müde, um sich zu wundern.",
      "En el retrovisor del taxi: un águila bicéfala. Emma está demasiado cansada para extrañarse.",
      "On the taxi's mirror: a double-headed eagle. Emma is too tired to be surprised."),
    Z("—Βιεννέζα! Τι έχετε; Είστε άρρωστη; Ο ΠΑΟΚ έχασε, κι εγώ είμαι άρρωστος.", "Wienerin! Was haben Sie? Sind Sie krank? PAOK hat verloren, ich bin auch krank.", "¡Vienesa! ¿Qué le pasa? ¿Está mala? El PAOK ha perdido, y yo también estoy malo.", "Viennese! What's wrong? Are you ill? PAOK lost, so I'm ill too.", "—Vienéza! Ti échete? Íste árrosti? O PAOK échase, ki egó íme árrostos."),
    Z("—Στο κέντρο υγείας. Γρήγορα, παρακαλώ.", "Zum Gesundheitszentrum. Schnell, bitte.", "Al centro de salud. Rápido, por favor.", "To the health centre. Quickly, please.", "—Sto kéndro iyías. Grígora, parakaló."),
    Z("—Γρήγορα; Στη Θεσσαλονίκη; Θα δούμε.", "Schnell? In Thessaloniki? Mal sehen.", "¿Rápido? ¿En Tesalónica? Ya veremos.", "Quickly? In Thessaloniki? We'll see.", "—Grígora? Sti Thessaloníki? Tha doúme."),
    N("Dann fährt er so vorsichtig wie nie, weicht jedem Schlagloch aus und nimmt am Ende kein Geld. Für Kranke und PAOK-Fans umsonst, sagt er. Emma ist nur eins von beidem.",
      "Luego conduce con más cuidado que nunca, esquiva cada bache y al final no le cobra. Gratis para enfermos y para los del PAOK, dice. Emma solo es una de las dos cosas.",
      "Then he drives more carefully than ever, avoids every pothole and won't take any money at the end. Free for the sick and for PAOK fans, he says. Emma is only one of the two."),
    Z("—Ευχαριστώ, Στέλιο. Και… ΠΑΟΚ!", "Danke, Stelios. Und … PAOK!", "Gracias, Stelios. Y… ¡PAOK!", "Thank you, Stelios. And… PAOK!", "—Efcharistó, Stélio. Ke… PAOK!"),
    N("Stelios. Thessaloniki hat eine Million Einwohner, aber offenbar nur ein Taxi. Im Gesundheitszentrum: Plastikstühle, ein Kind mit Gips, ein Schalter.",
      "Stelios. Tesalónica tiene un millón de habitantes, pero por lo visto un solo taxi. En el centro de salud: sillas de plástico, un niño con escayola, una ventanilla.",
      "Stelios. Thessaloniki has a million inhabitants but apparently only one taxi. At the health centre: plastic chairs, a child with a cast, a counter."),
    Z("—Καλημέρα. Έχετε ΑΜΚΑ;", "Guten Morgen. Haben Sie eine AMKA?", "Buenos días. ¿Tiene AMKA?", "Good morning. Do you have an AMKA?", "—Kaliméra. Échete ÁMKA?"),
    Z("—Τι είναι ΑΜΚΑ;", "Was ist eine AMKA?", "¿Qué es el AMKA?", "What's an AMKA?", "—Ti íne ÁMKA?"),
    N("Die Sozialversicherungsnummer. Vier Buchstaben. Noch eine Nummer, ohne die man niemand ist. Emma hat sie nicht. Frau Roula beugt sich über den Schalter und sagt etwas Schnelles. Die Frau dahinter seufzt.",
      "El número de la Seguridad Social. Cuatro letras. Otro número sin el que uno no es nadie. Emma no lo tiene. La señora Rula se inclina sobre la ventanilla y dice algo rápido. La mujer de detrás suspira.",
      "The social security number. Four letters. Another number without which you're nobody. Emma doesn't have one. Mrs Roula leans over the counter and says something fast. The woman behind it sighs."),
    Z("—Δεν πειράζει. Το διαβατήριό σας, παρακαλώ.", "Macht nichts. Ihren Pass, bitte.", "No pasa nada. Su pasaporte, por favor.", "Never mind. Your passport, please.", "—Den pirázi. To diavatírió sas, parakaló."),
    N("Die Ärztin ist jung und hat Ringe unter den Augen, die nach Nachtdienst aussehen.",
      "La médica es joven y tiene unas ojeras de guardia nocturna.",
      "The doctor is young, with the kind of shadows under her eyes that come from night shifts."),
    Z("—Τι σας συμβαίνει;", "Was fehlt Ihnen?", "¿Qué le pasa?", "What seems to be the problem?", "—Ti sas simvéni?"),
    Z("—Με πονάει το κεφάλι. Και ο λαιμός.", "Ich habe Kopfschmerzen. Und Halsschmerzen.", "Me duele la cabeza. Y la garganta.", "I've got a headache. And a sore throat.", "—Me ponái to kefáli. Ke o lemós."),
    Z("—Από πότε;", "Seit wann?", "¿Desde cuándo?", "Since when?", "—Apó póte?"),
    Z("—Από χθες. Από τη βροχή.", "Seit gestern. Seit dem Regen.", "Desde ayer. Desde la lluvia.", "Since yesterday. Since the rain.", "—Apó chthes. Apó ti vrochí."),
    Z("—Έχετε πυρετό;", "Haben Sie Fieber?", "¿Tiene fiebre?", "Have you got a temperature?", "—Échete piretó?"),
    Z("—Ναι. Τριάντα οκτώ και πέντε.", "Ja. Achtunddreißig Komma fünf.", "Sí. Treinta y ocho y medio.", "Yes. Thirty-eight point five.", "—Ne. Triánda októ ke pénde."),
    N("Ne. Emma merkt es erst hinterher: Diesmal hat ihr Kopf nicht gezuckt. Das Fieber vielleicht. Oder zwei Wochen Thessaloniki.",
      "Ne. Emma se da cuenta después: esta vez no ha dado el respingo. Quizá sea la fiebre. O dos semanas en Tesalónica.",
      "Ne. Emma only notices afterwards: this time her head didn't twitch. Maybe the fever. Or two weeks of Thessaloniki."),
    Z("—Ανοίξτε το στόμα. Πείτε «α».", "Machen Sie den Mund auf. Sagen Sie »A«.", "Abra la boca. Diga «a».", "Open your mouth. Say “ah”.", "—Aníxte to stóma. Píte «a»."),
    Z("—Είναι ένα κρυολόγημα. Τίποτα σοβαρό. Σας γράφω μια συνταγή.", "Es ist eine Erkältung. Nichts Ernstes. Ich schreibe Ihnen ein Rezept.", "Es un resfriado. Nada grave. Le hago una receta.", "It's a cold. Nothing serious. I'll write you a prescription.", "—Íne éna kriolóyima. Típota sovaró. Sas gráfo mia sindayí."),
    Z("—Ένα χάπι τρεις φορές την ημέρα. Και πολύ νερό. Δύο μέρες στο σπίτι.", "Eine Tablette dreimal am Tag. Und viel Wasser. Zwei Tage zu Hause.", "Una pastilla tres veces al día. Y mucha agua. Dos días en casa.", "One tablet three times a day. And plenty of water. Two days at home.", "—Éna chápi tris forés tin iméra. Ke polí neró. Dío méres sto spíti."),
    Z("—Δύο μέρες; Την Πέμπτη έχω ραντεβού στην εφορία!", "Zwei Tage? Am Donnerstag habe ich einen Termin beim Finanzamt!", "¿Dos días? ¡El jueves tengo cita en Hacienda!", "Two days? On Thursday I've got an appointment at the tax office!", "—Dío méres? Tin Pémbti écho randevoú stin eforía!"),
    Z("—Στην εφορία; Τότε πάρτε δύο χάπια.", "Beim Finanzamt? Dann nehmen Sie zwei Tabletten.", "¿En Hacienda? Entonces tómese dos pastillas.", "At the tax office? Then take two tablets.", "—Stin eforía? Tóte párte dío chápia."),
    N("Sie lächelt nicht. Erst an der Tür versteht Emma, dass es ein Witz war. Glaubt sie.",
      "No sonríe. Solo en la puerta entiende Emma que era una broma. O eso cree.",
      "She doesn't smile. Only at the door does Emma realise it was a joke. She thinks."),
    Z("—Ευχαριστώ, γιατρέ.", "Danke, Frau Doktor.", "Gracias, doctora.", "Thank you, doctor.", "—Efcharistó, giatré."),
    Z("—Καλημέρα. Έχω μια συνταγή.", "Guten Morgen. Ich habe ein Rezept.", "Buenos días. Tengo una receta.", "Good morning. I've got a prescription.", "—Kaliméra. Écho mia sindayí."),
    Z("Στο φαρμακείο ο φαρμακοποιός δίνει τα χάπια. Και μια καραμέλα για τον λαιμό.", "In der Apotheke gibt ihr der Apotheker die Tabletten. Und ein Bonbon für den Hals.", "En la farmacia, el farmacéutico le da las pastillas. Y un caramelo para la garganta.", "At the chemist's the pharmacist hands over the tablets. And a sweet for her throat.", "Sto farmakío o farmakopiós dídi ta chápia. Ke mia karaméla gia ton lemó."),
    Z("—Πόσες φορές την ημέρα;", "Wie oft am Tag?", "¿Cuántas veces al día?", "How many times a day?", "—Póses forés tin iméra?"),
    Z("—Τρεις. Μετά το φαγητό.", "Dreimal. Nach dem Essen.", "Tres. Después de comer.", "Three. After food.", "—Tris. Metá to fayitó."),
    Z("—Μετά το φαγητό; Αυτό δεν είναι πρόβλημα.", "Nach dem Essen? Das ist kein Problem.", "¿Después de comer? Eso no es problema.", "After food? That's not a problem.", "—Metá to fayitó? Aftó den íne próvlima."),
    N("In dieser Stadt ist »nach dem Essen« ein Dauerzustand.",
      "En esta ciudad, «después de comer» es un estado permanente.",
      "In this city, “after food” is a permanent condition."),
    Z("—Περαστικά!", "Gute Besserung!", "¡Que se mejore!", "Get well soon!", "—Perastiká!"),
    N("Perastiká: Möge es vorübergehen. Am Abend steht wieder ein Topf vor der Tür. Hühnersuppe mit Zitrone. Daneben ein Glas Bergtee, mit einem Zettel in zittriger Schrift:",
      "Perastiká: que pase pronto. Por la noche vuelve a haber una olla en la puerta. Sopa de pollo con limón. Al lado, un tarro de té de montaña con una nota de letra temblorosa:",
      "Perastika: may it pass. In the evening there's another pot outside the door. Chicken soup with lemon. Next to it, a jar of mountain tea with a note in shaky handwriting:"),
    Z("«Σιγά-σιγά. Θανάσης.»", "»Langsam, langsam. Thanasis.«", "«Despacito. Thanasis.»", "“Slowly, slowly. Thanasis.”", "«Sigá-sigá. Thanásis.»"),
    Z("Η Έμμα τρώει τη σούπα, πίνει το τσάι και κοιμάται δώδεκα ώρες.", "Emma isst die Suppe, trinkt den Tee und schläft zwölf Stunden.", "Emma se toma la sopa, se bebe el té y duerme doce horas.", "Emma eats the soup, drinks the tea and sleeps for twelve hours.", "I Émma trói ti soúpa, píni to tsái ke kimáte dódeka óres.")
  ]),

  // ── Station 9 · HOTEL ───────────────────────────────────────────────
  S('fundament', 9, 'hotel', "Νι, όμικρον, βήτα",
    "Der Boiler platzt, das Bad schwimmt — der Vertrag nicht. Zwei Nächte im Hotel und ein Buchstabe, der seit der Antike weicher geworden ist.",
    "Revienta el calentador, el baño se inunda — el contrato no. Dos noches en un hotel y una letra que se ha ablandado desde la Antigüedad.",
    "The water heater bursts, the bathroom floods — the contract doesn't. Two nights in a hotel and a letter that has softened since antiquity.",
  [
    N("Mittwoch, sechs Uhr früh. Das Fieber ist gesunken. Emma schläft tief. Dann:",
      "Miércoles, las seis de la mañana. La fiebre ha bajado. Emma duerme profundamente. Entonces:",
      "Wednesday, six in the morning. The fever has gone down. Emma is sound asleep. Then:"),
    Z("ΜΠΑΜ! Ο θερμοσίφωνας!", "Bumm! Der Boiler!", "¡Pum! ¡El calentador!", "Bang! The water heater!", "BAM! O thermosífonas!"),
    Z("Νερό στο μπάνιο. Νερό στον διάδρομο. Νερό παντού.", "Wasser im Bad. Wasser im Flur. Überall Wasser.", "Agua en el baño. Agua en el pasillo. Agua por todas partes.", "Water in the bathroom. Water in the hall. Water everywhere.", "Neró sto bánio. Neró ston diádromo. Neró pandoú."),
    N("Emma greift nicht nach dem Pass. Nicht nach dem Laptop. Sie greift nach der Klarsichthülle auf dem Tisch. Darin: der Vertrag. Unterschrift, neun Ziffern. Trocken.",
      "Emma no coge el pasaporte. Ni el portátil. Coge la funda de plástico de la mesa. Dentro: el contrato. Firma, nueve cifras. Seco.",
      "Emma doesn't grab her passport. Or her laptop. She grabs the plastic sleeve on the table. Inside it: the contract. Signature, nine digits. Dry."),
    N("Zwei Wochen Arbeit, eine Zugfahrt, ein Kilo Wein. Ein Bad kann man trocknen. Eine Unterschrift aus Veria nicht.",
      "Dos semanas de trabajo, un viaje en tren, un kilo de vino. Un baño se puede secar. Una firma de Veria, no.",
      "Two weeks of work, a train journey, a kilo of wine. You can dry a bathroom. You can't dry a signature from Veria."),
    Z("—Κυρία Ρούλα! Έχω νερό παντού!", "Frau Roula! Bei mir ist überall Wasser!", "¡Señora Rula! ¡Tengo agua por todas partes!", "Mrs Roula! There's water everywhere!", "—Kiría Roúla! Écho neró pandoú!"),
    Z("—Κι εγώ! Από το ταβάνι!", "Bei mir auch! Von der Decke!", "¡Y yo! ¡Del techo!", "So have I! From the ceiling!", "—Ki egó! Apó to taváni!"),
    Z("Η κυρία Ρούλα παίρνει τηλέφωνο τον υδραυλικό.", "Frau Roula ruft den Installateur an.", "La señora Rula llama al fontanero.", "Mrs Roula rings the plumber.", "I kiría Roúla pérni tiléfono ton idravlikó."),
    Z("—Έρχομαι! Σε δέκα λεπτά!", "Ich komme! In zehn Minuten!", "¡Voy! ¡En diez minutos!", "I'm coming! In ten minutes!", "—Érchome! Se déka leptá!"),
    Z("Ο υδραυλικός έρχεται στις έντεκα. Κοιτάζει. Σκέφτεται. Λέει: «Δύο μέρες.»", "Der Installateur kommt um elf. Er schaut. Er denkt nach. Er sagt: »Zwei Tage.«", "El fontanero llega a las once. Mira. Piensa. Dice: «Dos días».", "The plumber arrives at eleven. He looks. He thinks. He says: “Two days.”", "O idravlikós érchete stis éndeka. Kitázi. Skéftete. Léi: «Dío méres.»"),
    N("Zehn Minuten auf Griechisch: drei Stunden. Frau Roula zieht zu ihrer Tochter nach Kalamaria. Emma sucht ein Hotel.",
      "Diez minutos en griego: tres horas. La señora Rula se va a casa de su hija, en Kalamaria. Emma busca un hotel.",
      "Ten minutes in Greek: three hours. Mrs Roula moves in with her daughter in Kalamaria. Emma looks for a hotel."),
    Z("ΞΕΝΟΔΟΧΕΙΟ «ΑΣΤΕΡΙ» · 2 ΑΣΤΕΡΙΑ", "Hotel »Asteri« · 2 Sterne", "Hotel «Asteri» · 2 estrellas", "Hotel “Asteri” · 2 stars", "XENODOCHÍO «ASTÉRI» · 2 ASTÉRIA"),
    N("»Asteri« heißt Stern. Das Hotel hat zwei, beide ein wenig verblasst, wie Sterne kurz vor Sonnenaufgang.",
      "«Asteri» significa estrella. El hotel tiene dos, los dos algo desvaídos, como estrellas poco antes del amanecer.",
      "“Asteri” means star. The hotel has two, both a little faded, like stars just before sunrise."),
    Z("—Καλησπέρα. Έχετε ένα μονόκλινο δωμάτιο;", "Guten Tag. Haben Sie ein Einzelzimmer?", "Buenas tardes. ¿Tiene una habitación individual?", "Good afternoon. Have you got a single room?", "—Kalispéra. Échete éna monóklino domátio?"),
    Z("—Καλώς ήρθατε στο «Αστέρι». Ναι, έχουμε.", "Willkommen im »Asteri«. Ja, haben wir.", "Bienvenida al «Asteri». Sí, tenemos.", "Welcome to the “Asteri”. Yes, we have.", "—Kalós írthate sto «Astéri». Ne, échoume."),
    Z("—Για πόσες νύχτες;", "Für wie viele Nächte?", "¿Para cuántas noches?", "For how many nights?", "—Gia póses níchtes?"),
    Z("—Για δύο νύχτες.", "Für zwei Nächte.", "Para dos noches.", "For two nights.", "—Gia dío níchtes."),
    Z("—Εντάξει. Το όνομά σας;", "In Ordnung. Ihr Name?", "De acuerdo. ¿Su nombre?", "All right. Your name?", "—Endáxi. To ónomá sas?"),
    Z("—Νόβακ. Έμμα Νόβακ.", "Novak. Emma Novak.", "Novak. Emma Novak.", "Novak. Emma Novak.", "—Nóvak. Émma Nóvak."),
    Z("—Είστε εδώ για διακοπές;", "Sind Sie im Urlaub hier?", "¿Está aquí de vacaciones?", "Are you here on holiday?", "—Íste edó gia diakopés?"),
    Z("—Όχι. Στο σπίτι μου έχει πρόβλημα με το νερό. Πολύ νερό.", "Nein. In meiner Wohnung gibt es ein Problem mit dem Wasser. Zu viel Wasser.", "No. En mi piso hay un problema con el agua. Demasiada agua.", "No. There's a problem with the water in my flat. Too much water.", "—Óchi. Sto spíti mou échi próvlima me to neró. Polí neró."),
    Z("—Πώς γράφεται;", "Wie schreibt man das?", "¿Cómo se escribe?", "How do you spell that?", "—Pós gráfete?"),
    N("Emma buchstabiert, wie in ihrem Altgriechischkurs in Wien: »Ny, Omikron, Beta …« Die Rezeptionistin schaut sie an, als käme sie aus einem Museum.",
      "Emma deletrea como en su curso de griego antiguo en Viena: «Ny, ómicron, beta…». La recepcionista la mira como si viniera de un museo.",
      "Emma spells it the way she learnt in her Ancient Greek course in Vienna: “Nu, omicron, beta…” The receptionist looks at her as if she had stepped out of a museum."),
    Z("—Βήτα. Όχι «μπέτα». Νι, όμικρον, βήτα, άλφα, κάπα.", "Wita. Nicht »Beta«. Ni, Omikron, Wita, Alfa, Kapa.", "Vita. No «beta». Ni, ómicron, vita, alfa, kapa.", "Vita. Not “beta”. Ni, omicron, vita, alfa, kapa.", "—Víta. Óchi «béta». Ni, ómikron, víta, álfa, kápa."),
    N("Im Kurs war Beta ein B, wie in Butter. Zweitausend Jahre später ist es weich geworden, ein W. Die Sprache hat sich bewegt. Emma noch nicht ganz.",
      "En el curso, la beta era una b, como en «bota». Dos mil años después se ha vuelto blanda, una v. La lengua se ha movido. Emma, todavía no del todo.",
      "In the course, beta was a b, as in butter. Two thousand years later it has gone soft, a v. The language has moved on. Emma, not quite yet."),
    Z("—Το πρωινό περιλαμβάνεται;", "Ist das Frühstück inbegriffen?", "¿Está incluido el desayuno?", "Is breakfast included?", "—To proinó perilamvánete?"),
    Z("—Ναι. Από τις επτά μέχρι τις δέκα. Έχει μπουγάτσα, τυρόπιτα, γιαούρτι με μέλι.", "Ja. Von sieben bis zehn. Es gibt Bougatsa, Käsepastete, Joghurt mit Honig.", "Sí. De siete a diez. Hay bugatsa, empanada de queso, yogur con miel.", "Yes. From seven to ten. There's bougatsa, cheese pie, yoghurt with honey.", "—Ne. Apó tis eptá méchri tis déka. Échi bougátsa, tirópita, giaoúrti me méli."),
    Z("—Ευχαριστώ. Σε ποιον όροφο είναι το δωμάτιο;", "Danke. In welchem Stock ist das Zimmer?", "Gracias. ¿En qué planta está la habitación?", "Thank you. Which floor is the room on?", "—Efcharistó. Se pion órofo íne to domátio?"),
    Z("—Στον δεύτερο όροφο. Δωμάτιο διακόσια δεκατρία. Το ασανσέρ είναι χαλασμένο.", "Im zweiten Stock. Zimmer zweihundertdreizehn. Der Aufzug ist kaputt.", "En la segunda planta. Habitación doscientos trece. El ascensor está estropeado.", "On the second floor. Room two hundred and thirteen. The lift is out of order.", "—Ston déftero órofo. Domátio diakósia dekatría. To asansér íne chalasméno."),
    Z("—Ορίστε το κλειδί. Καλή διαμονή!", "Hier ist der Schlüssel. Angenehmen Aufenthalt!", "Aquí tiene la llave. ¡Feliz estancia!", "Here's the key. Enjoy your stay!", "—Oríste to klidí. Kalí diamoní!"),
    Z("Η Έμμα ανεβαίνει τις σκάλες με τη βαλίτσα. Ένας όροφος. Δύο όροφοι.", "Emma steigt mit dem Koffer die Treppe hinauf. Ein Stock. Zwei Stockwerke.", "Emma sube las escaleras con la maleta. Una planta. Dos plantas.", "Emma climbs the stairs with her suitcase. One floor. Two floors.", "I Émma anevéni tis skáles me ti valítsa. Énas órofos. Dío órofi."),
    Z("Το δωμάτιο είναι μικρό, αλλά καθαρό.", "Das Zimmer ist klein, aber sauber.", "La habitación es pequeña, pero está limpia.", "The room is small but clean.", "To domátio íne mikró, allá katharó."),
    N("Zimmer 213: ein Bett, ein Fenster zum Hof, ein Bild vom Weißen Turm. Emma legt die Klarsichthülle auf den Nachttisch, daneben den Pass, daneben einen Zettel:",
      "Habitación 213: una cama, una ventana al patio, un cuadro de la Torre Blanca. Emma deja la funda de plástico en la mesilla, al lado el pasaporte y al lado una nota:",
      "Room 213: a bed, a window onto the courtyard, a picture of the White Tower. Emma puts the plastic sleeve on the bedside table, the passport next to it, and next to that a note:"),
    Z("Πέμπτη, 9:00. Εφορία. Ευθεία, δεξιά, φανάρι, αριστερά, γωνία.", "Donnerstag, 9:00. Finanzamt. Geradeaus, rechts, Ampel, links, Ecke.", "Jueves, 9:00. Hacienda. Recto, derecha, semáforo, izquierda, esquina.", "Thursday, 9:00. Tax office. Straight on, right, lights, left, corner.", "Pémbti, 9:00. Eforía. Efthía, dexiá, fanári, aristerá, gonía."),
    Z("Το βράδυ η Έμμα τρώει μια τυρόπιτα στο κρεβάτι. Δεν πεινάει. Αλλά εδώ πρέπει να τρως.", "Am Abend isst Emma im Bett eine Käsepastete. Sie hat keinen Hunger. Aber hier muss man essen.", "Por la noche, Emma se come una empanada de queso en la cama. No tiene hambre. Pero aquí hay que comer.", "In the evening Emma eats a cheese pie in bed. She isn't hungry. But here you have to eat.", "To vrádi i Émma trói mia tirópita sto kreváti. Den pinái. Allá edó prépi na tros."),
    N("Das Handy piept. Eine Nachricht vom Installateur:",
      "El móvil pita. Un mensaje del fontanero:",
      "Her phone beeps. A message from the plumber:"),
    Z("«Ο θερμοσίφωνας έρχεται αύριο. Σιγά-σιγά.»", "»Der Boiler kommt morgen. Langsam, langsam.«", "«El calentador llega mañana. Despacito.»", "“The water heater arrives tomorrow. Slowly, slowly.”", "«O thermosífonas érchete ávrio. Sigá-sigá.»")
  ]),

  // ── Station 10 · FAMILIE ────────────────────────────────────────────
  S('fundament', 10, 'familie', "Καλή συνέχεια",
    "Der Termin. Ein Beamter mit PAOK-Tasse und einer zwölfjährigen Tochter, neun Ziffern — und am Abend kündigt sich die Familie an.",
    "La cita. Un funcionario con taza del PAOK y una hija de doce años, nueve cifras — y por la noche la familia anuncia su visita.",
    "The appointment. A clerk with a PAOK mug and a twelve-year-old daughter, nine digits — and in the evening the family announces a visit.",
  [
    Z("Πέμπτη, είκοσι τέσσερις Οκτωβρίου. Η Έμμα δεν έχει πυρετό.", "Donnerstag, der vierundzwanzigste Oktober. Emma hat kein Fieber.", "Jueves, 24 de octubre. Emma no tiene fiebre.", "Thursday the twenty-fourth of October. Emma has no temperature.", "Pémbti, íkosi tésseris Oktovríou. I Émma den échi piretó."),
    Z("—Μια μπουγάτσα με κρέμα, παρακαλώ. Και έναν φραπέ μέτριο με γάλα.", "Eine Bougatsa mit Creme, bitte. Und einen Frappé, mittel, mit Milch.", "Una bugatsa de crema, por favor. Y un frapé con poco azúcar y leche.", "A custard bougatsa, please. And a frappé, medium, with milk.", "—Mia bougátsa me kréma, parakaló. Ke énan frapé métrio me gála."),
    N("Zweieinhalb Wochen. Den Satz sagt sie inzwischen, ohne nachzudenken. Um halb neun steht sie vor der Glastür. Geradeaus, rechts, Ampel, links, Ecke. Früh.",
      "Dos semanas y media. Esa frase ya la dice sin pensar. A las ocho y media está delante de la puerta de cristal. Recto, derecha, semáforo, izquierda, esquina. Temprano.",
      "Two and a half weeks. She says that sentence without thinking now. At half past eight she's outside the glass door. Straight on, right, lights, left, corner. Early."),
    Z("Στην οθόνη: Β112. Γραφείο τρία.", "Auf dem Bildschirm: B112. Schalter drei.", "En la pantalla: B112. Ventanilla tres.", "On the screen: B112. Desk three.", "Stin othóni: V112. Grafío tría."),
    N("Β wie Wita. Emma lächelt. Am Schalter drei: ein Mann um die fünfzig, Schnurrbart, das Foto eines Mädchens am Bildschirm — und eine Tasse mit Doppeladler.",
      "Β de vita. Emma sonríe. En la ventanilla tres: un hombre de unos cincuenta, bigote, la foto de una niña junto a la pantalla… y una taza con un águila bicéfala.",
      "Β for vita. Emma smiles. At desk three: a man of about fifty, moustache, a photo of a girl by his screen — and a mug with a double-headed eagle."),
    Z("—Καλημέρα. Έχω ραντεβού στις εννιά. Για ΑΦΜ.", "Guten Morgen. Ich habe einen Termin um neun. Für ein AFM.", "Buenos días. Tengo cita a las nueve. Para el AFM.", "Good morning. I have an appointment at nine. For an AFM.", "—Kaliméra. Écho randevoú stis enniá. Gia afimí."),
    Z("—Διαβατήριο; Μισθωτήριο;", "Pass? Mietvertrag?", "¿Pasaporte? ¿Contrato de alquiler?", "Passport? Rental contract?", "—Diavatírio? Misthotírio?"),
    Z("—Ορίστε.", "Bitte schön.", "Aquí tiene.", "Here you are.", "—Oríste."),
    Z("—Σε ζελατίνα! Μπράβο. Γερμανίδα;", "In einer Klarsichthülle! Bravo. Deutsche?", "¡En una funda de plástico! Bravo. ¿Alemana?", "In a plastic sleeve! Bravo. German?", "—Se zelatína! Brávo. Yermanída?"),
    Z("—Όχι. Αυστριακή.", "Nein. Österreicherin.", "No. Austriaca.", "No. Austrian.", "—Óchi. Afstriakí."),
    Z("—Το ίδιο.", "Dasselbe.", "Lo mismo.", "Same thing.", "—To ídio."),
    N("Emma antwortet ohne Worte: Kinn hoch, Augenbrauen hoch, tsk. Der Beamte lacht laut auf. Dann tippt er. Und fragt.",
      "Emma responde sin palabras: barbilla arriba, cejas arriba, tsk. El funcionario suelta una carcajada. Luego teclea. Y pregunta.",
      "Emma answers without words: chin up, eyebrows up, tsk. The clerk bursts out laughing. Then he types. And asks."),
    Z("—Οικογενειακή κατάσταση; Παντρεμένη;", "Familienstand? Verheiratet?", "¿Estado civil? ¿Casada?", "Marital status? Married?", "—Ikoyeniakí katástasi? Pandreméni?"),
    Z("—Όχι. Ελεύθερη.", "Nein. Ledig.", "No. Soltera.", "No. Single.", "—Óchi. Eléftheri."),
    N("Eléftheri: ledig. Und frei. Wie das Taxi am ersten Tag.",
      "Eléftheri: soltera. Y libre. Como el taxi del primer día.",
      "Eleftheri: single. And free. Like the taxi on the first day."),
    Z("—Έχετε αδέρφια;", "Haben Sie Geschwister?", "¿Tiene hermanos?", "Have you got any brothers or sisters?", "—Échete adérfia?"),
    Z("—Ναι, έναν αδερφό. Τον λένε Φέλιξ.", "Ja, einen Bruder. Er heißt Felix.", "Sí, un hermano. Se llama Felix.", "Yes, one brother. His name is Felix.", "—Ne, énan aderfó. Ton léne Félix."),
    Z("—Πόσο χρονών είναι;", "Wie alt ist er?", "¿Cuántos años tiene?", "How old is he?", "—Póso chronón íne?"),
    Z("—Δώδεκα.", "Zwölf.", "Doce.", "Twelve.", "—Dódeka."),
    Z("—Δώδεκα! Σαν την κόρη μου. Δύσκολη ηλικία.", "Zwölf! Wie meine Tochter. Ein schwieriges Alter.", "¡Doce! Como mi hija. Una edad difícil.", "Twelve! Like my daughter. A difficult age.", "—Dódeka! San tin kóri mou. Dískoli ilikía."),
    Z("—Πολύ δύσκολη. Αλλά ο Φέλιξ είναι πολύ γλυκός.", "Sehr schwierig. Aber Felix ist sehr lieb.", "Muy difícil. Pero Felix es un encanto.", "Very difficult. But Felix is very sweet.", "—Polí dískoli. Allá o Félix íne polí glikós."),
    Z("—Και οι γονείς σας;", "Und Ihre Eltern?", "¿Y sus padres?", "And your parents?", "—Ke i gonís sas?"),
    Z("—Μένουν στη Βιέννη. Ο πατέρας μου είναι συνταξιούχος. Ήταν οδηγός τραμ.", "Sie wohnen in Wien. Mein Vater ist Rentner. Er war Straßenbahnfahrer.", "Viven en Viena. Mi padre está jubilado. Era conductor de tranvía.", "They live in Vienna. My father is retired. He was a tram driver.", "—Ménoun sti Viénni. O patéras mou íne sindaxioúchos. Ítan odigós tram."),
    Z("—Τραμ! Εμείς έχουμε μετρό. Επιτέλους!", "Straßenbahn! Wir haben eine U-Bahn. Endlich!", "¡Tranvía! Nosotros tenemos metro. ¡Por fin!", "Trams! We've got a metro. At last!", "—Tram! Emís échoume metró. Epitélous!"),
    N("Dreißig Jahre hat Thessaloniki auf seine U-Bahn gewartet, und beim Graben stießen die Bagger auf die halbe byzantinische Stadt. Emma weiß das. Sie hat ihre Masterarbeit darüber geschrieben. Sie sagt nichts. Der Drucker summt.",
      "Tesalónica esperó treinta años su metro, y al excavar las máquinas se toparon con media ciudad bizantina. Emma lo sabe. Hizo el trabajo de fin de máster sobre eso. No dice nada. La impresora zumba.",
      "Thessaloniki waited thirty years for its metro, and the diggers struck half a Byzantine city along the way. Emma knows. She wrote her master's thesis on it. She says nothing. The printer hums."),
    Z("Ένα χαρτί. Πάνω: εννιά αριθμοί. Το ΑΦΜ της Έμμας.", "Ein Blatt Papier. Darauf: neun Ziffern. Emmas AFM.", "Un papel. Encima: nueve cifras. El AFM de Emma.", "A sheet of paper. On it: nine digits. Emma's AFM.", "Éna chartí. Páno: enniá arithmí. To afimí tis Émmas."),
    Z("—Έτοιμο. Καλή συνέχεια!", "Fertig. Alles Gute weiterhin!", "Listo. ¡Que le vaya bien!", "Done. All the best!", "—Étimo. Kalí sinéchia!"),
    N("Kalí sinéchia: eine gute Fortsetzung. Man wünscht es dem Tag, der Arbeit, dem Leben. Als wäre jeder Abschied nur eine Kapitelgrenze.",
      "Kalí sinéchia: una buena continuación. Se le desea al día, al trabajo, a la vida. Como si cada despedida fuera solo un cambio de capítulo.",
      "Kali sinechia: a good continuation. You wish it to the day, to the work, to life. As if every goodbye were only the end of a chapter."),
    Z("Το βράδυ, στο δωμάτιο διακόσια δεκατρία, η Έμμα μιλάει με την οικογένειά της.", "Am Abend, in Zimmer zweihundertdreizehn, spricht Emma mit ihrer Familie.", "Por la noche, en la habitación doscientos trece, Emma habla con su familia.", "In the evening, in room two hundred and thirteen, Emma talks to her family.", "To vrádi, sto domátio diakósia dekatría, i Émma milái me tin ikoyénia tis."),
    N("Drei Gesichter vor der Kamera in Wien-Favoriten: Brigitte, Karl, Felix. Felix hat auf YouTube Griechisch geübt. Er will angeben.",
      "Tres caras delante de la cámara en Viena-Favoriten: Brigitte, Karl, Felix. Felix ha practicado griego en YouTube. Quiere presumir.",
      "Three faces in front of the camera in Vienna-Favoriten: Brigitte, Karl, Felix. Felix has been practising Greek on YouTube. He wants to show off."),
    Z("—Γεια σου, Έμμα! Τι κάνεις;", "Hallo, Emma! Wie geht's?", "¡Hola, Emma! ¿Qué tal?", "Hi, Emma! How are you?", "—Giá sou, Émma! Ti kánis?"),
    Z("—Γεια σου, Φέλιξ! Πολύ καλά. Έχω ΑΦΜ!", "Hallo, Felix! Sehr gut. Ich habe ein AFM!", "¡Hola, Felix! Muy bien. ¡Tengo AFM!", "Hi, Felix! Very well. I've got an AFM!", "—Giá sou, Félix! Polí kalá. Écho afimí!"),
    Z("—Τι είναι ΑΦΜ;", "Was ist ein AFM?", "¿Qué es un AFM?", "What's an AFM?", "—Ti íne afimí?"),
    Z("—Ένας αριθμός. Χωρίς ΑΦΜ δεν είσαι κανένας.", "Eine Nummer. Ohne AFM bist du niemand.", "Un número. Sin AFM no eres nadie.", "A number. Without an AFM you're nobody.", "—Énas arithmós. Chorís afimí den íse kanénas."),
    Z("—Η μαμά ρωτάει: τρως καλά;", "Mama fragt: Isst du ordentlich?", "Mamá pregunta: ¿comes bien?", "Mum's asking: are you eating properly?", "—I mamá rotái: tros kalá?"),
    Z("—Φέλιξ, εδώ όλοι μου δίνουν φαγητό. Η κυρία Ρούλα, ο κυρ-Θανάσης, η κυρία Δέσποινα, η κυρία Βούλα…", "Felix, hier geben mir alle zu essen. Frau Roula, Herr Thanasis, Frau Despina, Frau Voula …", "Felix, aquí todo el mundo me da de comer. La señora Rula, el señor Thanasis, la señora Despina, la señora Vula…", "Felix, everyone here feeds me. Mrs Roula, Mr Thanasis, Mrs Despina, Mrs Voula…", "—Félix, edó óli mou dínoun fayitó. I kiría Roúla, o kir-Thanásis, i kiría Déspina, i kiría Voúla…"),
    N("Emma lacht so sehr, dass sie husten muss. Dann schiebt sich ihr Vater vor die Kamera, feierlich wie bei einer Durchsage: »Wir haben gebucht. Zu Ostern kommen wir. Alle drei.«",
      "Emma se ríe tanto que le da la tos. Luego su padre se pone delante de la cámara, solemne como en un aviso por megafonía: «Hemos reservado. En Semana Santa vamos. Los tres».",
      "Emma laughs so hard she starts coughing. Then her father moves in front of the camera, solemn as a tannoy announcement: “We've booked. We're coming at Easter. All three of us.”"),
    Z("—Το Πάσχα; Έρχεστε το Πάσχα; Όλοι;", "Zu Ostern? Ihr kommt zu Ostern? Alle?", "¿En Semana Santa? ¿Venís en Semana Santa? ¿Todos?", "At Easter? You're coming at Easter? All of you?", "—To Páscha? Ércheste to Páscha? Óli?"),
    Z("—Ναι!", "Ja!", "¡Sí!", "Yes!", "—Ne!"),
    N("Felix sagt es. Ne. Und es heißt ja. Emmas Kopf zuckt nicht mehr.",
      "Lo dice Felix. Ne. Y significa sí. La cabeza de Emma ya no da el respingo.",
      "Felix says it. Ne. And it means yes. Emma's head doesn't twitch any more."),
    Z("Η οικογένειά μου μένει στη Βιέννη. Εγώ μένω στη Θεσσαλονίκη. Έχω ΑΦΜ. Είμαι κάποια.", "Meine Familie wohnt in Wien. Ich wohne in Thessaloniki. Ich habe ein AFM. Ich bin jemand.", "Mi familia vive en Viena. Yo vivo en Tesalónica. Tengo AFM. Soy alguien.", "My family lives in Vienna. I live in Thessaloniki. I have an AFM. I'm somebody.", "I ikoyénia mou méni sti Viénni. Egó méno sti Thessaloníki. Écho afimí. Íme kápia.")
  ])

  ];
})(window);

/* ──────────────────────────────────────────────────────────────────────────
   lr-el/emma-2.js — „Η Έμμα στη Θεσσαλονίκη" · Teil II · aufbau + Epilog
   Zielsprache Griechisch · Muttersprachen de (Hochdeutsch), es (castellano de
   España), en (British). Stationen 11–20 = die zehn Themen auf A2 (Ostern,
   die Familie aus Wien kommt), Station 21 = Epilog «Θα τα πούμε», 100 % Prosa.
   N(de, es, en) = Erzählung in der Muttersprache · Z(el, de, es, en, lt) =
   Griechisch + Brücken (+ Umschrift nur bei neuen/schweren Wörtern).
   ────────────────────────────────────────────────────────────────────────── */
(function (w) {
  var K = w.__LR_PARTS_EMMA = w.__LR_PARTS_EMMA || {};
  function N(de, es, en) { return { na: { de: de, es: es, en: en } }; }
  function Z(z, de, es, en, lt) { var o = { z: z }; if (de) o.tr = { de: de, es: es, en: en }; if (lt) o.lt = lt; return o; }
  function P(p) { return { p: p }; }
  function S(level, n, thema, title, tde, tes, ten, body) { return { level: level, n: n, thema: thema, title: title, teaser: { de: tde, es: tes, en: ten }, body: body }; }

  K.teil2 = [

  /* ═════════════════════════════════════════════════════════════════════
     TEIL II · AUFBAU · „Πάσχα" — dieselben zehn Themen auf A2
     Die Familie kommt zu Ostern. Emma fragt, erklärt, übersetzt.
     ═════════════════════════════════════════════════════════════════════ */

  // ── Station 11 · TAXI (A2) ────────────────────────────────────────────
  S("aufbau", 11, "taxi", "Βιάζομαι",
    "Sechs Monate später. Die Familie landet am Dienstag der Karwoche — und die halbe Stadt steht im Stau. Zum Glück fährt Stelios.",
    "Seis meses después. La familia aterriza el Martes Santo y media ciudad está en un atasco. Por suerte, conduce Stelios.",
    "Six months later. The family lands on Holy Tuesday — and half the city is stuck in traffic. Luckily, Stelios is driving.",
  [
    Z("Πέρασαν έξι μήνες. Ήρθε η άνοιξη.", "Sechs Monate vergingen. Es wurde Frühling.", "Pasaron seis meses. Llegó la primavera.", "Six months went by. Spring came.", "Pérasan éxi mínes. Írthe i ánixi."),
    Z("Η Έμμα δεν χανόταν πια στην Άνω Πόλη. Κάθε πρωί έπινε έναν φραπέ, μέτριο με γάλα, στο καφενείο του κυρ-Θανάση.", "Emma verlief sich nicht mehr in der Oberstadt. Jeden Morgen trank sie einen Frappé, mittelsüß mit Milch, im Kafeneio von Herrn Thanasis.", "Emma ya no se perdía en la Ciudad Alta. Cada mañana se tomaba un frapé, con poco azúcar y con leche, en el café del señor Thanasis.", "Emma no longer got lost in the Upper Town. Every morning she had a frappé, medium sweet with milk, at Mr Thanasis's kafeneio."),
    N("Sie hatte eine Steuernummer, ein griechisches Gehalt und einen Mietvertrag, der immer noch in seiner Plastikhülle lag. Und trotzdem schaute sie an diesem Dienstag auf die Uhr wie an ihrem allerersten Tag.",
      "Tenía un número fiscal, un sueldo griego y un contrato de alquiler que seguía guardado en su funda de plástico. Y aun así, aquel martes miraba el reloj como el primer día.",
      "She had a tax number, a Greek salary and a tenancy agreement that still lived in its plastic sleeve. And yet on this Tuesday she kept checking the time just as she had on her very first day."),
    Z("Ήταν Μεγάλη Τρίτη. Η οικογένειά της ερχόταν από τη Βιέννη για το Πάσχα.", "Es war der Dienstag der Karwoche. Ihre Familie kam zu Ostern aus Wien.", "Era Martes Santo. Su familia venía de Viena para pasar la Semana Santa.", "It was Holy Tuesday. Her family was coming from Vienna for Easter.", "Ítan Megáli Tríti. I ikoyénia tis erchótan apó ti Viénni gia to Páscha."),
    N("In diesem Jahr fiel Ostern für Katholiken und Orthodoxe auf denselben Sonntag. Ihre Mutter hatte das als Zeichen genommen.",
      "Aquel año, católicos y ortodoxos celebraban la Pascua el mismo domingo. Su madre lo había tomado como una señal.",
      "That year Catholics and Orthodox celebrated Easter on the same Sunday. Her mother had taken it as a sign."),
    Z("Το αεροπλάνο έφτανε στις επτά παρά είκοσι. Αλλά στις έξι η Έμμα ήταν ακόμα στο πανεπιστήμιο.", "Das Flugzeug kam um zwanzig vor sieben an. Aber um sechs war Emma noch an der Universität.", "El avión llegaba a las siete menos veinte. Pero a las seis Emma seguía en la universidad.", "The plane was due at twenty to seven. But at six Emma was still at the university."),
    N("Die Sitzung hatte »um vier« begonnen. Um vier auf Griechisch, also um Viertel nach fünf. Marina hatte nur mit den Schultern gezuckt: »Willkommen in Thessaloniki. Hier ist vier eine Richtung, keine Uhrzeit.«",
      "La reunión había empezado «a las cuatro». A las cuatro en griego, o sea, a las cinco y cuarto. Marina se había encogido de hombros: «Bienvenida a Tesalónica. Aquí las cuatro son una dirección, no una hora».",
      "The meeting had started “at four”. Four o'clock in Greek, that is, quarter past five. Marina had just shrugged: “Welcome to Thessaloniki. Here four is a direction, not a time.”"),
    Z("Η Έμμα έτρεξε στην Εγνατία και σήκωσε το χέρι. Ένα ταξί σταμάτησε.", "Emma rannte zur Egnatia und hob die Hand. Ein Taxi hielt an.", "Emma corrió a la Egnatia y levantó la mano. Un taxi paró.", "Emma ran to Egnatia Street and put her hand up. A taxi stopped."),
    Z("—Στο αεροδρόμιο, παρακαλώ! Βιάζομαι πολύ.", "Zum Flughafen, bitte! Ich habe es sehr eilig.", "¡Al aeropuerto, por favor! Tengo mucha prisa.", "To the airport, please! I'm in a real hurry.", "—Sto aerodrómio, parakaló! Viázome polí."),
    N("Der Fahrer drehte sich um. Am Rückspiegel hing ein schwarz-weißer Schal mit einem doppelköpfigen Adler. Im Radio lief, natürlich, Fußball.",
      "El conductor se dio la vuelta. Del retrovisor colgaba una bufanda blanca y negra con un águila de dos cabezas. En la radio, cómo no, hablaban de fútbol.",
      "The driver turned round. A black-and-white scarf with a double-headed eagle hung from the rear-view mirror. On the radio, naturally, it was football."),
    Z("—Η Αυστριακή με το ΑΦΜ! Λοιπόν; Το βγάλατε τελικά;", "Die Österreicherin mit der Steuernummer! Und? Haben Sie sie am Ende bekommen?", "¡La austriaca del número fiscal! ¿Y qué? ¿Al final lo sacó?", "The Austrian with the tax number! Well? Did you get it in the end?", "—I Afstriakí me to afimí! Lipón? To vgálate teliká?"),
    Z("—Στέλιο! Ναι, το έβγαλα. Αλλά τώρα αργώ. Η οικογένειά μου φτάνει στις επτά παρά είκοσι.", "Stelios! Ja, ich habe sie bekommen. Aber jetzt bin ich spät dran. Meine Familie landet um zwanzig vor sieben.", "¡Stelios! Sí, lo saqué. Pero ahora llego tarde. Mi familia aterriza a las siete menos veinte.", "Stelios! Yes, I got it. But now I'm late. My family lands at twenty to seven."),
    Z("—Ωχ. Σήμερα έχει πολλή κίνηση. Είναι Μεγάλη Εβδομάδα, όλη η πόλη είναι στα μαγαζιά.", "Oje. Heute ist viel Verkehr. Es ist Karwoche, die ganze Stadt ist in den Geschäften.", "Uf. Hoy hay mucho tráfico. Es Semana Santa, toda la ciudad está de compras.", "Oh dear. There's a lot of traffic today. It's Holy Week, the whole city is out shopping.", "—Och. Símera échi pollí kínisi."),
    Z("—Και τι κάνουμε;", "Und was machen wir?", "¿Y qué hacemos?", "So what do we do?"),
    Z("—Θα πάμε από την παραλία. Είναι πιο γρήγορα. Κρατηθείτε!", "Wir fahren an der Uferstraße entlang. Das geht schneller. Halten Sie sich fest!", "Iremos por el paseo marítimo. Es más rápido. ¡Agárrese!", "We'll go along the seafront. It's quicker. Hold on!", "—Tha páme apó tin paralía. Íne pio grígora. Kratithíte!"),
    Z("—Στέλιο, μου λέτε «Βιεννέζα» από τον Οκτώβριο. Να μιλάμε στον ενικό;", "Stelios, Sie nennen mich seit Oktober »Wienerin«. Wollen wir uns duzen?", "Stelios, me llama «vienesa» desde octubre. ¿Nos tuteamos?", "Stelios, you've been calling me “Viennese” since October. Shall we drop the formalities?", "—Stélio, mou léte «Vienéza» apó ton Októvrio. Na miláme ston enikó?"),
    Z("—Στον ενικό; Ναι, ναι, βέβαια! Τότε… κρατήσου, Έμμα!", "Duzen? Ja, ja, natürlich! Dann … halt dich fest, Emma!", "¿Tutearnos? ¡Sí, sí, claro! Entonces… ¡agárrate, Emma!", "Drop the formalities? Yes, yes, of course! Then… hold on tight, Emma!", "—Ston enikó? Ne, ne, vévea! Tóte… kratísou, Émma!"),
    N("»Na miláme ston enikó?« — wörtlich: »Sollen wir im Singular sprechen?« So bietet man auf Griechisch das Du an. Aus »Kratithíte!« wird »Kratísou!«, und aus dem Taxifahrer ein Freund.",
      "«Na miláme ston enikó?» — literalmente: «¿Hablamos en singular?». Así se propone el tuteo en griego. «Kratithíte!» pasa a ser «Kratísou!», y el taxista, un amigo.",
      "“Na miláme ston enikó?” — literally: “Shall we speak in the singular?” That's how you offer to drop the formal you in Greek. “Kratithíte!” becomes “Kratísou!”, and the taxi driver becomes a friend."),
    Z("Ο Στέλιος έστριψε δεξιά, μετά αριστερά, μετά πέρασε από ένα στενό δρομάκι. Στο ραδιόφωνο μιλούσαν για τον ΠΑΟΚ.", "Stelios bog rechts ab, dann links, dann fuhr er durch eine schmale Gasse. Im Radio sprachen sie über PAOK.", "Stelios giró a la derecha, luego a la izquierda y luego se metió por una calle estrecha. En la radio hablaban del PAOK.", "Stelios turned right, then left, then cut down a narrow side street. On the radio they were talking about PAOK."),
    Z("—Ξέρεις τι είπε ο Ηράκλειτος; «Τα πάντα ρει.» Όλα κυλάνε. Εκτός από την κίνηση στη Θεσσαλονίκη.", "Weißt du, was Heraklit gesagt hat? »Alles fließt.« Alles bewegt sich. Außer dem Verkehr in Thessaloniki.", "¿Sabes lo que dijo Heráclito? «Todo fluye». Todo corre. Menos el tráfico de Tesalónica.", "Do you know what Heraclitus said? “Everything flows.” Everything moves on. Except the traffic in Thessaloniki.", "—Xéris ti ípe o Iráklitos? «Ta pánda ri.»"),
    N("Emmas Handy vibrierte. Ein Foto von Felix: ein großes gelbes Schild mit griechischen Buchstaben. Darunter: »Kannst du das lesen??? Wir stehen hier.« Auf dem Schild stand ΕΞΟΔΟΣ. Ausgang. Emma schrieb zurück: »Bleibt genau dort.«",
      "El móvil de Emma vibró. Una foto de Felix: un cartel amarillo enorme con letras griegas. Debajo: «¿¿¿Tú sabes leer esto??? Estamos aquí». En el cartel ponía ΕΞΟΔΟΣ. Salida. Emma contestó: «No os mováis de ahí».",
      "Emma's phone buzzed. A photo from Felix: a big yellow sign in Greek letters. Underneath: “Can you read this??? We're standing here.” The sign said ΕΞΟΔΟΣ. Exit. Emma wrote back: “Stay exactly where you are.”"),
    Z("Στις επτά και δέκα το ταξί σταμάτησε έξω από τις αφίξεις. Η Έμμα άργησε μισή ώρα.", "Um zehn nach sieben hielt das Taxi vor der Ankunftshalle. Emma war eine halbe Stunde zu spät.", "A las siete y diez, el taxi paró delante de llegadas. Emma llegaba media hora tarde.", "At ten past seven the taxi stopped outside arrivals. Emma was half an hour late.", "...éxo apó tis afíxis."),
    Z("—Στέλιο, μπορείς να περιμένεις λίγο; Θα γυρίσουμε με βαλίτσες.", "Stelios, kannst du kurz warten? Wir kommen mit Koffern zurück.", "Stelios, ¿puedes esperar un momento? Volvemos con maletas.", "Stelios, can you wait a moment? We'll be back with suitcases."),
    Z("—Περιμένω. Αλλά το ταξίμετρο τρέχει, ε;", "Ich warte. Aber das Taxameter läuft, ja?", "Te espero. Pero el taxímetro sigue corriendo, ¿eh?", "I'll wait. But the meter's running, mind."),
    N("Die Ankunftshalle. Felix rannte auf sie zu, den Rucksack auf dem Rücken, die Kopfhörer um den Hals. Ihre Mutter Brigitte lachte und weinte ein bisschen. Und ihr Vater Karl, vierzig Jahre Straßenbahnfahrer in Wien, trug eine Schachtel vor sich her wie ein rohes Ei.",
      "La sala de llegadas. Felix corrió hacia ella, con la mochila a la espalda y los cascos al cuello. Su madre, Brigitte, reía y lloraba un poco a la vez. Y su padre, Karl, cuarenta años conduciendo tranvías en Viena, llevaba una caja delante como si fuera un huevo crudo.",
      "The arrivals hall. Felix ran towards her, rucksack on his back, headphones round his neck. Her mother, Brigitte, was laughing and crying a little. And her father, Karl, forty years a tram driver in Vienna, was carrying a box in front of him like a raw egg."),
    Z("Μέσα στο κουτί ήταν μια τούρτα Σάχερ. Για την κυρία Ρούλα.", "In der Schachtel war eine Sachertorte. Für Frau Roula.", "Dentro de la caja había una tarta Sacher. Para la señora Rula.", "Inside the box was a Sachertorte. For Mrs Roula."),
    N("»Die Leute hier füttern dich seit einem halben Jahr«, sagte ihre Mutter. »Jetzt sind wir dran.« Im Taxi beugte sich ihr Vater vor. »Frag ihn nach einer Quittung.« — »Papa, du bist im Urlaub.« — »Trotzdem.«",
      "«La gente de aquí lleva medio año dándote de comer», dijo su madre. «Ahora nos toca a nosotros». En el taxi, su padre se inclinó hacia delante. «Pídele un recibo». «Papá, estás de vacaciones». «Da igual».",
      "“The people here have been feeding you for six months,” said her mother. “Now it's our turn.” In the taxi her father leant forward. “Ask him for a receipt.” “Dad, you're on holiday.” “All the same.”"),
    Z("—Στέλιο, μου δίνεις μια απόδειξη; Είναι για τον πατέρα μου.", "Stelios, gibst du mir eine Quittung? Sie ist für meinen Vater.", "Stelios, ¿me das un recibo? Es para mi padre.", "Stelios, could I have a receipt? It's for my father.", "—Stélio, mou dínis mia apódixi?"),
    Z("—Ναι, ναι, βεβαίως! Επιτέλους ένας πελάτης που ζητάει απόδειξη!", "Ja, ja, selbstverständlich! Endlich ein Fahrgast, der eine Quittung verlangt!", "¡Sí, sí, por supuesto! ¡Por fin un cliente que pide recibo!", "Yes, yes, of course! At last a passenger who asks for a receipt!", "—Ne, ne, vevéos! Epitélous énas pelátis pou zitái apódixi!"),
    N("Ihr Vater erstarrte. »Nein? Wieso nein?« Emma lachte. Sie hatte Wochen gebraucht, bis ihr Ohr bei ναι nicht mehr »nein« hörte. Jetzt war ihr Vater dran.",
      "Su padre se quedó helado. «¿Nein? ¿Cómo que nein?». Emma se rio. Ella había tardado semanas en dejar de oír un «nein», un «no» alemán, cada vez que alguien decía ναι. Ahora le tocaba a su padre.",
      "Her father froze. “Nein? Why nein?” Emma laughed. It had taken her weeks to stop hearing a German “nein” every time someone said ναι. Now it was her father's turn."),
    Z("—Μπαμπά, το «ναι» θα πει «ja»!", "Papa, »ne« heißt »ja«!", "¡Papá, «ne» quiere decir «ja», o sea, sí!", "Dad, “ne” means “ja” — yes!", "—Babá, to «ne» tha pi «ja»!"),
    N("Dann fragte ihr Vater, über Emma, ob es in Thessaloniki eine Straßenbahn gebe. Stelios lachte so laut, dass Felix die Kopfhörer abnahm.",
      "Luego su padre preguntó, a través de Emma, si en Tesalónica había tranvía. Stelios se rio tan fuerte que Felix se quitó los cascos.",
      "Then her father asked, through Emma, whether Thessaloniki had a tram. Stelios laughed so loudly that Felix took his headphones off."),
    Z("—Τραμ; Εδώ δεν έχουμε τραμ. Εδώ έχουμε εμένα. Καλώς ήρθατε στη Θεσσαλονίκη!", "Straßenbahn? Hier haben wir keine Straßenbahn. Hier haben wir mich. Willkommen in Thessaloniki!", "¿Tranvía? Aquí no tenemos tranvía. Aquí me tenemos a mí. ¡Bienvenidos a Tesalónica!", "Trams? We don't have trams here. Here you've got me. Welcome to Thessaloniki!", "...Kalós írthate sti Thessaloníki!"),
    Z("Ο πατέρας της δίπλωσε την απόδειξη στα δύο και την έβαλε στο πορτοφόλι.", "Ihr Vater faltete die Quittung in der Mitte und steckte sie in die Brieftasche.", "Su padre dobló el recibo por la mitad y se lo guardó en la cartera.", "Her father folded the receipt in half and put it in his wallet.")
  ]),

  // ── Station 12 · HOTEL (A2) ───────────────────────────────────────────
  S("aufbau", 12, "hotel", "Δεν έχει ζεστό νερό",
    "Erste Nacht im Hotel: kein warmes Wasser, Kirchenglocken ab sechs — und Emma beschwert sich zum ersten Mal auf Griechisch.",
    "Primera noche en el hotel: no hay agua caliente, las campanas suenan desde las seis y Emma se queja por primera vez en griego.",
    "First night at the hotel: no hot water, church bells from six — and Emma makes her first complaint in Greek.",
  [
    Z("Η οικογένεια έμενε σε ένα μικρό ξενοδοχείο στο κέντρο, στο «Αστέρι». Ήταν το ίδιο ξενοδοχείο όπου έμεινε η Έμμα τον Οκτώβριο, όταν χάλασε ο θερμοσίφωνας.", "Die Familie wohnte in einem kleinen Hotel im Zentrum, im »Asteri«. Es war dasselbe Hotel, in dem Emma im Oktober gewohnt hatte, als der Boiler kaputtging.", "La familia se alojaba en un hotel pequeño del centro, el «Asteri». Era el mismo hotel donde se había quedado Emma en octubre, cuando se estropeó el calentador.", "The family was staying in a small hotel in the centre, the “Asteri”. It was the same hotel where Emma had stayed in October, when the water heater broke.", "...ótan chálase o thermosífonas."),
    Z("Την Τετάρτη, στις επτά και μισή το πρωί, χτύπησε το κινητό της. Ήταν η μητέρα της.", "Am Mittwoch um halb acht morgens klingelte ihr Handy. Es war ihre Mutter.", "El miércoles, a las siete y media de la mañana, sonó su móvil. Era su madre.", "On Wednesday at half past seven in the morning, her phone rang. It was her mother."),
    N("»Emma. Es gibt kein warmes Wasser. Dein Vater hat kalt geduscht.« Im Hintergrund rief ihr Vater: »Wie beim Bundesheer!« Er klang nicht begeistert. »Und neben unserem Fenster ist eine Kirche. Die Glocken läuten seit sechs.«",
      "«Emma. No hay agua caliente. Tu padre se ha duchado con agua fría». Al fondo, su padre gritó: «¡Como en la mili!». No sonaba entusiasmado. «Y al lado de nuestra ventana hay una iglesia. Las campanas suenan desde las seis».",
      "“Emma. There's no hot water. Your father had a cold shower.” In the background her father called out: “Like in the army!” He didn't sound thrilled. “And there's a church right next to our window. The bells have been ringing since six.”"),
    N("Emma schloss die Augen. Kaltes Wasser. Schon wieder. Zwischen ihr und griechischen Boilern gab es offenbar etwas Persönliches.",
      "Emma cerró los ojos. Agua fría. Otra vez. Entre ella y los calentadores griegos había, por lo visto, algo personal.",
      "Emma closed her eyes. Cold water. Again. Between her and Greek water heaters there was clearly something personal."),
    Z("Είκοσι λεπτά αργότερα ήταν στη ρεσεψιόν. Πίσω από τον πάγκο καθόταν μια νέα κοπέλα. Το καρτελάκι της έγραφε: Κατερίνα.", "Zwanzig Minuten später stand sie an der Rezeption. Hinter dem Tresen saß eine junge Frau. Auf ihrem Namensschild stand: Katerina.", "Veinte minutos después estaba en la recepción. Detrás del mostrador había una chica joven. En su placa ponía: Katerina.", "Twenty minutes later she was at reception. A young woman sat behind the desk. Her name badge said: Katerina."),
    Z("—Καλημέρα. Οι γονείς μου μένουν στο δωμάτιο εκατόν δώδεκα. Δεν έχει ζεστό νερό.", "Guten Morgen. Meine Eltern wohnen in Zimmer hundertzwölf. Es gibt kein warmes Wasser.", "Buenos días. Mis padres están en la habitación ciento doce. No hay agua caliente.", "Good morning. My parents are in room one hundred and twelve. There's no hot water.", "...sto domátio ekatón dódeka. Den échi zestó neró."),
    Z("—Λυπάμαι πολύ. Από πότε;", "Das tut mir sehr leid. Seit wann?", "Lo siento mucho. ¿Desde cuándo?", "I'm very sorry. Since when?", "—Lipáme polí. Apó póte?"),
    Z("—Από χθες το βράδυ. Ο πατέρας μου έκανε κρύο ντους.", "Seit gestern Abend. Mein Vater hat kalt geduscht.", "Desde anoche. Mi padre se ha duchado con agua fría.", "Since last night. My father had a cold shower.", "—Apó chthes to vrádi. O patéras mou ékane krío dous."),
    Z("—Ωχ, συγγνώμη. Μάλλον χάλασε ο θερμοσίφωνας. Θα στείλω τεχνικό.", "Oh, Entschuldigung. Wahrscheinlich ist der Boiler kaputt. Ich schicke einen Techniker.", "Ay, perdone. Seguramente se ha estropeado el calentador. Mando a un técnico.", "Oh, I'm sorry. The water heater has probably broken. I'll send a technician.", "—Och, signómi. Málon chálase o thermosífonas. Tha stílo technikó."),
    Z("—Υπάρχει και ένα άλλο πρόβλημα. Το δωμάτιο είναι δίπλα στην εκκλησία. Οι καμπάνες χτυπάνε από τις έξι.", "Es gibt noch ein anderes Problem. Das Zimmer liegt neben der Kirche. Die Glocken läuten seit sechs.", "Hay otro problema. La habitación está al lado de la iglesia. Las campanas suenan desde las seis.", "There's another problem. The room is next to the church. The bells have been ringing since six.", "...I kambánes chtipáne apó tis éxi."),
    Z("—Είναι Μεγάλη Εβδομάδα. Οι καμπάνες χτυπάνε όλη τη μέρα. Θέλετε να αλλάξετε δωμάτιο;", "Es ist Karwoche. Die Glocken läuten den ganzen Tag. Möchten Sie das Zimmer wechseln?", "Es Semana Santa. Las campanas suenan todo el día. ¿Quieren cambiar de habitación?", "It's Holy Week. The bells ring all day. Would you like to change rooms?"),
    N("Emma übersetzte am Telefon. Ihr Vater: »Wir bleiben. Ich schlafe auch neben der Straßenbahn.« Ihre Mutter: »Wir wechseln.« Felix: »Gibt es eins mit Meerblick?« Drei Novaks, drei Meinungen. Emma entschied.",
      "Emma tradujo por teléfono. Su padre: «Nos quedamos. Yo duermo hasta al lado del tranvía». Su madre: «Nos cambiamos». Felix: «¿Hay alguna con vistas al mar?». Tres Novak, tres opiniones. Emma decidió.",
      "Emma translated over the phone. Her father: “We'll stay. I can sleep next to a tram.” Her mother: “We're moving.” Felix: “Is there one with a sea view?” Three Novaks, three opinions. Emma decided."),
    Z("—Θα θέλαμε να αλλάξουμε, αν γίνεται. Ένα δωμάτιο πιο ήσυχο, παρακαλώ.", "Wir würden gern wechseln, wenn es geht. Ein ruhigeres Zimmer, bitte.", "Querríamos cambiar, si es posible. Una habitación más tranquila, por favor.", "We'd like to change, if possible. A quieter room, please.", "—Tha thélame na alláxoume, an yínete. Éna domátio pio ísicho, parakaló."),
    Z("—Βεβαίως. Σας δίνω το τριακόσια πέντε. Είναι στον τρίτο όροφο, από την άλλη πλευρά. Και έχει θέα στη θάλασσα.", "Selbstverständlich. Ich gebe Ihnen die Dreihundertfünf. Sie liegt im dritten Stock, auf der anderen Seite. Und sie hat Meerblick.", "Por supuesto. Les doy la trescientos cinco. Está en la tercera planta, al otro lado. Y tiene vistas al mar.", "Of course. I'll give you three hundred and five. It's on the third floor, on the other side. And it has a sea view.", "...to triakósia pénde... Ke échi théa sti thálassa."),
    N("Felix hatte am Telefon ein einziges Wort verstanden: θάλασσα. Meer. Er jubelte so laut, dass Katerina ihn durch Emmas Handy hörte.",
      "Felix, al teléfono, había entendido una sola palabra: θάλασσα. Mar. Lo celebró tan alto que Katerina lo oyó a través del móvil de Emma.",
      "Felix, on the phone, had understood a single word: θάλασσα. Sea. He cheered so loudly that Katerina heard him through Emma's phone."),
    Z("—Και κάτι ακόμα: στο μπάνιο λείπει μια πετσέτα. Είναι τρεις και έχουν δύο.", "Und noch etwas: Im Bad fehlt ein Handtuch. Sie sind zu dritt und haben zwei.", "Y otra cosa: en el baño falta una toalla. Son tres y tienen dos.", "And one more thing: there's a towel missing in the bathroom. There are three of them and they've got two.", "...sto bánio lípi mia petséta."),
    Z("—Θα σας τη φέρω αμέσως. Και συγγνώμη για την ταλαιπωρία.", "Ich bringe es Ihnen sofort. Und entschuldigen Sie die Unannehmlichkeiten.", "Se la llevo enseguida. Y disculpen las molestias.", "I'll bring it up straight away. And sorry for the inconvenience.", "...ke signómi gia tin taleporía."),
    N("Als Emma sich umdrehte, stand ihre Mutter hinter ihr, mit nassen Haaren und Mantel. Sie hatte alles gehört. »Du redest ja wie eine von hier.« Emma zuckte mit den Schultern. Seit dem Finanzamt, dachte sie. Nach der ΔΟΥ machte ihr kein Schalter der Welt mehr Angst.",
      "Cuando Emma se dio la vuelta, su madre estaba detrás de ella, con el pelo mojado y el abrigo puesto. Lo había oído todo. «Pero si hablas como una de aquí». Emma se encogió de hombros. Desde Hacienda, pensó. Después de la ΔΟΥ, ningún mostrador del mundo le daba miedo.",
      "When Emma turned round, her mother was standing behind her, hair wet, coat on. She had heard everything. “You talk like a local.” Emma shrugged. Since the tax office, she thought. After the ΔΟΥ, no counter in the world could frighten her."),
    Z("Το δωμάτιο τριακόσια πέντε ήταν μικρότερο, αλλά ήταν ήσυχο. Και το νερό στο ντους ήταν ζεστό. Πολύ ζεστό.", "Zimmer dreihundertfünf war kleiner, aber es war ruhig. Und das Wasser in der Dusche war warm. Sehr warm.", "La habitación trescientos cinco era más pequeña, pero era tranquila. Y el agua de la ducha salía caliente. Muy caliente.", "Room three hundred and five was smaller, but it was quiet. And the water in the shower was hot. Very hot."),
    Z("Ο πατέρας της κατέβηκε στη ρεσεψιόν και είπε, πολύ αργά: «Ευ-χα-ρι-στώ».", "Ihr Vater ging hinunter zur Rezeption und sagte sehr langsam: »Ef-cha-ri-stó.«", "Su padre bajó a la recepción y dijo, muy despacio: «Ef-ja-ris-tó».", "Her father went down to reception and said, very slowly: “Ef-cha-ri-stó.”", "Ef-cha-ri-stó."),
    N("Vier Silben, sorgfältig, wie eine Haltestellenansage auf der Linie 43. Es war sein erstes griechisches Wort. Katerina lächelte.",
      "Cuatro sílabas, con cuidado, como el anuncio de una parada en la línea 43. Era su primera palabra en griego. Katerina sonrió.",
      "Four syllables, carefully, like a stop announcement on the number 43. It was his first Greek word. Katerina smiled.")
  ]),

  // ── Station 13 · CAFE (A2) ────────────────────────────────────────────
  S("aufbau", 13, "cafe", "Έχει ξηρούς καρπούς;",
    "Emma stellt ihre Familie Herrn Thanasis vor. Felix verträgt keine Nüsse, Papas Kaffee ist kalt — und bei Herrn Thanasis beschwert sich niemand.",
    "Emma presenta a su familia al señor Thanasis. Felix no puede tomar frutos secos, el café de su padre está frío y en ese café no se queja nadie.",
    "Emma introduces her family to Mr Thanasis. Felix can't eat nuts, Dad's coffee is cold — and nobody complains at Mr Thanasis's.",
  [
    Z("Μετά το ξενοδοχείο, η Έμμα πήγε την οικογένειά της στο καφενείο του κυρ-Θανάση.", "Nach dem Hotel ging Emma mit ihrer Familie ins Kafeneio von Herrn Thanasis.", "Después del hotel, Emma llevó a su familia al café del señor Thanasis.", "After the hotel, Emma took her family to Mr Thanasis's kafeneio."),
    N("Vier Tische auf dem Gehsteig, blaue Stühle, der Fernseher ohne Ton, ein Kalender von 2019 an der Wand. Herr Thanasis saß draußen mit seinem Komboloi, wie jeden Morgen. Als er die vier Novaks sah, stand er auf. Das tut er sonst nur für den Pfarrer und für PAOK-Spieler.",
      "Cuatro mesas en la acera, sillas azules, la tele sin sonido, un calendario de 2019 en la pared. El señor Thanasis estaba sentado fuera con su komboloi, como cada mañana. Cuando vio a los cuatro Novak, se levantó. Eso solo lo hace por el cura y por los jugadores del PAOK.",
      "Four tables on the pavement, blue chairs, the television with no sound, a 2019 calendar on the wall. Mr Thanasis was sitting outside with his komboloi, as he did every morning. When he saw the four Novaks, he stood up. He normally does that only for the priest and for PAOK players."),
    Z("—Καλώς τους! Αυτή είναι η οικογένεια;", "Herzlich willkommen! Ist das die Familie?", "¡Bienvenidos! ¿Esta es la familia?", "Welcome, welcome! Is this the family?", "—Kalós tous!"),
    Z("—Ναι, κυρ-Θανάση. Η μητέρα μου, ο πατέρας μου και ο αδερφός μου, ο Φέλιξ.", "Ja, Herr Thanasis. Meine Mutter, mein Vater und mein Bruder Felix.", "Sí, señor Thanasis. Mi madre, mi padre y mi hermano, Felix.", "Yes, Mr Thanasis. My mother, my father and my brother, Felix."),
    Z("—Καθίστε, καθίστε. Τι θα πάρετε;", "Setzt euch, setzt euch. Was nehmt ihr?", "Sentaos, sentaos. ¿Qué vais a tomar?", "Sit down, sit down. What will you have?"),
    Z("—Έναν ελληνικό μέτριο για τον πατέρα μου, έναν φρέντο εσπρέσο για τη μητέρα μου και μια πορτοκαλάδα για τον Φέλιξ. Και για μένα, τα συνηθισμένα.", "Einen griechischen Kaffee, mittelsüß, für meinen Vater, einen Freddo Espresso für meine Mutter und eine Orangenlimonade für Felix. Und für mich das Übliche.", "Un café griego con poco azúcar para mi padre, un freddo espresso para mi madre y una naranjada para Felix. Y para mí, lo de siempre.", "A Greek coffee, medium sweet, for my father, a freddo espresso for my mother and an orangeade for Felix. And for me, the usual.", "...Ke gia ména, ta sinithisména."),
    Z("—Φραπέ, μέτριο με γάλα. Έρχεται.", "Frappé, mittelsüß mit Milch. Kommt sofort.", "Frapé, con poco azúcar con leche. Marchando.", "Frappé, medium with milk. Coming up."),
    N("Felix stand vor der Vitrine: Baklava, Walnusskuchen, Kataifi. Und Brigitte wurde ernst. Felix ist allergisch gegen Nüsse. Seit er drei ist, liest die Familie jede Zutatenliste zweimal.",
      "Felix se quedó delante de la vitrina: baklava, pastel de nueces, kataifi. Y Brigitte se puso seria. Felix es alérgico a los frutos secos. Desde que tenía tres años, la familia lee cada lista de ingredientes dos veces.",
      "Felix stood in front of the display: baklava, walnut cake, kataifi. And Brigitte turned serious. Felix is allergic to nuts. Since he was three, the family has read every ingredients list twice."),
    Z("—Κυρ-Θανάση, μια ερώτηση: ο μπακλαβάς έχει ξηρούς καρπούς;", "Herr Thanasis, eine Frage: Sind im Baklava Nüsse?", "Señor Thanasis, una pregunta: ¿el baklava lleva frutos secos?", "Mr Thanasis, a question: does the baklava have nuts in it?", "...o baklavás échi xiroús karpoús?"),
    Z("—Ο μπακλαβάς; Μόνο καρύδια έχει! Και η καρυδόπιτα, το λέει και το όνομα.", "Der Baklava? Der besteht nur aus Walnüssen! Und der Walnusskuchen — das sagt schon der Name.", "¿El baklava? ¡Si es todo nueces! Y el pastel de nueces, lo dice el nombre.", "The baklava? It's nothing but walnuts! And the walnut cake — the name says it all.", "...móno karídia échi!"),
    Z("—Και η λεμονόπιτα;", "Und der Zitronenkuchen?", "¿Y la tarta de limón?", "And the lemon pie?", "—Ke i lemonópita?"),
    N("Herr Thanasis hob kurz das Kinn und schnalzte mit der Zunge. Felix strahlte: »Er hat genickt!« — »Nein, Felix. Das war ein Nein.« Hier nickt man nach oben, wenn man Nein meint. Emma fragte lieber noch einmal nach.",
      "El señor Thanasis levantó un momento la barbilla y chasqueó la lengua. Felix sonrió: «¡Ha dicho que sí con la cabeza!». «No, Felix. Eso era un no». Aquí se cabecea hacia arriba para decir que no. Emma prefirió preguntar otra vez.",
      "Mr Thanasis tipped his chin up and clicked his tongue. Felix beamed: “He nodded!” “No, Felix. That was a no.” Here you nod upwards when you mean no. Emma preferred to ask again."),
    Z("—Δηλαδή όχι;", "Also nein?", "¿O sea, que no?", "So that's a no?", "—Diladí óchi?"),
    Z("—Όχι, κορίτσι μου. Η λεμονόπιτα είναι της γυναίκας μου. Λεμόνι, αυγά, ζάχαρη, φύλλο. Τίποτα άλλο.", "Nein, Mädchen. Den Zitronenkuchen macht meine Frau. Zitrone, Eier, Zucker, Filoteig. Sonst nichts.", "No, hija. La tarta de limón la hace mi mujer. Limón, huevos, azúcar y masa filo. Nada más.", "No, my girl. The lemon pie is my wife's. Lemon, eggs, sugar, filo. Nothing else.", "—Óchi, korítsi mou..."),
    Z("—Τέλεια. Ο αδερφός μου είναι αλλεργικός στους ξηρούς καρπούς. Τότε μια λεμονόπιτα, παρακαλώ.", "Perfekt. Mein Bruder ist allergisch gegen Nüsse. Dann einen Zitronenkuchen, bitte.", "Perfecto. Mi hermano es alérgico a los frutos secos. Entonces, una de limón, por favor.", "Perfect. My brother is allergic to nuts. A lemon pie, then, please.", "...íne alleryikós stous xiroús karpoús."),
    N("Dann trank ihr Vater einen Schluck von seinem griechischen Kaffee. Er verzog das Gesicht und flüsterte: »Der ist kalt.« Emma erstarrte. Bei Herrn Thanasis beschwert sich niemand. Der Letzte, der es versucht hat, war angeblich ein Athener, im Jahr 1987. Man hat ihn nie wieder gesehen.",
      "Entonces su padre bebió un sorbo de su café griego. Torció el gesto y susurró: «Está frío». Emma se quedó helada. Al señor Thanasis no se le queja nadie. El último que lo intentó, dicen, fue un ateniense, en 1987. Nunca más se le volvió a ver.",
      "Then her father took a sip of his Greek coffee. He pulled a face and whispered: “It's cold.” Emma froze. Nobody complains to Mr Thanasis. The last person who tried, so they say, was an Athenian, in 1987. He was never seen again."),
    Z("Αλλά ο καφές ήταν πραγματικά κρύος. Η Έμμα πήρε μια βαθιά ανάσα.", "Aber der Kaffee war wirklich kalt. Emma holte tief Luft.", "Pero el café estaba frío de verdad. Emma respiró hondo.", "But the coffee really was cold. Emma took a deep breath."),
    Z("—Συγγνώμη, κυρ-Θανάση… ο καφές του πατέρα μου ήρθε κρύος.", "Entschuldigung, Herr Thanasis … der Kaffee meines Vaters ist kalt gekommen.", "Perdone, señor Thanasis… el café de mi padre ha llegado frío.", "Excuse me, Mr Thanasis… my father's coffee came cold.", "...o kafés tou patéra mou írthe kríos."),
    Z("Οι δύο παππούδες στο τάβλι σταμάτησαν να παίζουν. Ο κυρ-Θανάσης ακούμπησε το φλιτζάνι με ένα δάχτυλο.", "Die zwei alten Männer am Tavli-Brett hörten auf zu spielen. Herr Thanasis berührte die Tasse mit einem Finger.", "Los dos abuelos del tavli dejaron de jugar. El señor Thanasis tocó la taza con un dedo.", "The two old men at the backgammon board stopped playing. Mr Thanasis touched the cup with one finger."),
    Z("—Έχεις δίκιο. Συγγνώμη. Τον Απρίλιο όλοι πίνουν κρύο καφέ και το μπρίκι κρύωσε. Σου φτιάχνω αμέσως άλλον.", "Du hast recht. Entschuldige. Im April trinken alle kalten Kaffee, und das Kännchen ist kalt geworden. Ich mache dir sofort einen neuen.", "Tienes razón. Perdona. En abril todo el mundo toma café frío y el cazo se enfrió. Ahora mismo te hago otro.", "You're right. Sorry. In April everyone drinks iced coffee and the pot went cold. I'll make you another one right away.", "—Échis díkio... to bríki kríose."),
    Z("—Ο ελληνικός θέλει υπομονή. Σιγά-σιγά.", "Ein griechischer Kaffee braucht Geduld. Langsam, langsam.", "El café griego necesita paciencia. Despacito.", "Greek coffee needs patience. Slowly, slowly.", "—O ellinikós théli ipomoní. Sigá-sigá."),
    Z("Ο καινούριος καφές ήταν καυτός. Δίπλα είχε ένα λουκούμι. Χωρίς ξηρούς καρπούς, για καλό και για κακό.", "Der neue Kaffee war glühend heiß. Daneben lag ein Lokum. Ohne Nüsse, für alle Fälle.", "El café nuevo estaba ardiendo. Al lado había una delicia turca. Sin frutos secos, por si acaso.", "The new coffee was piping hot. Next to it lay a piece of Turkish delight. No nuts, just in case.", "...Chorís xiroús karpoús, gia kaló ke gia kakó."),
    N("Danach spielte ihr Vater eine Partie Tavli mit Herrn Thanasis. Zwei Rentner, kein gemeinsames Wort. Karl verlor dreimal und lachte jedes Mal lauter.",
      "Después, su padre jugó una partida de tavli con el señor Thanasis. Dos jubilados sin una palabra en común. Karl perdió tres veces y cada vez se rio más fuerte.",
      "Afterwards her father played a game of tavli with Mr Thanasis. Two pensioners, not a word in common. Karl lost three times and laughed louder each time."),
    Z("Στο τέλος ο κυρ-Θανάσης δεν πήρε λεφτά. «Κερασμένα», είπε. «Για την οικογένεια της Αυστριακής.»", "Am Ende nahm Herr Thanasis kein Geld. »Geht aufs Haus«, sagte er. »Für die Familie der Österreicherin.«", "Al final, el señor Thanasis no les cobró. «Invita la casa», dijo. «Por la familia de la austriaca».", "In the end Mr Thanasis wouldn't take any money. “On the house,” he said. “For the Austrian's family.”", "...«Kerasména»...")
  ]),

  // ── Station 14 · WEGBESCHREIBUNG (A2) ─────────────────────────────────
  S("aufbau", 14, "wegbeschreibung", "Στο φανάρι, δεξιά",
    "Zwei Athener fragen nach dem Weg zur Rotonda — und zwar ausgerechnet Emma. Sie erklärt ihn wie eine Einheimische, vor der ganzen Familie.",
    "Dos atenienses preguntan cómo llegar a la Rotonda — y se lo preguntan precisamente a Emma. Ella se lo explica como una más, delante de toda la familia.",
    "Two Athenians ask the way to the Rotunda — and of all people, they ask Emma. She explains it like a local, in front of the whole family.",
  [
    Z("Το απόγευμα η οικογένεια κατέβηκε στο κέντρο. Στάθηκαν στην πλατεία της Αγίας Σοφίας, μπροστά στην εκκλησία.", "Am Nachmittag ging die Familie hinunter ins Zentrum. Sie blieben auf dem Platz der Hagia Sophia stehen, vor der Kirche.", "Por la tarde, la familia bajó al centro. Se pararon en la plaza de Santa Sofía, delante de la iglesia.", "In the afternoon the family went down into the centre. They stopped in Agia Sofia square, in front of the church."),
    N("Ihre Mutter hielt einen Stadtplan aus Papier, verkehrt herum. Ihr Vater wollte ans Meer. Felix wollte eine Bougatsa. Emma kannte den Weg zu allem. Aber bevor sie etwas sagen konnte, sprach sie jemand an.",
      "Su madre sujetaba un plano de papel, al revés. Su padre quería ir al mar. Felix quería una bougatsa. Emma sabía llegar a todo. Pero antes de que pudiera decir nada, alguien se dirigió a ella.",
      "Her mother was holding a paper map, upside down. Her father wanted to go to the sea. Felix wanted a bougatsa. Emma knew the way to everything. But before she could say a word, someone spoke to her."),
    Z("Ένα ζευγάρι με μια φωτογραφική μηχανή πλησίασε. Εκείνος φορούσε καπέλο. Εκείνη κρατούσε το κινητό με τον χάρτη.", "Ein Paar mit einem Fotoapparat kam näher. Er trug einen Hut. Sie hielt das Handy mit der Karte.", "Una pareja con una cámara de fotos se acercó. Él llevaba sombrero. Ella sujetaba el móvil con el mapa.", "A couple with a camera came over. He was wearing a hat. She was holding her phone with the map."),
    Z("—Συγγνώμη, κοπέλα μου, ξέρετε πού είναι η Ροτόντα; Είμαστε από την Αθήνα και χαθήκαμε.", "Entschuldigung, junge Frau, wissen Sie, wo die Rotonda ist? Wir sind aus Athen und haben uns verlaufen.", "Perdone, joven, ¿sabe dónde está la Rotonda? Somos de Atenas y nos hemos perdido.", "Excuse me, miss, do you know where the Rotunda is? We're from Athens and we're lost.", "...xérete poú íne i Rotónda? ...ke chathíkame."),
    N("Zwei Athener. Griechen. Sie fragten nach dem Weg, in Thessaloniki. Und zwar sie, die Österreicherin. Nicht den Mann am Kiosk, nicht den Polizisten an der Ecke. Sie.",
      "Dos atenienses. Griegos. Preguntaban cómo llegar a un sitio, en Tesalónica. Y se lo preguntaban a ella, a la austriaca. No al hombre del quiosco, ni al policía de la esquina. A ella.",
      "Two Athenians. Greeks. Asking the way, in Thessaloniki. And they were asking her, the Austrian. Not the man at the kiosk, not the policeman on the corner. Her."),
    Z("—Ναι, βέβαια. Ανεβείτε την Αγίας Σοφίας, ευθεία, μέχρι την Εγνατία.", "Ja, natürlich. Gehen Sie die Agias-Sofias-Straße hinauf, geradeaus, bis zur Egnatia.", "Sí, claro. Suban por la calle Agias Sofias, todo recto, hasta la Egnatia.", "Yes, of course. Go up Agias Sofias Street, straight on, as far as Egnatia.", "—Ne, vévea. Anevíte tin Ayías Sofías, efthía, méchri tin Egnatía."),
    Z("—Και μετά;", "Und dann?", "¿Y después?", "And then?"),
    Z("—Μετά θα δείτε έναν μεγάλο δρόμο με πολλή κίνηση. Αυτή είναι η Εγνατία. Μην την περάσετε ακόμα.", "Dann sehen Sie eine große Straße mit viel Verkehr. Das ist die Egnatia. Überqueren Sie sie noch nicht.", "Luego verán una calle grande con mucho tráfico. Esa es la Egnatia. No la crucen todavía.", "Then you'll see a big road with lots of traffic. That's Egnatia. Don't cross it yet.", "...Min ti perásete akóma."),
    Z("—Στο φανάρι, στρίψτε δεξιά. Περπατήστε πέντε λεπτά. Θα δείτε μια μεγάλη πύλη, την Καμάρα.", "An der Ampel biegen Sie rechts ab. Gehen Sie fünf Minuten. Sie sehen dann ein großes Tor, die Kamara.", "En el semáforo, giren a la derecha. Caminen cinco minutos. Verán una puerta grande, la Kamara.", "At the traffic lights, turn right. Walk for five minutes. You'll see a big gateway, the Kamara.", "—Sto fanári, strípste dexiá. Perpatíste pénde leptá. Tha díte mia megáli píli, tin Kamára."),
    Z("—Και η Ροτόντα;", "Und die Rotonda?", "¿Y la Rotonda?", "And the Rotunda?"),
    Z("—Είναι ακριβώς πίσω από την Καμάρα, λίγο πιο πάνω. Δεν μπορείτε να τη χάσετε. Είναι στρογγυλή.", "Sie liegt direkt hinter der Kamara, ein bisschen weiter oben. Sie können sie nicht verfehlen. Sie ist rund.", "Está justo detrás de la Kamara, un poco más arriba. No tiene pérdida. Es redonda.", "It's right behind the Kamara, a bit further up. You can't miss it. It's round.", "—Íne akrivós píso apó tin Kamára... Íne strongilí."),
    N("Ihr Vater verstand kein Wort. Aber er sah die Hände seiner Tochter: geradeaus, rechts, hinauf. Er sah die Athener nicken — diesmal nach unten. Und er stand ein bisschen gerader.",
      "Su padre no entendía ni una palabra. Pero veía las manos de su hija: recto, a la derecha, hacia arriba. Veía a los atenienses asentir, esta vez hacia abajo. Y se puso un poco más derecho.",
      "Her father didn't understand a word. But he saw his daughter's hands: straight on, right, uphill. He saw the Athenians nod — downwards, this time. And he stood up a little straighter."),
    Z("—Μπορούμε να πάμε με τα πόδια;", "Können wir zu Fuß gehen?", "¿Podemos ir andando?", "Can we walk there?", "—Boroúme na páme me ta pódia?"),
    Z("—Βεβαίως, δέκα λεπτά είναι. Αν χαθείτε, ρωτήστε στο περίπτερο!", "Natürlich, das sind zehn Minuten. Wenn Sie sich verlaufen, fragen Sie am Kiosk!", "Claro, son diez minutos. Si se pierden, pregunten en el quiosco.", "Of course, it's ten minutes. If you get lost, ask at the kiosk!", "—Vevéos, déka leptá íne. An chathíte, rotíste sto períptero!"),
    N("Kaum hatte sie es gesagt, dachte Emma an den jungen Mann im Períptero am Aristotelous-Platz, der ihr im Oktober mit dem Kinn »dort« gezeigt hatte. Vielleicht doch lieber nicht am Kiosk.",
      "Nada más decirlo, Emma pensó en el chico del períptero de la plaza Aristotelous que en octubre le había señalado «allí» con la barbilla. Quizá mejor no en el quiosco.",
      "No sooner had she said it than Emma thought of the young man in the periptero on Aristotelous Square who in October had pointed “there” with his chin. Perhaps not the kiosk after all."),
    Z("—Και ο Λευκός Πύργος; Είναι μακριά;", "Und der Weiße Turm? Ist der weit?", "¿Y la Torre Blanca? ¿Está lejos?", "And the White Tower? Is it far?", "—Ke o Lefkós Pírgos? Íne makriá?"),
    Z("—Όχι, είναι κοντά. Κατεβείτε στη θάλασσα και στρίψτε αριστερά. Περπατήστε δέκα λεπτά στην παραλία. Ο Πύργος είναι στο τέλος.", "Nein, er ist nah. Gehen Sie hinunter zum Meer und biegen Sie links ab. Gehen Sie zehn Minuten an der Uferpromenade entlang. Der Turm steht am Ende.", "No, está cerca. Bajen hasta el mar y giren a la izquierda. Caminen diez minutos por el paseo marítimo. La torre está al final.", "No, it's close. Go down to the sea and turn left. Walk along the seafront for ten minutes. The tower's at the end.", "—Óchi, íne kondá. Katevíte sti thálassa ke strípste aristerá."),
    Z("—Ευχαριστούμε πολύ! Μιλάτε σαν Θεσσαλονικιά!", "Vielen Dank! Sie reden wie eine Thessalonikerin!", "¡Muchas gracias! ¡Habla usted como una de Tesalónica!", "Thank you so much! You talk like a real Thessalonian!", "...Miláte san Thessalonikiá!"),
    Z("—Και κάτι ακόμα: πριν από τη Ροτόντα, φάτε μια μπουγάτσα. Με κρέμα. Εδώ δεν είναι Αθήνα.", "Und noch etwas: Essen Sie vor der Rotonda eine Bougatsa. Mit Creme. Hier ist nicht Athen.", "Y otra cosa: antes de la Rotonda, cómanse una bougatsa. De crema. Esto no es Atenas.", "And one more thing: before the Rotunda, have a bougatsa. With custard. This isn't Athens, you know.", "...fáte mia bougátsa. Me kréma."),
    N("Der Mann mit dem Hut lachte. Die Frau sagte etwas über Athener und Thessaloniker, das Emma nicht ganz verstand. Es klang nach einer sehr alten Rivalität. Und nach einer guten.",
      "El hombre del sombrero se rio. La mujer dijo algo sobre atenienses y salonicenses que Emma no entendió del todo. Sonaba a una rivalidad muy antigua. Y de las buenas.",
      "The man in the hat laughed. The woman said something about Athenians and Thessalonians that Emma didn't quite catch. It sounded like a very old rivalry. And a friendly one."),
    N("Als die beiden weg waren, sah Felix seine Schwester an, als hätte sie gerade gezaubert. »Du hast Griechen den Weg erklärt. Auf Griechisch.« — »Ja.« — »Cool.« Von einem Zwölfjährigen ist das ein Orden.",
      "Cuando se fueron, Felix miró a su hermana como si acabara de hacer un truco de magia. «Les has explicado el camino a unos griegos. En griego». «Sí». «Qué guay». Viniendo de alguien de doce años, eso es una medalla.",
      "When they had gone, Felix looked at his sister as if she had just done a magic trick. “You gave Greeks directions. In Greek.” “Yes.” “Cool.” From a twelve-year-old, that's a medal."),
    Z("Μετά πήγαν όλοι μαζί στη Ροτόντα, από τον ίδιο δρόμο. Και πρώτα έφαγαν μπουγάτσα. Με κρέμα.", "Danach gingen sie alle zusammen zur Rotonda, denselben Weg. Und vorher aßen sie Bougatsa. Mit Creme.", "Después fueron todos juntos a la Rotonda, por el mismo camino. Y antes se comieron una bougatsa. De crema.", "Then they all went to the Rotunda together, the same way. And first they had bougatsa. With custard.")
  ]),

  // ── Station 15 · EINKAUFEN (A2) ───────────────────────────────────────
  S("aufbau", 15, "einkaufen", "Μου πέφτει μεγάλο",
    "Gründonnerstag auf der Tsimiski: Papas neues Hemd ist zu groß, und er will es umtauschen. Zum Glück hat er die Quittung. Natürlich hat er die Quittung.",
    "Jueves Santo en la calle Tsimiskí: la camisa nueva de su padre le queda grande y quiere cambiarla. Por suerte tiene el tique. Cómo no va a tener el tique.",
    "Maundy Thursday on Tsimiski Street: Dad's new shirt is too big and he wants to exchange it. Luckily, he has the receipt. Of course he has the receipt.",
  [
    Z("Τη Μεγάλη Πέμπτη η Έμμα πήγε με τον πατέρα της στην Τσιμισκή, τον μεγάλο εμπορικό δρόμο της πόλης.", "Am Gründonnerstag ging Emma mit ihrem Vater auf die Tsimiski, die große Einkaufsstraße der Stadt.", "El Jueves Santo, Emma fue con su padre a la calle Tsimiskí, la gran calle comercial de la ciudad.", "On Maundy Thursday Emma went with her father to Tsimiski, the city's big shopping street.", "Ti Megáli Pémbti..."),
    N("Am Mittwoch hatte Karl allein ein Hemd gekauft. Ohne Emma, ohne Griechisch, nur mit dem Zeigefinger. Ein blaues Leinenhemd für Ostern, Größe XL. Am Abend probierte er es an. Er sah darin aus wie ein Segelboot.",
      "El miércoles, Karl se había comprado una camisa él solo. Sin Emma, sin griego, solo con el dedo índice. Una camisa azul de lino para Semana Santa, talla XL. Por la noche se la probó. Parecía un velero.",
      "On Wednesday Karl had bought a shirt on his own. No Emma, no Greek, just his index finger. A blue linen shirt for Easter, size XL. In the evening he tried it on. He looked like a sailing boat."),
    Z("—Καλημέρα. Ο πατέρας μου αγόρασε αυτό το πουκάμισο χθες, αλλά του πέφτει μεγάλο. Θα ήθελα να το αλλάξω.", "Guten Morgen. Mein Vater hat dieses Hemd gestern gekauft, aber es ist ihm zu groß. Ich möchte es umtauschen.", "Buenos días. Mi padre compró esta camisa ayer, pero le queda grande. Querría cambiarla.", "Good morning. My father bought this shirt yesterday, but it's too big for him. I'd like to exchange it.", "—Kaliméra. O patéras mou agórase aftó to poukámiso chthes, allá tou péfti megálo. Tha íthela na to alláxo."),
    Z("—Κανένα πρόβλημα. Έχετε την απόδειξη;", "Kein Problem. Haben Sie den Kassenzettel?", "Ningún problema. ¿Tienen el tique?", "No problem. Do you have the receipt?", "...Échete tin apódixi?"),
    N("Noch bevor Emma übersetzen konnte, lag die Quittung auf dem Tresen. Glatt gestrichen, sauber gefaltet, direkt aus der Brieftasche. Ihr Vater sah Emma an. Er sagte nichts. Er musste nichts sagen.",
      "Antes de que Emma pudiera traducir, el tique ya estaba sobre el mostrador. Bien alisado, doblado con cuidado, recién salido de la cartera. Su padre miró a Emma. No dijo nada. No hacía falta.",
      "Before Emma could translate, the receipt was already on the counter. Smoothed out, neatly folded, straight from the wallet. Her father looked at Emma. He said nothing. He didn't need to."),
    Z("—Τι νούμερο θέλετε;", "Welche Größe möchten Sie?", "¿Qué talla quiere?", "What size would you like?", "—Ti noúmero thélete?"),
    Z("—Ένα νούμερο μικρότερο, παρακαλώ. Large.", "Eine Nummer kleiner, bitte. Large.", "Una talla menos, por favor. La L.", "One size down, please. Large.", "—Éna noúmero mikrótero..."),
    Z("—Στο μπλε δεν έχουμε Large, δυστυχώς. Έχουμε σε άσπρο και σε πράσινο.", "In Blau haben wir leider kein Large. Wir haben es in Weiß und in Grün.", "En azul no nos queda la L, lo siento. La tenemos en blanco y en verde.", "We haven't got a large in blue, I'm afraid. We have it in white and in green.", "...Échoume se áspro ke se prásino."),
    Z("Ο πατέρας της διάλεξε το άσπρο. «Το Πάσχα φοράμε άσπρα», είπε στα γερμανικά, σαν να το ήξερε όλη του τη ζωή.", "Ihr Vater wählte Weiß. »Zu Ostern trägt man Weiß«, sagte er auf Deutsch, als hätte er das sein Leben lang gewusst.", "Su padre eligió el blanco. «En Pascua se va de blanco», dijo en alemán, como si lo hubiera sabido toda la vida.", "Her father chose white. “At Easter you wear white,” he said in German, as if he had known it all his life.", "...sto áspro..."),
    Z("—Υπάρχει διαφορά στην τιμή;", "Gibt es einen Preisunterschied?", "¿Hay diferencia de precio?", "Is there a difference in price?", "—Ipárchi diaforá stin timí?"),
    Z("—Όχι, είναι η ίδια τιμή. Τριάντα εννιά ευρώ.", "Nein, es ist derselbe Preis. Neununddreißig Euro.", "No, es el mismo precio. Treinta y nueve euros.", "No, it's the same price. Thirty-nine euros.", "...triánda enniá evró."),
    Z("—Μπορεί να το δοκιμάσει;", "Kann er es anprobieren?", "¿Se la puede probar?", "Can he try it on?", "—Borí na to dokimási?"),
    Z("—Βεβαίως. Το δοκιμαστήριο είναι εκεί, δεξιά.", "Selbstverständlich. Die Umkleidekabine ist dort rechts.", "Claro. El probador está ahí, a la derecha.", "Of course. The fitting room is over there, on the right.", "...To dokimastírio íne ekí, dexiá."),
    Z("Όσο ο πατέρας της πάλευε με τα κουμπιά, η πωλήτρια έδωσε στην Έμμα ένα κομμάτι τσουρέκι.", "Während ihr Vater mit den Knöpfen kämpfte, gab die Verkäuferin Emma ein Stück Tsoureki.", "Mientras su padre se peleaba con los botones, la dependienta le dio a Emma un trozo de tsoureki.", "While her father battled with the buttons, the shop assistant gave Emma a piece of tsoureki.", "...éna kommáti tsouréki."),
    Z("—Το έφτιαξε η μητέρα μου. Φάε, φάε!", "Das hat meine Mutter gebacken. Iss, iss!", "Lo ha hecho mi madre. ¡Come, come!", "My mother made it. Eat, eat!", "—To éftiaxe i mitéra mou. Fáe, fáe!"),
    N("Tsoureki ist der süße Osterzopf. Natürlich. Auch in einem Bekleidungsgeschäft wird man in Griechenland gefüttert.",
      "El tsoureki es el bollo dulce de Pascua. Cómo no. En Grecia te dan de comer hasta en una tienda de ropa.",
      "Tsoureki is the sweet Easter bread. Naturally. In Greece they feed you even in a clothes shop."),
    N("Ihr Vater kam heraus. Die Ärmel passten. Die Schultern passten. Nur am Bauch … Er flüsterte: »Wie sagt man: Es ist mir zu groß?« Emma brachte es ihm bei, Silbe für Silbe.",
      "Su padre salió. Las mangas le quedaban bien. Los hombros, también. Solo en la barriga… Susurró: «¿Cómo se dice: me queda grande?». Emma se lo enseñó, sílaba a sílaba.",
      "Her father came out. The sleeves fitted. The shoulders fitted. Only round the middle… He whispered: “How do you say: it's too big for me?” Emma taught him, syllable by syllable."),
    Z("—Μου πέφτει… μεγάλο;", "Es ist mir … zu groß?", "¿Me queda… grande?", "It's… too big for me?", "—Mou péfti… megálo?"),
    Z("—Όχι, όχι! Σας πάει πολύ! Είναι τέλειο.", "Nein, nein! Es steht Ihnen sehr gut! Es ist perfekt.", "¡No, no! ¡Le queda muy bien! Es perfecta.", "No, no! It really suits you! It's perfect.", "—Óchi, óchi! Sas pái polí!"),
    N("Bei jedem όχι hob die Verkäuferin das Kinn. Ihr Vater sah Emma hilflos an. »Nickt sie jetzt oder nicht?« — »Sie sagt, es steht dir, Papa.«",
      "Con cada όχι, la dependienta levantaba la barbilla. Su padre miró a Emma, perdido. «¿Eso es que sí o que no?». «Dice que te queda muy bien, papá».",
      "With every όχι the shop assistant tipped her chin up. Her father looked at Emma helplessly. “Is she nodding or not?” “She says it suits you, Dad.”"),
    Z("Ο πατέρας της πήρε το άσπρο πουκάμισο. Η πωλήτρια του έδωσε μια καινούρια απόδειξη.", "Ihr Vater nahm das weiße Hemd. Die Verkäuferin gab ihm einen neuen Kassenzettel.", "Su padre se quedó con la camisa blanca. La dependienta le dio un tique nuevo.", "Her father took the white shirt. The shop assistant gave him a new receipt."),
    Z("—Καλή Ανάσταση!", "Frohe Ostern! (wörtlich: Gute Auferstehung!)", "¡Feliz Pascua! (literalmente: ¡Buena Resurrección!)", "Happy Easter! (literally: A good Resurrection!)", "—Kalí Anástasi!"),
    N("So wünscht man sich in der Karwoche frohe Ostern. Draußen auf der Tsimiski faltete ihr Vater den neuen Kassenzettel und steckte ihn zum alten. »Siehst du?«, sagte er nur.",
      "Así se desea feliz Pascua durante la Semana Santa. Fuera, en la calle Tsimiskí, su padre dobló el tique nuevo y lo guardó junto al viejo. «¿Lo ves?», fue lo único que dijo.",
      "That's how you wish someone a happy Easter in Holy Week. Outside on Tsimiski, her father folded the new receipt and put it with the old one. “You see?” was all he said.")
  ]),

  // ── Station 16 · WETTER (A2) ──────────────────────────────────────────
  S("aufbau", 16, "wetter", "Ανάλογα με τον καιρό",
    "Rote Eier bei Frau Roula und ein Plan für Karfreitag: ans Meer, auf die Chalkidiki. Das Handy sagt Regen am Morgen. Der Olymp sagt dasselbe.",
    "Huevos rojos en casa de la señora Rula y un plan para el Viernes Santo: la playa, en Calcídica. El móvil dice que lloverá por la mañana. El Olimpo dice lo mismo.",
    "Red eggs at Mrs Roula's and a plan for Good Friday: the beach, in Halkidiki. The phone says rain in the morning. Olympus says the same.",
  [
    Z("Το βράδυ της Μεγάλης Πέμπτης η κυρία Ρούλα κάλεσε την οικογένεια στο σπίτι της, στο ισόγειο.", "Am Abend des Gründonnerstags lud Frau Roula die Familie zu sich ein, ins Erdgeschoss.", "La noche del Jueves Santo, la señora Rula invitó a la familia a su casa, en la planta baja.", "On the evening of Maundy Thursday, Mrs Roula invited the family round to her flat on the ground floor.", "...sto isóyio."),
    N("Ihre Küche roch nach Essig und Zwiebelschalen. Auf dem Tisch lagen drei Dutzend Eier, alle knallrot. Am Gründonnerstag färbt man in Griechenland die Ostereier. Rot, für das Blut Christi. Nur rot.",
      "Su cocina olía a vinagre y a piel de cebolla. Sobre la mesa había tres docenas de huevos, todos de un rojo intenso. En Grecia, los huevos de Pascua se tiñen el Jueves Santo. De rojo, por la sangre de Cristo. Solo de rojo.",
      "Her kitchen smelt of vinegar and onion skins. On the table lay three dozen eggs, all bright red. In Greece you dye the Easter eggs on Maundy Thursday. Red, for the blood of Christ. Only red."),
    Z("Η μητέρα της Έμμας έδωσε στην κυρία Ρούλα την τούρτα Σάχερ.", "Emmas Mutter gab Frau Roula die Sachertorte.", "La madre de Emma le dio a la señora Rula la tarta Sacher.", "Emma's mother gave Mrs Roula the Sachertorte."),
    Z("—Για μένα; Από τη Βιέννη; Ε, τώρα θα φάτε κι εσείς κάτι. Τσουρέκι!", "Für mich? Aus Wien? Na, dann esst ihr jetzt auch etwas. Tsoureki!", "¿Para mí? ¿De Viena? Bueno, pues ahora coméis vosotros algo. ¡Tsoureki!", "For me? From Vienna? Well, now you'll eat something too. Tsoureki!"),
    Z("—Κυρία Ρούλα, αύριο θέλουμε να πάμε στη Χαλκιδική, στη θάλασσα. Αλλά εξαρτάται από τον καιρό. Τι λέτε; Θα κάνει καλό καιρό;", "Frau Roula, morgen wollen wir auf die Chalkidiki fahren, ans Meer. Aber das hängt vom Wetter ab. Was meinen Sie? Wird das Wetter schön?", "Señora Rula, mañana queremos ir a Calcídica, a la playa. Pero depende del tiempo. ¿Usted qué dice? ¿Hará buen tiempo?", "Mrs Roula, tomorrow we want to go to Halkidiki, to the sea. But it depends on the weather. What do you think? Will the weather be nice?", "...Allá exartáte apó ton keró. Ti léte? Tha káni kaló keró?"),
    N("Frau Roula sagt das Wetter nicht mit dem Handy voraus. Sie fragt den Olymp. Sie ging auf den Balkon und schaute lange über den Golf, dorthin, wo der Berg im Abendlicht stand.",
      "La señora Rula no predice el tiempo con el móvil. Se lo pregunta al Olimpo. Salió al balcón y estuvo un buen rato mirando al otro lado del golfo, hacia la montaña, a la luz del atardecer.",
      "Mrs Roula doesn't forecast the weather with a phone. She asks Olympus. She went out onto the balcony and looked across the gulf for a long time, to where the mountain stood in the evening light."),
    Z("—Η θάλασσα είναι λάδι. Αλλά βλέπετε; Ο Όλυμπος φοράει καπέλο. Αύριο το πρωί θα βρέξει.", "Das Meer ist Öl. Aber seht ihr? Der Olymp trägt einen Hut. Morgen früh wird es regnen.", "El mar es aceite. Pero ¿veis? El Olimpo lleva sombrero. Mañana por la mañana lloverá.", "The sea is oil. But do you see? Olympus is wearing a hat. Tomorrow morning it'll rain.", "—I thálassa íne ládi. Allá vlépete? O Ólimbos forái kapélo. Ávrio to proí tha vréxi."),
    Z("—Θα βρέξει; Όλη τη μέρα;", "Es wird regnen? Den ganzen Tag?", "¿Lloverá? ¿Todo el día?", "It'll rain? All day?"),
    Z("—Όχι. Το μεσημέρι θα σταματήσει. Το απόγευμα θα βγει ήλιος και θα έρθει η μπουκαδούρα.", "Nein. Mittags hört es auf. Am Nachmittag kommt die Sonne heraus, und die Bukadura kommt.", "No. Al mediodía parará. Por la tarde saldrá el sol y llegará la bukadura.", "No. It'll stop at midday. In the afternoon the sun will come out and the boukadoura will blow in.", "...to apóyevma tha vyi ílios ke tha érthi i boukadoúra."),
    N("Die Bukadura ist der Wind, der an warmen Nachmittagen vom Meer in die Stadt weht. Frisch, salzig, pünktlich. Pünktlicher als jeder Grieche.",
      "La bukadura es el viento que sopla del mar hacia la ciudad las tardes de calor. Fresco, salado, puntual. Más puntual que cualquier griego.",
      "The boukadoura is the wind that blows in from the sea on warm afternoons. Fresh, salty, punctual. More punctual than any Greek."),
    N("Ihr Vater holte das Handy heraus, öffnete die Wetter-App und hielt sie Emma hin. Emma las vor.",
      "Su padre sacó el móvil, abrió la aplicación del tiempo y se la tendió a Emma. Emma la leyó en voz alta.",
      "Her father took out his phone, opened the weather app and held it out to Emma. Emma read it aloud."),
    Z("—Το πρωί θα βρέχει, λέει. Το απόγευμα θα βγει ήλιος, αλλά θα φυσάει λίγο.", "Am Vormittag regnet es, steht da. Am Nachmittag kommt die Sonne heraus, aber es wird ein bisschen windig.", "Por la mañana lloverá, dice. Por la tarde saldrá el sol, pero hará un poco de viento.", "It'll be raining in the morning, it says. In the afternoon the sun will come out, but it'll be a bit windy.", "—To proí tha vréchi, léi. To apóyevma tha vyi ílios, allá tha fisái lígo."),
    Z("—Ε, ναι. Αυτό σας λέω κι εγώ. Αλλά ο Όλυμπος το είπε πρώτος.", "Na ja. Das sage ich euch doch. Aber der Olymp hat es zuerst gesagt.", "Pues sí. Eso mismo os digo yo. Pero el Olimpo lo ha dicho antes.", "Well, yes. That's what I'm telling you. But Olympus said it first."),
    N("Emma erinnerte sich an einen Sonntag im Oktober. Der Olymp hatte einen Hut getragen, die App hatte Sonne versprochen, und Emma hatte der App geglaubt. Am Montag war sie bis auf die Haut nass geworden. Seitdem glaubt sie dem Berg.",
      "Emma se acordó de un domingo de octubre. El Olimpo llevaba sombrero, la aplicación prometía sol y Emma creyó a la aplicación. El lunes acabó calada hasta los huesos. Desde entonces, le cree a la montaña.",
      "Emma remembered a Sunday in October. Olympus had been wearing a hat, the app had promised sun, and Emma had believed the app. On the Monday she got soaked to the skin. Since then she has believed the mountain."),
    Z("—Τότε θα φύγουμε στις δέκα. Θα πάρουμε το ΚΤΕΛ και θα φτάσουμε το μεσημέρι, όταν θα σταματήσει η βροχή.", "Dann fahren wir um zehn los. Wir nehmen den Überlandbus und kommen mittags an, wenn der Regen aufhört.", "Entonces saldremos a las diez. Cogeremos el autobús de línea y llegaremos al mediodía, cuando pare la lluvia.", "Then we'll leave at ten. We'll take the KTEL coach and get there at midday, when the rain stops.", "...Tha pároume to KTEL..."),
    Z("—Και πάρτε μπουφάν. Για καλό και για κακό. Τον Απρίλιο ο καιρός αλλάζει γρήγορα.", "Und nehmt Jacken mit. Für alle Fälle. Im April ändert sich das Wetter schnell.", "Y llevaos chaquetas. Por si acaso. En abril el tiempo cambia rápido.", "And take jackets. Just in case. In April the weather changes quickly.", "—Ke párte boufán. Gia kaló ke gia kakó."),
    Z("—Και ομπρέλα;", "Und einen Schirm?", "¿Y paraguas?", "And an umbrella?", "—Ke ombréla?"),
    Z("—Ομπρέλα οπωσδήποτε. Εσύ, Έμμα, πάρε δύο.", "Einen Schirm auf jeden Fall. Du, Emma, nimmst zwei.", "Paraguas, sin falta. Tú, Emma, coge dos.", "An umbrella, definitely. You, Emma, take two.", "—Ombréla oposdípote."),
    N("Zum Abschied lud Frau Roula die ganze Familie zum Ostersonntag ein. Zu ihrem Sohn Nikos, in sein Haus am Stadtrand, zum Lamm am Spieß. Es war keine Frage. Es war eine Vorhersage.",
      "Al despedirse, la señora Rula invitó a toda la familia al Domingo de Pascua. A casa de su hijo Nikos, a las afueras, a comer cordero asado en el espetón. No era una pregunta. Era un pronóstico.",
      "As they said goodnight, Mrs Roula invited the whole family for Easter Sunday. To her son Nikos's house on the edge of town, for lamb on the spit. It wasn't a question. It was a forecast."),
    Z("—Την Κυριακή θα έρθετε στον γιο μου. Θα φάμε αρνί. Και θα κάνει καλό καιρό. Το λέει ο Όλυμπος.", "Am Sonntag kommt ihr zu meinem Sohn. Wir essen Lamm. Und das Wetter wird schön. Das sagt der Olymp.", "El domingo venís a casa de mi hijo. Comeremos cordero. Y hará buen tiempo. Lo dice el Olimpo.", "On Sunday you're coming to my son's. We'll eat lamb. And the weather will be fine. Olympus says so.", "...Tha fáme arní...")
  ]),

  // ── Station 17 · BAHNHOF (A2) ─────────────────────────────────────────
  S("aufbau", 17, "bahnhof", "Χάσαμε την ανταπόκριση",
    "Karfreitag: Regen, ein Busbahnhof voller Osterkerzen, eine Verspätung und ein verpasster Anschluss. Und dann, wie angekündigt, die Sonne.",
    "Viernes Santo: lluvia, una estación de autobuses llena de cirios de Pascua, un retraso y un enlace perdido. Y después, tal como estaba previsto, el sol.",
    "Good Friday: rain, a coach station full of Easter candles, a delay and a missed connection. And then, as forecast, the sun.",
  [
    Z("Τη Μεγάλη Παρασκευή το πρωί έβρεχε. Όπως είπε η κυρία Ρούλα.", "Am Karfreitagmorgen regnete es. Wie Frau Roula gesagt hatte.", "El Viernes Santo por la mañana llovía. Como había dicho la señora Rula.", "On Good Friday morning it was raining. Just as Mrs Roula had said.", "Ti Megáli Paraskeví to proí évreche."),
    Z("Η οικογένεια πήγε στον σταθμό του ΚΤΕΛ Χαλκιδικής. Ο σταθμός ήταν γεμάτος κόσμο, βαλίτσες και λαμπάδες.", "Die Familie fuhr zum Busbahnhof der Chalkidiki-Linien. Der Bahnhof war voller Menschen, Koffer und Osterkerzen.", "La familia fue a la estación de autobuses de Calcídica. La estación estaba llena de gente, maletas y cirios.", "The family went to the Halkidiki coach station. The station was full of people, suitcases and Easter candles.", "...ítan yemátos kósmo, valítses ke labádes."),
    N("Am Karfreitag fährt halb Thessaloniki in die Dörfer: zu den Großeltern, zur Kirche, nach Hause. Jeder trägt etwas — einen Koffer, ein Kind, eine lange weiße Osterkerze in Folie.",
      "El Viernes Santo, media Tesalónica se va a los pueblos: a casa de los abuelos, a la iglesia, a casa. Todo el mundo lleva algo: una maleta, un niño, un cirio blanco y largo envuelto en plástico.",
      "On Good Friday half of Thessaloniki heads out to the villages: to the grandparents, to church, home. Everyone is carrying something — a suitcase, a child, a long white Easter candle wrapped in cellophane."),
    Z("—Καλημέρα. Τρία εισιτήρια για ενήλικες και ένα παιδικό για την Άφυτο, παρακαλώ.", "Guten Morgen. Drei Fahrkarten für Erwachsene und eine Kinderfahrkarte nach Afytos, bitte.", "Buenos días. Tres billetes de adulto y uno infantil para Afytos, por favor.", "Good morning. Three adult tickets and one child's ticket to Afytos, please.", "—Tría isitíria gia enílikes ke éna pedikó gia tin Áfito."),
    Z("—Για την Άφυτο δεν έχει απευθείας. Θα πάρετε το λεωφορείο για τα Μουδανιά και εκεί θα αλλάξετε.", "Nach Afytos gibt es keine direkte Verbindung. Sie nehmen den Bus nach Moudania und steigen dort um.", "Para Afytos no hay directo. Cogerán el autobús a Moudaniá y allí harán transbordo.", "There's no direct coach to Afytos. You'll take the coach to Moudania and change there.", "...den échi apefthías... ke ekí tha alláxete."),
    Z("—Και πόση ώρα έχουμε για την ανταπόκριση;", "Und wie viel Zeit haben wir zum Umsteigen?", "¿Y cuánto tiempo tenemos para el enlace?", "And how much time do we have for the connection?", "—Ke pósi óra échoume gia tin andapókrisi?"),
    Z("—Δέκα λεπτά. Αν το λεωφορείο φύγει στην ώρα του.", "Zehn Minuten. Wenn der Bus pünktlich abfährt.", "Diez minutos. Si el autobús sale a su hora.", "Ten minutes. If the coach leaves on time."),
    Z("—Και αν τη χάσουμε, τι γίνεται;", "Und wenn wir ihn verpassen, was dann?", "¿Y si lo perdemos, qué pasa?", "And if we miss it, what happens?", "—Ke an ti chásoume, ti yínete?"),
    Z("—Τότε παίρνετε το επόμενο. Το εισιτήριό σας ισχύει κανονικά.", "Dann nehmen Sie den nächsten. Ihre Fahrkarte gilt ganz normal.", "Entonces cogen el siguiente. Su billete sigue valiendo.", "Then you take the next one. Your ticket is still valid.", "—Tóte pérnete to epómeno. To isitírió sas ischíi kanoniká."),
    N("»Wenn er pünktlich abfährt.« Emma kannte diese Art von Satz. Im Oktober, auf dem Weg nach Veria, hatte der Zug »ein bisschen« Verspätung gehabt: fast anderthalb Stunden.",
      "«Si sale a su hora». Emma conocía ese tipo de frases. En octubre, de camino a Veria, el tren había llevado «un poco» de retraso: casi hora y media.",
      "“If it leaves on time.” Emma knew that kind of sentence. In October, on the way to Veria, the train had been “a bit” late: nearly an hour and a half."),
    Z("Το λεωφορείο δεν έφυγε στην ώρα του. Έφυγε με είκοσι λεπτά καθυστέρηση. Στον δρόμο είχε βροχή, κίνηση και ένα φορτηγό με αρνιά.", "Der Bus fuhr nicht pünktlich ab. Er fuhr mit zwanzig Minuten Verspätung. Unterwegs gab es Regen, Verkehr und einen Lastwagen mit Lämmern.", "El autobús no salió a su hora. Salió con veinte minutos de retraso. Por el camino hubo lluvia, tráfico y un camión lleno de corderos.", "The coach didn't leave on time. It left twenty minutes late. On the way there was rain, traffic and a lorry full of lambs.", "...me íkosi leptá kathistérisi..."),
    N("Felix drückte die Nase an die Scheibe und zählte die Lämmer. Seine Mutter bat ihn, damit aufzuhören. Es war Karfreitag, und am Sonntag … Sie sprach den Satz nicht zu Ende.",
      "Felix pegó la nariz a la ventanilla y contó los corderos. Su madre le pidió que lo dejara. Era Viernes Santo, y el domingo… No terminó la frase.",
      "Felix pressed his nose to the window and counted the lambs. His mother asked him to stop. It was Good Friday, and on Sunday… She didn't finish the sentence."),
    Z("Στα Μουδανιά η Έμμα έτρεξε στο εκδοτήριο.", "In Moudania rannte Emma zum Fahrkartenschalter.", "En Moudaniá, Emma corrió a la taquilla.", "In Moudania Emma ran to the ticket office.", "...sto ekdotírio."),
    Z("—Συγγνώμη, το λεωφορείο για την Άφυτο έφυγε;", "Entschuldigung, ist der Bus nach Afytos schon weg?", "Perdone, ¿el autobús a Afytos ya ha salido?", "Excuse me, has the coach to Afytos gone?"),
    Z("—Έφυγε πριν από δέκα λεπτά. Το επόμενο είναι στη μία και μισή.", "Er ist vor zehn Minuten abgefahren. Der nächste fährt um halb zwei.", "Salió hace diez minutos. El siguiente es a la una y media.", "It left ten minutes ago. The next one is at half past one.", "...To epómeno íne sti mía ke misí."),
    Z("—Χάσαμε την ανταπόκριση! Και τώρα τι κάνουμε;", "Wir haben den Anschluss verpasst! Und was machen wir jetzt?", "¡Hemos perdido el enlace! ¿Y ahora qué hacemos?", "We've missed the connection! So what do we do now?", "—Chásame tin andapókrisi!"),
    Z("—Τι να κάνετε; Περιμένετε. Πιείτε έναν καφέ. Είναι Μεγάλη Παρασκευή, κανείς δεν βιάζεται.", "Was sollen Sie schon machen? Warten Sie. Trinken Sie einen Kaffee. Es ist Karfreitag, niemand hat es eilig.", "¿Qué van a hacer? Esperar. Tómense un café. Es Viernes Santo, nadie tiene prisa.", "What can you do? Wait. Have a coffee. It's Good Friday, nobody's in a hurry.", "...kanís den viázete."),
    N("Also warteten sie, anderthalb Stunden, in einem Kafeneio neben der Haltestelle. Die Kirchenglocken läuteten langsam und traurig. Ihr Vater, der in vierzig Jahren keine Straßenbahn zu spät losgeschickt hatte, sah alle fünf Minuten auf die Uhr. Dann, irgendwann, hörte er auf.",
      "Así que esperaron hora y media en un café junto a la parada. Las campanas de la iglesia tocaban lentas y tristes. Su padre, que en cuarenta años no había sacado un tranvía con retraso, miraba el reloj cada cinco minutos. Luego, en algún momento, dejó de hacerlo.",
      "So they waited, an hour and a half, in a kafeneio next to the stop. The church bells tolled, slow and sad. Her father, who in forty years had never sent a tram out late, checked his watch every five minutes. Then, at some point, he stopped."),
    Z("Στη μία η βροχή σταμάτησε και βγήκε ο ήλιος. Όπως είπε η κυρία Ρούλα. Το επόμενο λεωφορείο ήρθε στη μία και πενήντα. Κανείς δεν είπε τίποτα.", "Um eins hörte der Regen auf, und die Sonne kam heraus. Wie Frau Roula gesagt hatte. Der nächste Bus kam um zehn vor zwei. Niemand sagte etwas.", "A la una dejó de llover y salió el sol. Como había dicho la señora Rula. El siguiente autobús llegó a las dos menos diez. Nadie dijo nada.", "At one the rain stopped and the sun came out. Just as Mrs Roula had said. The next coach came at ten to two. Nobody said a word."),
    N("Um drei standen sie am Strand von Afytos. Das Meer war tatsächlich Öl: glatt, türkis, leer. Ihr Vater zog die Schuhe aus und ging bis zu den Knöcheln hinein. Achtzehn Grad. Er schrie, und eine Möwe flog empört davon.",
      "A las tres estaban en la playa de Afytos. El mar estaba como un plato, de verdad: liso, turquesa, vacío. Su padre se quitó los zapatos y se metió hasta los tobillos. Dieciocho grados. Gritó, y una gaviota se fue volando, indignada.",
      "At three they were standing on the beach at Afytos. The sea really was like a millpond: smooth, turquoise, empty. Her father took off his shoes and waded in up to his ankles. Eighteen degrees. He yelled, and a seagull flew off in disgust."),
    Z("Το βράδυ, στο χωριό, είδαν τον Επιτάφιο. Όλο το χωριό περπατούσε αργά, με κεριά στα χέρια.", "Am Abend sahen sie im Dorf den Epitaphios. Das ganze Dorf ging langsam, mit Kerzen in den Händen.", "Por la noche, en el pueblo, vieron el Epitafio. Todo el pueblo caminaba despacio, con velas en las manos.", "In the evening, in the village, they watched the Epitaphios. The whole village walked slowly, candles in their hands.", "...ídan ton Epitáfio..."),
    N("Der Epitaphios ist das mit Blumen geschmückte Grab Christi, das man am Karfreitagabend durch die Straßen trägt. Felix, der sonst nie still ist, war eine ganze Stunde lang still. Den letzten Bus zurück bekamen sie trotzdem. Er hatte Verspätung. Natürlich.",
      "El Epitafio es el sepulcro de Cristo adornado con flores que se lleva por las calles la noche del Viernes Santo. Felix, que nunca está callado, estuvo callado una hora entera. Aun así, cogieron el último autobús de vuelta. Llevaba retraso. Cómo no.",
      "The Epitaphios is Christ's tomb, decorated with flowers, carried through the streets on the evening of Good Friday. Felix, who is never quiet, was quiet for a whole hour. They still caught the last coach back. It was late. Of course.")
  ]),

  // ── Station 18 · RESTAURANT (A2) ──────────────────────────────────────
  S("aufbau", 18, "restaurant", "Κάτι πιο ελαφρύ",
    "Ostersonntag: Lamm am Spieß bei Roulas Sohn, dreißig Gäste, rote Eier — und eine Spezialität, die Emma lieber nicht übersetzt.",
    "Domingo de Pascua: cordero en el espetón en casa del hijo de Rula, treinta invitados, huevos rojos y una especialidad que Emma prefiere no traducir.",
    "Easter Sunday: lamb on the spit at Roula's son's, thirty guests, red eggs — and a speciality Emma would rather not translate.",
  [
    Z("Το Μεγάλο Σάββατο, στις δώδεκα τα μεσάνυχτα, όλη η πόλη ήταν στις εκκλησίες. «Χριστός Ανέστη!» φώναξε ο παπάς. «Αληθώς Ανέστη!» απάντησαν όλοι.", "Am Karsamstag um Mitternacht war die ganze Stadt in den Kirchen. »Christus ist auferstanden!«, rief der Priester. »Er ist wahrhaftig auferstanden!«, antworteten alle.", "El Sábado Santo, a las doce de la noche, toda la ciudad estaba en las iglesias. «¡Cristo ha resucitado!», gritó el cura. «¡En verdad ha resucitado!», respondieron todos.", "On Holy Saturday at midnight the whole city was in church. “Christ is risen!” called the priest. “He is risen indeed!” everyone answered.", "«Christós Anésti!» ... «Alithós Anésti!»"),
    N("Glocken, Feuerwerk, tausend Kerzen in tausend Händen. Ihr Vater stand mittendrin und weinte ein bisschen, was er später abstritt. Auf den Stufen der Kirche rutschte er auf Kerzenwachs aus. Er fiel auf die Schulter, stand sofort wieder auf und sagte: »Passt schon.« In Wien heißt das alles zwischen »gut« und »ich sterbe«.",
      "Campanas, fuegos artificiales, mil velas en mil manos. Su padre, en medio de todo, lloró un poco, cosa que después negó. En los escalones de la iglesia resbaló con la cera de las velas. Cayó sobre el hombro, se levantó enseguida y dijo: «Passt schon». En Viena eso significa cualquier cosa entre «bien» y «me muero».",
      "Bells, fireworks, a thousand candles in a thousand hands. Her father stood in the middle of it all and cried a little, which he later denied. On the church steps he slipped on candle wax. He landed on his shoulder, got straight back up and said: “Passt schon.” In Vienna that means anything between “fine” and “I'm dying”."),
    Z("Την Κυριακή του Πάσχα πήγαν όλοι στο σπίτι του Νίκου, του γιου της κυρίας Ρούλας. Στην αυλή γύριζε ένα ολόκληρο αρνί στη σούβλα.", "Am Ostersonntag fuhren alle zum Haus von Nikos, Frau Roulas Sohn. Im Hof drehte sich ein ganzes Lamm am Spieß.", "El Domingo de Pascua fueron todos a casa de Nikos, el hijo de la señora Rula. En el patio giraba un cordero entero en el espetón.", "On Easter Sunday they all went to the house of Nikos, Mrs Roula's son. In the yard a whole lamb was turning on the spit.", "...éna olókliro arní sti soúvla."),
    N("Dreißig Leute: Nikos, seine Frau, drei Kinder, Cousins, Nachbarn, ein Onkel aus Kozani, ein Hund. Auf einem langen Tisch standen Salate, Käse, Tzatziki, rote Eier, Wein. Die Sonne schien. Der Olymp hatte es gesagt.",
      "Treinta personas: Nikos, su mujer, tres niños, primos, vecinos, un tío de Kozani, un perro. En una mesa larga había ensaladas, queso, tzatziki, huevos rojos, vino. Hacía sol. El Olimpo lo había dicho.",
      "Thirty people: Nikos, his wife, three children, cousins, neighbours, an uncle from Kozani, a dog. On a long table were salads, cheese, tzatziki, red eggs, wine. The sun was shining. Olympus had said so."),
    Z("—Χριστός Ανέστη! Καλώς ήρθατε! Τι θα πιείτε; Κρασί; Τσίπουρο;", "Christus ist auferstanden! Willkommen! Was trinkt ihr? Wein? Tsipouro?", "¡Cristo ha resucitado! ¡Bienvenidos! ¿Qué vais a beber? ¿Vino? ¿Tsipouro?", "Christ is risen! Welcome! What will you drink? Wine? Tsipouro?", "...Ti tha piíte? Krasí? Tsípouro?"),
    Z("—Αληθώς Ανέστη! Λίγο κρασί, ευχαριστούμε.", "Er ist wahrhaftig auferstanden! Ein bisschen Wein, danke.", "¡En verdad ha resucitado! Un poco de vino, gracias.", "He is risen indeed! A little wine, thank you."),
    Z("—Και να φάτε!", "Und esst!", "¡Y a comer!", "And eat!"),
    Z("—Ευχαριστούμε! Ποια είναι η σπεσιαλιτέ σας;", "Danke! Was ist Ihre Spezialität?", "¡Gracias! ¿Cuál es su especialidad?", "Thank you! What's your speciality?", "—Efcharistoúme! Pia íne i spesialité sas?"),
    Z("—Το κοκορέτσι! Να σας βάλω;", "Kokoretsi! Soll ich euch etwas geben?", "¡El kokoretsi! ¿Os sirvo?", "Kokoretsi! Shall I give you some?", "—To kokorétsi! Na sas válo?"),
    N("Kokoretsi: Innereien vom Lamm, in Darm gewickelt, stundenlang am Spieß gegrillt. Emma übersetzte das nicht. Nicht genau. Sie sagte »eine Art Wurst«.",
      "Kokoretsi: asaduras de cordero envueltas en tripa y asadas durante horas en el espetón. Emma no lo tradujo. No exactamente. Dijo «una especie de salchicha».",
      "Kokoretsi: lamb offal wrapped in intestine and roasted on the spit for hours. Emma didn't translate that. Not exactly. She said “a sort of sausage”."),
    Z("—Ο αδερφός μου δεν τρώει κοκορέτσι. Μήπως έχετε κάτι πιο ελαφρύ;", "Mein Bruder isst kein Kokoretsi. Habt ihr etwas Leichteres?", "Mi hermano no come kokoretsi. ¿Tenéis algo más ligero?", "My brother doesn't eat kokoretsi. Have you got anything lighter?", "...Mípos échete káti pio elafrí?"),
    Z("—Πιο ελαφρύ; Είναι Πάσχα, κορίτσι μου! Εντάξει, έχουμε σαλάτα και πατάτες στο φούρνο. Και αρνί, βέβαια.", "Leichter? Es ist Ostern, Mädchen! Na gut, wir haben Salat und Ofenkartoffeln. Und Lamm natürlich.", "¿Más ligero? ¡Es Pascua, hija! Bueno, tenemos ensalada y patatas al horno. Y cordero, claro.", "Lighter? It's Easter, my girl! All right, we've got salad and roast potatoes. And lamb, of course."),
    N("Dann das Eierpecken. Jeder nimmt ein rotes Ei und schlägt es gegen das Ei des anderen, Spitze gegen Spitze. Wessen Ei ganz bleibt, hat ein Jahr lang Glück. Felix gewann gegen alle: gegen Nikos, gegen den Onkel aus Kozani, sogar gegen Frau Roula.",
      "Luego, el choque de huevos. Cada uno coge un huevo rojo y lo golpea contra el del otro, punta contra punta. Aquel cuyo huevo queda entero tiene suerte todo el año. Felix les ganó a todos: a Nikos, al tío de Kozani, incluso a la señora Rula.",
      "Then the egg-tapping. Everyone takes a red egg and knocks it against someone else's, tip to tip. Whoever's egg stays whole has luck for a year. Felix beat everyone: Nikos, the uncle from Kozani, even Mrs Roula."),
    Z("—Το αυγό του Φέλιξ είναι από ατσάλι! Μπράβο, παλικάρι μου!", "Felix' Ei ist aus Stahl! Bravo, mein Junge!", "¡El huevo de Felix es de acero! ¡Bravo, chaval!", "Felix's egg is made of steel! Well done, lad!", "—To avgó tou Félix íne apó atsáli! Brávo, palikári mou!"),
    N("Emma bemerkte, dass ihr Vater nur mit der linken Hand aß. Die rechte lag still auf dem Tisch. »Papa? Die Schulter?« — »Passt schon.«",
      "Emma se dio cuenta de que su padre comía solo con la mano izquierda. La derecha descansaba quieta sobre la mesa. «¿Papá? ¿El hombro?». «Passt schon».",
      "Emma noticed that her father was eating only with his left hand. His right lay still on the table. “Dad? Your shoulder?” “Passt schon.”"),
    Z("Στις τέσσερις η Έμμα είχε φάει αρνί, πατάτες, τυρί, δύο αυγά και τρία κομμάτια τσουρέκι.", "Um vier hatte Emma Lamm, Kartoffeln, Käse, zwei Eier und drei Stück Tsoureki gegessen.", "A las cuatro, Emma había comido cordero, patatas, queso, dos huevos y tres trozos de tsoureki.", "By four o'clock Emma had eaten lamb, potatoes, cheese, two eggs and three pieces of tsoureki."),
    Z("—Κυρία Ρούλα, δεν μπορώ άλλο. Είμαι πολύ χορτάτη.", "Frau Roula, ich kann nicht mehr. Ich bin sehr satt.", "Señora Rula, no puedo más. Estoy llenísima.", "Mrs Roula, I can't eat any more. I'm completely full.", "...den boró állo. Íme polí chortáti."),
    Z("—Τι χορτάτη; Είσαι πολύ αδύνατη! Φάε λίγο ακόμα.", "Was heißt satt? Du bist viel zu dünn! Iss noch ein bisschen.", "¿Cómo que llena? ¡Si estás muy delgada! Come un poco más.", "Full? You're far too thin! Have a bit more.", "...Íse polí adínati!"),
    Z("Ο Νίκος σήκωσε το ποτήρι του. Σηκώθηκαν όλοι.", "Nikos hob sein Glas. Alle standen auf.", "Nikos levantó su copa. Todos se pusieron de pie.", "Nikos raised his glass. Everyone stood up."),
    Z("—Γεια μας!", "Auf uns! (wörtlich: Unsere Gesundheit!)", "¡Salud! (literalmente: ¡Nuestra salud!)", "Cheers! (literally: Our health!)", "—Giá mas!"),
    N("Ihr Vater hob sein Glas. Mit der linken Hand.",
      "Su padre levantó su copa. Con la mano izquierda.",
      "Her father raised his glass. With his left hand.")
  ]),

  // ── Station 19 · ARZT (A2) ────────────────────────────────────────────
  S("aufbau", 19, "arzt", "Γλίστρησε",
    "Ostermontag: Papas »Passt schon« passt nicht mehr. Ein Krankenhaus im Feiertagsdienst, eine Penicillin-Allergie, ein Röntgenbild — und ein Ναι, das wieder wie Nein klingt.",
    "Lunes de Pascua: el «Passt schon» de su padre ya no cuela. Un hospital de guardia, una alergia a la penicilina, una radiografía y un ναι que vuelve a sonar a «nein».",
    "Easter Monday: Dad's “Passt schon” won't do any more. An on-duty hospital, a penicillin allergy, an X-ray — and a ναι that sounds like “nein” all over again.",
  [
    Z("Τη Δευτέρα του Πάσχα, το πρωί, ο πατέρας της Έμμας δεν μπορούσε να σηκώσει το χέρι του.", "Am Ostermontagmorgen konnte Emmas Vater seinen Arm nicht heben.", "El lunes de Pascua por la mañana, el padre de Emma no podía levantar el brazo.", "On Easter Monday morning Emma's father couldn't lift his arm.", "...den boroúse na sikósi to chéri tou."),
    N("Er konnte sich nicht allein anziehen. Das neue weiße Hemd knöpfte ihm Brigitte zu, Knopf für Knopf. »Passt schon«, sagte er. Diesmal glaubte es niemand. Nicht einmal er selbst.",
      "No podía vestirse solo. Brigitte le abrochó la camisa blanca nueva, botón a botón. «Passt schon», dijo. Esta vez nadie se lo creyó. Ni siquiera él.",
      "He couldn't dress himself. Brigitte buttoned up the new white shirt for him, button by button. “Passt schon,” he said. This time nobody believed him. Not even he did."),
    Z("Το Πάσχα τα κέντρα υγείας είναι κλειστά. Η Έμμα πήγε την οικογένεια στο εφημερεύον νοσοκομείο.", "An Ostern sind die Gesundheitszentren geschlossen. Emma brachte die Familie ins diensthabende Krankenhaus.", "En Pascua los centros de salud están cerrados. Emma llevó a la familia al hospital de guardia.", "At Easter the health centres are closed. Emma took the family to the on-duty hospital.", "...sto efimerévon nosokomío."),
    N("In Griechenland hat an Feiertagen immer ein Krankenhaus Dienst; welches, steht im Internet. Emma hatte es in der Nacht nachgeschaut. Seit Oktober weiß sie, wie man hier zum Arzt kommt.",
      "En Grecia, los días festivos siempre hay un hospital de guardia; cuál, lo pone en internet. Emma lo había mirado por la noche. Desde octubre sabe cómo se va al médico aquí.",
      "In Greece there's always a hospital on duty on public holidays; which one, you can find online. Emma had looked it up during the night. Since October she has known how to see a doctor here."),
    Z("Μετά από μία ώρα στην αναμονή, τους φώναξε μια γιατρός.", "Nach einer Stunde im Wartebereich rief eine Ärztin sie auf.", "Después de una hora en la sala de espera, los llamó una médica.", "After an hour in the waiting area, a doctor called them in.", "...stin anamoní... mia giatrós."),
    Z("—Καλημέρα. Πείτε μου, τι έγινε;", "Guten Morgen. Erzählen Sie, was ist passiert?", "Buenos días. Dígame, ¿qué ha pasado?", "Good morning. Tell me, what happened?", "—Kaliméra. Píte mou, ti éyine?"),
    Z("—Ο πατέρας μου γλίστρησε στην Ανάσταση, στα σκαλιά της εκκλησίας. Έπεσε στον δεξί ώμο.", "Mein Vater ist in der Osternacht auf den Stufen der Kirche ausgerutscht. Er ist auf die rechte Schulter gefallen.", "Mi padre resbaló en la misa de Resurrección, en los escalones de la iglesia. Se cayó sobre el hombro derecho.", "My father slipped at the Resurrection service, on the church steps. He fell on his right shoulder.", "...glístrise stin Anástasi, sta skaliá tis ekklisías. Épese ston dexí ómo."),
    Z("—Πού ακριβώς πονάει;", "Wo genau tut es weh?", "¿Dónde le duele exactamente?", "Where exactly does it hurt?", "—Poú akrivós ponái?"),
    Z("—Εδώ. Και δεν μπορεί να σηκώσει το χέρι.", "Hier. Und er kann den Arm nicht heben.", "Aquí. Y no puede levantar el brazo.", "Here. And he can't lift his arm."),
    Z("—Πονάει πολύ;", "Tut es sehr weh?", "¿Le duele mucho?", "Does it hurt a lot?"),
    N("Emma übersetzte. Ihr Vater sagte: »Geht schon.« Emma übersetzte: «Πονάει πολύ.» Die Ärztin sah erst ihn an, dann Emma, und verstand beide Übersetzungen.",
      "Emma tradujo. Su padre dijo: «Geht schon», o sea, «no es nada». Emma tradujo: «Πονάει πολύ», le duele mucho. La médica lo miró a él, luego a Emma, y entendió las dos traducciones.",
      "Emma translated. Her father said: “Geht schon” — it's nothing. Emma translated: «Πονάει πολύ» — it hurts a lot. The doctor looked first at him, then at Emma, and understood both translations."),
    Z("—Είναι αλλεργικός σε κάποιο φάρμακο;", "Ist er gegen ein Medikament allergisch?", "¿Es alérgico a algún medicamento?", "Is he allergic to any medication?", "—Íne alleryikós se kápio fármako?"),
    Z("—Ναι, είναι αλλεργικός στην πενικιλίνη.", "Ja, er ist gegen Penicillin allergisch.", "Sí, es alérgico a la penicilina.", "Yes, he's allergic to penicillin.", "—Ne, íne alleryikós stin penikilíni."),
    N("Ihr Vater hörte ναι und rief sofort: »Nein, nein! Penicillin — ja! Allergisch — ja!« Die Ärztin lachte zum ersten Mal.",
      "Su padre oyó ναι y gritó enseguida: «¡Nein, nein! ¡Penicilina, ja! ¡Alérgico, ja!». La médica se rio por primera vez.",
      "Her father heard ναι and immediately cried: “Nein, nein! Penicillin — ja! Allergic — ja!” The doctor laughed for the first time."),
    Z("—Έχει ΑΜΚΑ;", "Hat er eine AMKA-Nummer?", "¿Tiene número AMKA?", "Does he have an AMKA number?", "—Échi ÁMKA?"),
    Z("—Όχι, είναι τουρίστας. Έχει την ευρωπαϊκή κάρτα ασφάλισης υγείας.", "Nein, er ist Tourist. Er hat die Europäische Krankenversicherungskarte.", "No, es turista. Tiene la tarjeta sanitaria europea.", "No, he's a tourist. He's got the European Health Insurance Card.", "...tin evropaikí kárta asfálisis iyías."),
    N("Die Frage nach der AMKA. Im Oktober hatte Emma sie nicht verstanden. Heute hatte sie die Antwort, bevor die Frage zu Ende war.",
      "La pregunta del AMKA. En octubre, Emma no la había entendido. Hoy tenía la respuesta antes de que terminara la pregunta.",
      "The AMKA question. In October Emma hadn't understood it. Today she had the answer before the question was finished."),
    Z("—Εντάξει, το σημειώνω. Θα κάνουμε μια ακτινογραφία, για να είμαστε σίγουροι.", "Gut, ich notiere es. Wir machen ein Röntgenbild, um sicherzugehen.", "De acuerdo, lo apunto. Vamos a hacer una radiografía, para estar seguros.", "All right, I'll make a note of that. We'll do an X-ray, to be on the safe side.", "—Endáxi, to simióno. Tha kánoume mia aktinografía..."),
    Z("Μετά από μισή ώρα η γιατρός γύρισε με την ακτινογραφία.", "Nach einer halben Stunde kam die Ärztin mit dem Röntgenbild zurück.", "Media hora después, la médica volvió con la radiografía.", "Half an hour later the doctor came back with the X-ray."),
    Z("—Καλά νέα. Δεν έσπασε τίποτα. Είναι μια θλάση. Θα κρατάει το χέρι σε αναρτήρα για μία εβδομάδα και θα βάζει πάγο τρεις φορές τη μέρα.", "Gute Nachrichten. Es ist nichts gebrochen. Es ist eine Prellung. Er muss den Arm eine Woche in einer Schlinge tragen und dreimal am Tag Eis auflegen.", "Buenas noticias. No se ha roto nada. Es una contusión. Tendrá que llevar el brazo en cabestrillo una semana y ponerse hielo tres veces al día.", "Good news. Nothing's broken. It's a bad bruise. He'll keep his arm in a sling for a week and put ice on it three times a day.", "—Kalá néa. Den éspase típota. Íne mia thlási... se anartíra..."),
    Z("—Και για τον πόνο;", "Und gegen die Schmerzen?", "¿Y para el dolor?", "And for the pain?"),
    Z("—Σας γράφω ένα παυσίπονο. Χωρίς πενικιλίνη, μην ανησυχείτε. Περαστικά!", "Ich verschreibe Ihnen ein Schmerzmittel. Ohne Penicillin, keine Sorge. Gute Besserung!", "Le receto un analgésico. Sin penicilina, no se preocupe. ¡Que se mejore!", "I'll prescribe a painkiller. No penicillin, don't worry. Get well soon!", "...éna pafsípono... min anisichíte. Perastiká!"),
    N("Vor dem Krankenhaus saß ihr Vater auf einer Bank, den Arm in der Schlinge, und schüttelte den Kopf. Vierzig Jahre Straßenbahn in Wien. Glatteis, Schneematsch, die Kurve am Schottentor. Nie war er gestürzt. Und dann eine einzige Nacht in einer griechischen Kirche.",
      "Delante del hospital, su padre estaba sentado en un banco, con el brazo en cabestrillo, negando con la cabeza. Cuarenta años de tranvía en Viena. Hielo, nieve sucia, la curva del Schottentor. Nunca se había caído. Y luego, una sola noche en una iglesia griega.",
      "Outside the hospital her father sat on a bench, arm in a sling, shaking his head. Forty years of trams in Vienna. Black ice, slush, the bend at Schottentor. He had never fallen. And then one single night in a Greek church."),
    Z("Ο Φέλιξ έβγαλε μια φωτογραφία για την τάξη του. Ο πατέρας του χαμογέλασε. Δεν έσπασε τίποτα. Αυτό ήταν το πιο ωραίο δώρο του Πάσχα.", "Felix machte ein Foto für seine Klasse. Sein Vater lächelte. Es war nichts gebrochen. Das war das schönste Ostergeschenk.", "Felix hizo una foto para su clase. Su padre sonrió. No se había roto nada. Ese fue el mejor regalo de Pascua.", "Felix took a photo for his class. His father smiled. Nothing was broken. That was the best Easter present of all.")
  ]),

  // ── Station 20 · FAMILIE (A2) ─────────────────────────────────────────
  S("aufbau", 20, "familie", "Μου λείπεις",
    "Der letzte Abend: alle in Roulas Hof, Aprikosen aus der Wachau, Feigen aus der Chalkidiki — und ein griechischer Satz, in dem nicht ich vermisse, sondern du fehlst.",
    "La última noche: todos en el patio de Rula, albaricoques del Wachau, higos de Calcídica… y una frase griega en la que no eres tú quien echa de menos: es el otro quien te falta.",
    "The last evening: everyone in Roula's courtyard, apricots from the Wachau, figs from Halkidiki — and a Greek phrase in which you don't miss someone: they are missing to you.",
  [
    Z("Το τελευταίο βράδυ η οικογένεια έφαγε στην αυλή της κυρίας Ρούλας. Αυτή τη φορά ήρθαν όλοι.", "Am letzten Abend aß die Familie in Frau Roulas Hof. Diesmal kamen alle.", "La última noche, la familia cenó en el patio de la señora Rula. Esta vez vinieron todos.", "On the last evening the family ate in Mrs Roula's courtyard. This time everyone came."),
    N("Herr Thanasis, mit Komboloi und einer Flasche Tsipouro. Marina von der Uni, mit einer Schachtel Trigona aus der Konditorei — zweimal geprüft: ohne Nüsse. Stelios, nach der Schicht, im PAOK-Schal. Und Frau Roula, die für zwanzig gekocht hatte, obwohl sie zu acht waren. Ihr Vater saß mit dem Arm in der Schlinge am Kopfende, wie ein verwundeter General.",
      "El señor Thanasis, con su komboloi y una botella de tsipouro. Marina, de la universidad, con una caja de trígona de la pastelería, comprobados dos veces: sin frutos secos. Stelios, después de su turno, con la bufanda del PAOK. Y la señora Rula, que había cocinado para veinte aunque eran ocho. Su padre, con el brazo en cabestrillo, presidía la mesa como un general herido.",
      "Mr Thanasis, with his komboloi and a bottle of tsipouro. Marina from the university, with a box of trigona from the patisserie — checked twice: no nuts. Stelios, after his shift, in his PAOK scarf. And Mrs Roula, who had cooked for twenty although there were eight of them. Her father sat at the head of the table with his arm in a sling, like a wounded general."),
    Z("Μετά το φαγητό, η Μαρίνα ρώτησε την Έμμα:", "Nach dem Essen fragte Marina Emma:", "Después de cenar, Marina le preguntó a Emma:", "After the meal Marina asked Emma:"),
    Z("—Έμμα, πού μεγάλωσες; Στη Βιέννη;", "Emma, wo bist du aufgewachsen? In Wien?", "Emma, ¿dónde te criaste? ¿En Viena?", "Emma, where did you grow up? In Vienna?", "—Émma, poú megáloses? Sti Viénni?"),
    Z("—Ναι. Μέναμε σε ένα διαμέρισμα στον τρίτο όροφο, χωρίς ασανσέρ. Αλλά τα καλοκαίρια πηγαίναμε στους παππούδες μου, στη Βαχάου, δίπλα στον Δούναβη.", "Ja. Wir wohnten in einer Wohnung im dritten Stock, ohne Aufzug. Aber im Sommer fuhren wir zu meinen Großeltern in die Wachau, an die Donau.", "Sí. Vivíamos en un piso en la tercera planta, sin ascensor. Pero en verano íbamos a casa de mis abuelos, en el Wachau, junto al Danubio.", "Yes. We lived in a flat on the third floor, no lift. But in the summers we went to my grandparents' in the Wachau, by the Danube.", "...ta kalokéria piyéname stous pappoúdes mou..."),
    Z("—Και τι κάνατε εκεί;", "Und was habt ihr dort gemacht?", "¿Y qué hacíais allí?", "And what did you do there?"),
    Z("—Ο παππούς μου είχε βερικοκιές. Μαζεύαμε βερίκοκα όλη μέρα και τρώγαμε μέχρι να πονέσει η κοιλιά μας.", "Mein Großvater hatte Aprikosenbäume. Wir pflückten den ganzen Tag Aprikosen und aßen, bis uns der Bauch wehtat.", "Mi abuelo tenía albaricoqueros. Recogíamos albaricoques todo el día y comíamos hasta que nos dolía la barriga.", "My grandfather had apricot trees. We picked apricots all day and ate them till our tummies hurt.", "...Mazévame veríkoka óli méra ke trógame..."),
    Z("—Κι εμείς το ίδιο! —είπε η κυρία Ρούλα—. Όταν ήμουν μικρή, πήγαινα κάθε καλοκαίρι στη γιαγιά μου στη Χαλκιδική. Είχε συκιές. Τα σύκα ήταν σαν μέλι.", "Bei uns genauso!, sagte Frau Roula. Als ich klein war, fuhr ich jeden Sommer zu meiner Großmutter auf die Chalkidiki. Sie hatte Feigenbäume. Die Feigen waren wie Honig.", "¡Nosotros igual!, dijo la señora Rula. Cuando era pequeña, cada verano iba a casa de mi abuela, en Calcídica. Tenía higueras. Los higos eran como miel.", "Same with us! said Mrs Roula. When I was little, I went to my grandmother's in Halkidiki every summer. She had fig trees. The figs were like honey.", "...Ótan ímoun mikrí, píyena..."),
    Z("—Και εσύ, Στέλιο; —ρώτησε ο Φέλιξ. Το είχε εξασκήσει όλη την εβδομάδα.", "Und du, Stelios?, fragte Felix. Er hatte es die ganze Woche geübt.", "¿Y tú, Stelios?, preguntó Felix. Lo había practicado toda la semana.", "And you, Stelios? asked Felix. He had been practising it all week."),
    Z("—Εγώ; Μεγάλωσα στην Τούμπα, δίπλα στο γήπεδο του ΠΑΟΚ. Τα καλοκαίρια μου ήταν όλα ασπρόμαυρα.", "Ich? Ich bin in Toumba aufgewachsen, neben dem PAOK-Stadion. Meine Sommer waren alle schwarz-weiß.", "¿Yo? Me crie en Toumba, al lado del estadio del PAOK. Todos mis veranos fueron en blanco y negro.", "Me? I grew up in Toumba, next to the PAOK ground. All my summers were black and white.", "...Ta kalokéria mou ítan óla asprómavra."),
    N("Alle lachten. Marina übersetzte für Brigitte, Emma für ihren Vater, Felix für niemanden. Dann räusperte sich ihr Vater. Er sprach langsam, Wort für Wort, mit den Sätzen, die er heimlich auf dem Handy geübt hatte.",
      "Todos se rieron. Marina traducía para Brigitte, Emma para su padre, Felix para nadie. Entonces su padre carraspeó. Habló despacio, palabra por palabra, con las frases que había practicado a escondidas en el móvil.",
      "Everyone laughed. Marina translated for Brigitte, Emma for her father, Felix for nobody. Then her father cleared his throat. He spoke slowly, word by word, with the sentences he had secretly practised on his phone."),
    Z("—Όταν η Έμμα ήταν μικρή… έσκαβε. Στον κήπο του παππού. Βρήκε ένα κουμπί. Είπε: «Ρωμαϊκό!»", "Als Emma klein war … grub sie. Im Garten vom Großvater. Sie fand einen Knopf. Sie sagte: »Römisch!«", "Cuando Emma era pequeña… cavaba. En el jardín del abuelo. Encontró un botón. Dijo: «¡Romano!».", "When Emma was little… she used to dig. In her grandfather's garden. She found a button. She said: “Roman!”", "—Ótan i Émma ítan mikrí… éskave... Romaikó!"),
    Z("—Γι' αυτό έγινε αρχαιολόγος! —φώναξε η Μαρίνα.", "Darum ist sie Archäologin geworden!, rief Marina.", "¡Por eso se hizo arqueóloga!, exclamó Marina.", "That's why she became an archaeologist! cried Marina.", "—Gi' aftó éyine archeológos!"),
    N("Und Emma, die Frau, die vor keinem griechischen Schalter mehr Angst hatte, wurde rot wie ein Osterei.",
      "Y Emma, la mujer a la que ya no le daba miedo ningún mostrador griego, se puso roja como un huevo de Pascua.",
      "And Emma, the woman no longer afraid of any Greek counter, turned as red as an Easter egg."),
    Z("Αργότερα, στο μπαλκόνι, η Μαρίνα τη ρώτησε πιο σιγά:", "Später, auf dem Balkon, fragte Marina sie leiser:", "Más tarde, en el balcón, Marina le preguntó en voz más baja:", "Later, on the balcony, Marina asked her more quietly:"),
    Z("—Σου λείπει η Βιέννη;", "Fehlt dir Wien?", "¿Te hace falta Viena?", "Do you miss Vienna?", "—Sou lípi i Viénni?"),
    N("Emma dachte nach. An die Aprikosenbäume im Juli. An die 43er am Sonntagmorgen. An den Duft der Kaffeehäuser. Dann sah sie sich um: das Tsipouro, die roten Eier, das Komboloi, unten im Hof ihr Vater mit dem Arm in der Schlinge, der mit Frau Roula zu tanzen versuchte.",
      "Emma se lo pensó. En los albaricoqueros en julio. En el tranvía 43 un domingo por la mañana. En el olor de los cafés vieneses. Luego miró a su alrededor: el tsipouro, los huevos rojos, el komboloi y, abajo en el patio, su padre con el brazo en cabestrillo intentando bailar con la señora Rula.",
      "Emma thought about it. About the apricot trees in July. About the number 43 on a Sunday morning. About the smell of the coffee houses. Then she looked around: the tsipouro, the red eggs, the komboloi, and down in the courtyard her father, arm in a sling, trying to dance with Mrs Roula."),
    Z("—Ναι. Μερικές φορές μου λείπει. Αλλά κι εδώ είμαι στο σπίτι μου.", "Ja. Manchmal fehlt es mir. Aber auch hier bin ich zu Hause.", "Sí. A veces me hace falta. Pero aquí también estoy en casa.", "Yes. Sometimes I miss it. But I'm at home here too.", "—Ne. Merikés forés mou lípi..."),
    Z("Το επόμενο πρωί ο Στέλιος πήγε την οικογένεια στο αεροδρόμιο. Χωρίς ταξίμετρο. Το βράδυ το σπίτι ήταν πολύ ήσυχο. Η Έμμα έγραψε ένα μήνυμα στη μητέρα της:", "Am nächsten Morgen fuhr Stelios die Familie zum Flughafen. Ohne Taxameter. Am Abend war es in der Wohnung sehr still. Emma schrieb ihrer Mutter eine Nachricht:", "A la mañana siguiente, Stelios llevó a la familia al aeropuerto. Sin taxímetro. Por la noche, la casa estaba muy silenciosa. Emma le escribió un mensaje a su madre:", "The next morning Stelios drove the family to the airport. No meter. That evening the flat was very quiet. Emma wrote her mother a message:"),
    Z("«Μου λείπετε.»", "»Ihr fehlt mir.«", "«Me hacéis falta».", "“I miss you all.”", "Mou lípete."),
    N("Auf Deutsch vermisst man jemanden: Ich bin es, die vermisst. Auf Griechisch ist es umgekehrt. Μου λείπεις heißt: Du fehlst mir. Du bist das Subjekt, du bist es, der fehlt — mir. Wie im Spanischen: me haces falta. Im Mittelpunkt steht der, der fehlt. Emma fand, dass die Griechen recht hatten.",
      "En alemán uno vermisst a alguien, lo echa de menos: soy yo quien echa de menos. En griego es al revés. Μου λείπεις significa: tú me faltas. Tú eres el sujeto, tú eres quien falta… a mí. Igual que en español: me haces falta. En el centro está quien falta. Emma pensó que los griegos tenían razón.",
      "In English you miss someone: I'm the one doing the missing. In Greek it's the other way round. Μου λείπεις means: you are missing to me. You are the subject, you are the one who is missing — from me. Like the Spanish me haces falta. The one who is missing is at the centre. Emma thought the Greeks had it right."),
    N("Und dann, ganz plötzlich, ein zweiter Gedanke. Im Juli würde sie nach Wien zurückfliegen. Und dann würde ihr etwas anderes fehlen. Ein Kafeneio. Ein Balkon. Ein Berg mit Hut.",
      "Y entonces, de repente, otra idea. En julio volvería a Viena. Y entonces le faltaría otra cosa. Un café de barrio. Un balcón. Una montaña con sombrero.",
      "And then, quite suddenly, a second thought. In July she would fly back to Vienna. And then something else would be missing to her. A kafeneio. A balcony. A mountain wearing a hat."),
    Z("«Θα μου λείπει η Θεσσαλονίκη.»", "»Thessaloniki wird mir fehlen.«", "«Tesalónica me hará falta».", "“I'll miss Thessaloniki.”", "Tha mou lípi i Thessaloníki.")
  ]),

  /* ═════════════════════════════════════════════════════════════════════
     EPILOG · ANWENDUNG · ganz auf Griechisch, ohne Brücke, ohne Umschrift
     Jede Figur kommt noch einmal vorbei; der Schluss spiegelt Station 1.
     ═════════════════════════════════════════════════════════════════════ */
  S("anwendung", 21, null, "Θα τα πούμε",
    "Juli. Die letzte Woche in Thessaloniki: ein Anruf aus Veria, ein letzter Frappé — und eine Taxifahrt, die dort endet, wo alles anfing. Ganz auf Griechisch.",
    "Julio. La última semana en Tesalónica: una llamada desde Veria, un último frapé y un taxi que termina donde empezó todo. Todo en griego.",
    "July. The last week in Thessaloniki: a phone call from Veria, one last frappé — and a taxi ride that ends where it all began. Entirely in Greek.",
  [
    P("Ο Ιούλιος ήρθε στη Θεσσαλονίκη όπως έρχονται όλα εδώ: σιγά-σιγά, και μετά ξαφνικά. Στις δέκα το πρωί η θερμοκρασία ήταν ήδη τριάντα βαθμοί. Η παραλία ήταν γεμάτη ποδήλατα και παγωτά, και κάθε απόγευμα, στις πέντε ακριβώς, ερχόταν από τη θάλασσα η μπουκαδούρα. Η κυρία Ρούλα δεν χρειαζόταν πια να την προβλέψει. Την ήξερε και η Έμμα."),
    P("Η βαλίτσα της ήταν ανοιχτή στο πάτωμα εδώ και τρεις μέρες. Μέσα είχε βιβλία, σημειώσεις, ένα κομπολόι από τον κυρ-Θανάση και δύο κουτιά λουκούμια για τον Φέλιξ, χωρίς ξηρούς καρπούς. Δεν την έκλεινε. Το ήξερε κι η ίδια: μια βαλίτσα που δεν κλείνει είναι μια απόφαση που δεν έχει παρθεί ακόμα."),
    P("Η ερευνητική της χρονιά στο Αριστοτέλειο είχε τελειώσει. Την προηγούμενη εβδομάδα είχε παρουσιάσει τη δουλειά της: τα βυζαντινά ευρήματα κάτω από τους δρόμους της πόλης, εκεί που χρόνια έσκαβαν για το μετρό. Στο τέλος, ο καθηγητής της πρότεινε ένα καινούριο πρόγραμμα από τον Ιανουάριο. Η Έμμα είπε ότι θα το σκεφτεί. Στα ελληνικά αυτό μπορεί να σημαίνει «όχι». Μπορεί όμως να σημαίνει και «ναι, αλλά σιγά-σιγά»."),
    P("Η Μαρίνα τη συνόδευσε μέχρι την έξοδο του πανεπιστημίου."),
    P("—Μην ξεχάσεις να κλείσεις το ΑΦΜ σου πριν φύγεις. Πλάκα κάνω. Το ΑΦΜ δεν κλείνει ποτέ. Είναι για πάντα, σαν τον γάμο. Πιο πολύ από τον γάμο."),
    P("Το Σάββατο το πρωί χτύπησε το κινητό. Στην οθόνη έγραφε: «Κυρία Βούλα». Η Έμμα παραλίγο να το ρίξει κάτω. Σε εννιά μήνες η κυρία Βούλα δεν είχε τηλεφωνήσει ούτε μία φορά. Συνήθως δεν απαντούσε καν."),
    P("—Έμμα; Η Βούλα είμαι, από τη Βέροια. Μου είπε η Δέσποινα από τη λαϊκή ότι φεύγεις. Άκου: το σπίτι μένει δικό σου. Αν γυρίσεις, δεν θα ψάξεις σπίτι. Και το συμβόλαιο θα το ξαναϋπογράψω. Με το ίδιο στυλό."),
    P("Και έκλεισε. Η κυρία Βούλα δεν έλεγε ποτέ αντίο στο τηλέφωνο. Απλώς έκλεινε, σαν να επρόκειτο να ξαναμιλήσουν σε πέντε λεπτά."),
    P("Στη λαϊκή, η κυρία Δέσποινα της γέμισε μια σακούλα με ροδάκινα χωρίς να ρωτήσει. Η Έμμα πλήρωσε, και η κυρία Δέσποινα της έβαλε τα ρέστα πίσω στην τσέπη. Μετά της έδωσε και ένα πεπόνι. Για το αεροπλάνο, είπε. Η Έμμα δεν ρώτησε πώς θα περάσει ένα πεπόνι από τον έλεγχο."),
    P("Το απόγευμα, η κυρία Ρούλα της έφερε γεμιστά σε ένα ταπεράκι."),
    P("—Για το ταξίδι. Και αύριο θα έχει καλό καιρό. Ο Όλυμπος δεν φοράει καπέλο και η θάλασσα είναι λάδι. Καλή μέρα για να πετάξεις."),
    P("Την Πέμπτη το πρωί, η Έμμα κατέβηκε για τελευταία φορά στο καφενείο. Ο κυρ-Θανάσης δεν τη ρώτησε τι θα πάρει. Της έφερε έναν φραπέ, μέτριο με γάλα, και κάθισε απέναντί της με το κομπολόι του."),
    P("—Ο τελευταίος —είπε η Έμμα."),
    P("—Θα δούμε —είπε ο κυρ-Θανάσης."),
    P("Όταν η Έμμα έβγαλε το πορτοφόλι, εκείνος σήκωσε το πηγούνι και έκανε «τσκ». Πριν από εννιά μήνες η Έμμα δεν θα καταλάβαινε. Τώρα ήξερε: εδώ δεν πληρώνεις."),
    P("—Κερασμένος. Και όταν γυρίσεις, πάλι κερασμένος."),
    P("Μπροστά στο σπίτι περίμενε ένα ταξί. Η Έμμα δεν είχε τηλεφωνήσει σε κανέναν. Ο Στέλιος στεκόταν ακουμπισμένος στην πόρτα, με το ραδιόφωνο ανοιχτό. Στον καθρέφτη κρεμόταν, όπως πάντα, το ασπρόμαυρο κασκόλ."),
    P("—Μου το είπε η κυρία Ρούλα —εξήγησε, και έβαλε τη βαλίτσα στο πορτμπαγκάζ σαν να ήταν άδεια."),
    P("Ο δρόμος για το αεροδρόμιο ήταν άδειος, αλλά ο Στέλιος οδηγούσε αργά, πολύ αργά, από την παραλία. Από το παράθυρο περνούσαν μέρη που η Έμμα πια ήξερε: ο Λευκός Πύργος, ο δρόμος για τη Ροτόντα, η Καμάρα, η Αγίας Σοφίας. Ευθεία, δεξιά, στο φανάρι αριστερά. Η Θεσσαλονίκη δεν ήταν πια ένας χάρτης. Ήταν δρόμοι με πρόσωπα."),
    P("—Ξέρεις τι είπε ο Ηράκλειτος;"),
    P("—«Τα πάντα ρει». Το ξέρω, Στέλιο. Εκτός από την κίνηση."),
    P("—Όχι, όχι. Είπε κι άλλο. «Δεν μπορείς να μπεις δύο φορές στο ίδιο ποτάμι.» Δηλαδή, όταν γυρίσεις, η Θεσσαλονίκη θα είναι άλλη. Κι εσύ θα είσαι άλλη. Μόνο ο ΠΑΟΚ θα είναι ο ίδιος."),
    P("Στις αναχωρήσεις, ο Στέλιος σταμάτησε το ταξίμετρο. Η Έμμα έβγαλε το πορτοφόλι."),
    P("—Πόσο κάνει;"),
    P("—Σήμερα τίποτα, Αυστριακή. Αλλά θέλω κάτι: όταν γυρίσεις, θα πάρεις εμένα. Κανέναν άλλον."),
    P("Και μετά, χωρίς να πει λέξη, έγραψε μια απόδειξη και της την έδωσε. Μηδέν ευρώ. Από κάτω, με μεγάλα γράμματα: «Για τον πατέρα σου»."),
    P("Η Έμμα γέλασε και τον αγκάλιασε. Ο Στέλιος μύριζε λεμόνι και λίγο καφέ, όπως το ταξί του. Την πρώτη μέρα, τον Οκτώβριο, είχε μπει σε αυτό το ταξί και δεν καταλάβαινε τίποτα: ούτε την πόλη, ούτε τους ανθρώπους, ούτε γιατί το «ναι» ακούγεται σαν «όχι». Τώρα καταλάβαινε σχεδόν τα πάντα. Μόνο τον ΠΑΟΚ δεν καταλάβαινε ακόμα."),
    P("Στην πόρτα της αίθουσας γύρισε πίσω. Ο Στέλιος στεκόταν δίπλα στο ταξί, με το χέρι σηκωμένο. Η Έμμα έψαξε τη σωστή λέξη. Το «αντίο» ακουγόταν σαν πόρτα που κλείνει. Το «γεια σου» ήταν πολύ μικρό για εννιά μήνες. Και τότε θυμήθηκε τι έλεγαν όλοι εδώ, κάθε μέρα, στο καφενείο, στη λαϊκή, στη σκάλα: κανείς δεν αποχαιρετούσε. Όλοι έλεγαν το ίδιο."),
    P("—Θα τα πούμε, Στέλιο!"),
    P("—Θα τα πούμε, Έμμα!"),
    P("Θα τα πούμε: θα πούμε τα πράγματα. Αυτά που δεν προλάβαμε, αυτά που θα γίνουν, αυτά που δεν ξέρουμε ακόμα. Στα ελληνικά δεν αποχαιρετάς κάποιον. Του υπόσχεσαι την επόμενη κουβέντα.")
  ])

  ];
})(window);

